// StayTW Study — TOCFL Level 4 文法
// 正本: 國家教育研究院「臺灣華語文能力基準(TBCL)」語法點表 496 点。
//   第4級 の点をそのまま並べ、最後に官方の表に無い点(書面語・進階)を足している。
//   語法點名(t)と1つ目の例文は官方のまま。説明と訳と2つ目の例文はこちらで書いた。
//   作り直し: node scripts/gen-grammar.mjs → node scripts/build-grammar.mjs
// 形式: id, cat, t=語法點名, g=一言の意味, p=文型, ex=解説, eg=例文[{z,py,j,e,k}]
const GRAMMAR_L4 = [
{"id":"g4-242","cat":"助動詞","t":"可1","g":{"j":"〜してよい（書き言葉の可以）","e":"may / be allowed to (formal written \"可以\")","k":"~해도 된다 (문어체 可以)"},"p":{"j":"（不）可 ＋ 動詞句","e":"(bù) kě + VP","k":"（不）可 ＋ 동사구"},"ex":{"j":"「可」は書き言葉で「可以」と同じ「〜してよい」を表す。規則・掲示・お知らせなどのフォーマルな文でよく使われる。話し言葉では普通「可以」を使うので混同しないこと。","e":"\"可\" is the formal written equivalent of \"可以\" (\"may/can\"), common in rules, notices, and official texts. In everyday speech, use \"可以\" instead — mixing them up sounds unnatural.","k":"「可」는 문어체에서 「可以」와 같은 뜻으로 「~해도 된다」를 나타내며 규정이나 공지 등 공식적인 글에 자주 쓰인다. 구어에서는 보통 「可以」를 쓰므로 혼동하지 않도록 주의한다."},"eg":[{"z":"一般民眾不<em>可</em>免費使用本校的游泳池。","py":"Yìbān mínzhòng bù kě miǎnfèi shǐyòng běn xiào de yóuyǒngchí.","j":"一般の人は本校のプールを無料で使うことはできません。","e":"The general public may not use this school's swimming pool for free.","k":"일반인은 본교의 수영장을 무료로 이용할 수 없습니다."},{"z":"圖書館內不<em>可</em>大聲喧嘩。","py":"Túshūguǎn nèi bù kě dàshēng xuānhuá.","j":"図書館内では大声で騒いではいけません。","e":"Loud talking is not permitted inside the library.","k":"도서관 안에서는 큰 소리로 떠들면 안 됩니다."}]},
{"id":"g4-243","cat":"助動詞","t":"可2","g":{"j":"〜できる（書き言葉の能力表現）","e":"can / be able to (formal written ability)","k":"~할 수 있다 (문어체 능력 표현)"},"p":{"j":"可 ＋ 動詞句（能力を表す）","e":"kě + VP (expressing ability)","k":"可 ＋ 동사구 (능력을 나타냄)"},"ex":{"j":"「可2」は能力を表す書き言葉で「能/可以」に近い。「不但可…還能…」のように能力を列挙する文でよく使う。許可を表す「可1」との違いは、ここでは「できる」の意味であること。","e":"\"可2\" expresses ability in formal writing, similar to \"能/可以\". It often appears in \"不但可...還能...\" patterns listing abilities. Unlike \"可1\" (permission), here it means capability, not being allowed.","k":"「可2」는 문어체에서 능력을 나타내며 「能/可以」와 비슷하다. 「不但可…還能…」처럼 여러 능력을 나열할 때 자주 쓴다. 허가를 뜻하는 「可1」과 달리 여기서는 「할 수 있다」는 능력을 의미한다."},"eg":[{"z":"他不但<em>可</em>理解老師上課的內容，還能說出重點。","py":"Tā bùdàn kě lǐjiě lǎoshī shàngkè de nèiróng, hái néng shuōchū zhòngdiǎn.","j":"彼は先生の授業内容を理解できるだけでなく、要点も言うことができる。","e":"He can not only understand what the teacher covers in class but also point out the key ideas.","k":"그는 선생님의 수업 내용을 이해할 수 있을 뿐만 아니라 요점도 말할 수 있다."},{"z":"這個軟體不但<em>可</em>翻譯文章，還能修改文法錯誤。","py":"Zhège ruǎntǐ bùdàn kě fānyì wénzhāng, hái néng xiūgǎi wénfǎ cuòwù.","j":"このソフトは文章を翻訳できるだけでなく、文法の誤りも直せる。","e":"This software can not only translate articles but also fix grammar mistakes.","k":"이 소프트웨어는 글을 번역할 수 있을 뿐만 아니라 문법 오류도 고칠 수 있다."}]},
{"id":"g4-244","cat":"助動詞","t":"可3","g":{"j":"〜につながる／〜できる（事柄が結果をもたらす）","e":"can (lead to) — an action/fact making a result possible","k":"~할 수 있다 (어떤 일이 결과를 가져올 수 있음)"},"p":{"j":"（行為・事柄）＋ 可 ＋ 動詞句（結果）","e":"(action/fact) + kě + VP (result)","k":"(행위·사실) ＋ 可 ＋ 동사구 (결과)"},"ex":{"j":"「可3」は人ではなく行為・事柄を主語にして「(それをすると)〜という結果になりうる」ことを表す書き言葉。能力を表す「可2」とは違い、主語は人ではなく行為である点に注意。","e":"\"可3\" is used when the subject is an action or fact (not a person), meaning \"doing this can lead to...\". Unlike \"可2\" (personal ability), the subject here is an event, and \"可\" shows its potential effect.","k":"「可3」은 사람이 아니라 행위나 사실을 주어로 하여 「(이렇게 하면) ~라는 결과를 가져올 수 있다」는 뜻을 나타내는 문어체다. 능력을 뜻하는 「可2」와 달리 주어가 사람이 아닌 행위라는 점에 주의한다."},"eg":[{"z":"做好資源回收<em>可</em>改善環境。","py":"Zuò hǎo zīyuán huíshōu kě gǎishàn huánjìng.","j":"資源回収をしっかり行えば、環境を改善できる。","e":"Doing recycling properly can improve the environment.","k":"자원 재활용을 잘하면 환경을 개선할 수 있다."},{"z":"多喝水<em>可</em>預防感冒。","py":"Duō hē shuǐ kě yùfáng gǎnmào.","j":"水をたくさん飲むと風邪の予防になる。","e":"Drinking more water can help prevent colds.","k":"물을 많이 마시면 감기를 예방할 수 있다."}]},
{"id":"g4-245","cat":"助動詞","t":"該1","g":{"j":"〜すべきだ","e":"should / ought to","k":"~해야 한다"},"p":{"j":"（不）該 ＋ 動詞句","e":"(bù) gāi + VP","k":"（不）該 ＋ 동사구"},"ex":{"j":"「該」は「〜すべきだ」という義務・当然を表し、「應該」の口語的な短縮形に近い。未来の予測を表す「會」と混同しないよう注意。","e":"\"該\" means \"should/ought to\", expressing obligation or what's proper — a shortened, more colloquial form close to \"應該\". Don't confuse it with \"會\" (will/likely), which expresses prediction, not obligation.","k":"「該」는 「~해야 한다」는 의무·당위를 나타내며 「應該」의 구어적 축약형에 가깝다. 예측을 나타내는 「會」와 혼동하지 않도록 주의한다."},"eg":[{"z":"我們平常不<em>該</em>吃太鹹的食物。","py":"Wǒmen píngcháng bù gāi chī tài xián de shíwù.","j":"私たちは普段、塩辛すぎる食べ物を食べるべきではない。","e":"We shouldn't normally eat overly salty food.","k":"우리는 평소에 너무 짠 음식을 먹지 말아야 한다."},{"z":"你身體不舒服，<em>該</em>去看醫生了。","py":"Nǐ shēntǐ bù shūfu, gāi qù kàn yīshēng le.","j":"体調が悪いなら、医者に診てもらうべきだよ。","e":"If you're not feeling well, you should go see a doctor.","k":"몸이 안 좋으면 병원에 가봐야 해."}]},
{"id":"g4-246","cat":"助動詞","t":"該2","g":{"j":"~すべきだ／そろそろ~しなければ","e":"should / it's time to","k":"~해야 한다"},"p":{"j":"(主語)＋該＋動詞(＋了)","e":"Subject + 該 + Verb (+ 了)","k":"주어 + 該 + 동사(+了)"},"ex":{"j":"「該」は「應該」の口語的な短縮形で、状況から見て「そろそろ~すべき」という判断を表す。文末の「了」とセットで使うことが多く、「そのタイミングが来た」という含みが出る。「應該」ほど硬くなく会話でよく使われる。","e":"\"該\" is a colloquial, shortened form of \"應該,\" expressing that circumstances now call for an action. It often pairs with sentence-final \"了\" to signal \"the time has come.\" Learners sometimes drop the \"了\" and lose that nuance, or confuse it with \"會\" (will happen) rather than \"should.\"","k":"「該」는「應該」의 구어체 축약형으로, 상황상 \"이제 ~해야 한다\"는 판단을 나타낸다. 문장 끝의 「了」와 함께 쓰여 \"그 시점이 됐다\"는 뉘앙스를 준다. 「應該」보다 부드럽고 회화체에 자주 쓰인다."},"eg":[{"z":"時間不早了，我<em>該</em>回家了。","py":"Shíjiān bù zǎo le, wǒ gāi huíjiā le.","j":"時間ももう遅いから、そろそろ家に帰らないと。","e":"It's getting late, I should head home now.","k":"시간이 많이 늦었으니, 나는 이제 집에 가야겠다."},{"z":"已經十二點了，我們<em>該</em>吃飯了。","py":"Yǐjīng shí'èr diǎn le, wǒmen gāi chīfàn le.","j":"もう12時になったから、そろそろご飯を食べないと。","e":"It's already 12 o'clock, we should eat now.","k":"벌써 12시가 됐으니, 우리는 이제 밥을 먹어야겠다."}]},
{"id":"g4-247","cat":"補語","t":"V出2","g":{"j":"~し出す／考え出す(結果補語「出」)","e":"to produce/come up with (resultative complement 出)","k":"~해내다／생각해내다(결과보어 出)"},"p":{"j":"動詞＋出＋(目的語)","e":"Verb + 出 + (Object)","k":"동사 + 出 + (목적어)"},"ex":{"j":"ここでの「出」は物理的に外に出る意味ではなく、「無から有を生み出す」という結果補語で、「想出(考え出す)」「提出(提出する)」「找出(見つけ出す)」のように抽象的な思考の産出を表す。初級で習う「走出去」のような移動の「出」と混同しないよう注意。","e":"Here \"出\" is a resultative complement meaning \"to bring something into existence,\" used with verbs like 想出 (think up), 提出 (propose), 找出 (find out) for abstract, mental results — not physical movement outward. Learners often confuse it with the literal \"exit\" sense of 出 in verbs like 走出去.","k":"여기서의 「出」는 물리적으로 밖으로 나간다는 뜻이 아니라 \"무에서 유를 만들어낸다\"는 결과보어로, 「想出(생각해내다)」「提出(제기하다)」「找出(찾아내다)」처럼 추상적인 사고의 산출을 나타낸다. 「走出去」같은 이동의 「出」와 혼동하지 않도록 주의."},"eg":[{"z":"在重要時刻他總能<em>提出</em>有用的想法或辦法。","py":"Zài zhòngyào shíkè tā zǒng néng tíchū yǒuyòng de xiǎngfǎ huò bànfǎ.","j":"重要な場面で彼はいつも役に立つ考えや方法を提出できる。","e":"At key moments, he can always come up with useful ideas or solutions.","k":"중요한 순간에 그는 항상 유용한 생각이나 방법을 내놓을 수 있다."},{"z":"經過討論，我們終於<em>想出</em>解決的辦法。","py":"Jīngguò tǎolùn, wǒmen zhōngyú xiǎngchū jiějué de bànfǎ.","j":"話し合いを経て、私たちはついに解決策を考え出した。","e":"After discussing it, we finally came up with a solution.","k":"논의를 거쳐, 우리는 마침내 해결 방법을 생각해냈다."}]},
{"id":"g4-248","cat":"副詞","t":"還3","g":{"j":"その上~もする／さらに~","e":"on top of that / also (unexpectedly)","k":"게다가 ~도 하다"},"p":{"j":"…，(時間/状況)＋還＋動詞","e":"..., (time/situation) + 還 + Verb","k":"…, (시간/상황) + 還 + 동사"},"ex":{"j":"この「還」は既に述べた状況に加えて、さらに別のことも行われることを示し、負担や意外性のニュアンスを伴うことが多い。「還」に「まだ~している」という継続の意味もあるため混同しないよう、文脈(すでに一つの事柄が提示されている点)で見分ける。","e":"This \"還\" adds an extra, often burdensome or unexpected item on top of a situation already mentioned. Since \"還\" can also mean \"still\" (continuation), tell them apart by context — here a first fact is already stated, and 還 introduces something additional.","k":"이 「還」는 이미 언급된 상황에 더해 또 다른 일이 추가로 일어남을 나타내며, 부담스럽거나 뜻밖이라는 뉘앙스를 동반하는 경우가 많다. 「還」에는 \"아직도 ~하다\"라는 지속의 의미도 있으므로, 이미 한 가지 사실이 제시된 문맥으로 구별해야 한다."},"eg":[{"z":"他白天上班，晚上<em>還</em>當家教，根本沒時間回信。","py":"Tā báitiān shàngbān, wǎnshang hái dāng jiājiào, gēnběn méi shíjiān huíxìn.","j":"彼は昼間は仕事をして、夜はさらに家庭教師もしているので、返信する時間が全然ない。","e":"He works during the day, and in the evening he also tutors, so he has no time at all to reply to messages.","k":"그는 낮에는 회사에 다니고, 저녁에는 과외까지 하느라 답장할 시간이 전혀 없다."},{"z":"她已經很忙了，週末<em>還</em>要去打工。","py":"Tā yǐjīng hěn máng le, zhōumò hái yào qù dǎgōng.","j":"彼女はもう十分忙しいのに、週末はさらにアルバイトに行かなければならない。","e":"She's already very busy, and on top of that she has to go work a part-time job on weekends.","k":"그녀는 이미 많이 바쁜데, 주말에는 아르바이트까지 하러 가야 한다."}]},
{"id":"g4-249","cat":"補語","t":"V起來4","g":{"j":"~のように見える／~そうだ","e":"seems / looks (like)","k":"~인 것 같다／~해 보인다"},"p":{"j":"(主語)＋看起來/聽起來＋形容詞","e":"Subject + 看起來/聽起來 + Adjective","k":"주어 + 看起來/聽起來 + 형용사"},"ex":{"j":"「V起來」がここでは「見た目/聞いた感じ~のようだ」という判断・印象を表す固定表現で、「看起來」「聽起來」など感覚動詞と結びつきやすい。物理的に「起き上がる」動作を表す用法や、「泣き出す」のように動作の開始を表す用法とは別なので注意。","e":"Here \"V起來\" (as in 看起來, 聽起來) forms a fixed expression meaning \"it appears/sounds like...\", expressing a judgment based on perception. It differs from the literal \"stand up\" sense of V起來 and the inchoative \"start doing\" sense (e.g., 哭起來, \"burst into tears\") — don't mix the uses up.","k":"여기서의 「V起來」는 「看起來」「聽起來」처럼 지각동사와 결합하여 \"보아하니/듣자하니 ~인 것 같다\"는 판단・인상을 나타내는 고정 표현이다. 물리적으로 \"일어나다\"를 뜻하는 용법이나, \"울기 시작하다\"처럼 동작의 시작을 나타내는 용법과는 다르므로 구별해야 한다."},"eg":[{"z":"你今天<em>看起來</em>很累。","py":"Nǐ jīntiān kànqǐlái hěn lèi.","j":"あなたは今日、とても疲れて見える。","e":"You look very tired today.","k":"너 오늘 아주 피곤해 보인다."},{"z":"這道菜<em>聞起來</em>很香，我想快點吃。","py":"Zhè dào cài wénqǐlái hěn xiāng, wǒ xiǎng kuàidiǎn chī.","j":"この料理はとてもいい匂いがして、早く食べたいと思う。","e":"This dish smells great, I want to eat it soon.","k":"이 요리는 냄새가 아주 좋아서, 나는 빨리 먹고 싶다."}]},
{"id":"g4-250","cat":"特殊構文","t":"不能不/不得不/不可不","g":{"j":"~しないわけにはいかない／~せざるを得ない","e":"cannot help but / have no choice but to","k":"~하지 않을 수 없다"},"p":{"j":"(主語)＋不能不/不得不/不可不＋動詞","e":"Subject + 不能不/不得不/不可不 + Verb","k":"주어 + 不能不/不得不/不可不 + 동사"},"ex":{"j":"三つとも二重否定で「~しないことはできない→~せざるを得ない」という強い必要性を表す。「不得不」が最も口語的でよく使われ、外的事情による「仕方なく」を表す。「不可不」はやや書き言葉で、忠告や戒めに使われることが多い。「不能不」はその中間的な言い方。三つを自由に入れ替えられるとは限らないので、教科書の例文とセットで覚えるとよい。","e":"All three are double negatives meaning \"cannot not do X\" → \"must / have no choice but to.\" \"不得不\" is the most common and colloquial, framing the action as forced by outside circumstances. \"不可不\" is more literary, often used in advice or warnings. \"不能不\" sits in between. They aren't always freely interchangeable, so it helps to learn each with its typical example sentence.","k":"세 가지 모두 이중부정으로 \"~하지 않을 수 없다\"는 강한 필요성을 나타낸다. 「不得不」가 가장 구어적이고 흔히 쓰이며 외부 상황 때문에 \"어쩔 수 없이\"라는 뜻을 담는다. 「不可不」는 다소 문어체로 충고나 경고에 자주 쓰인다. 「不能不」는 그 중간 정도의 어감이다. 세 표현이 항상 자유롭게 바뀌어 쓰이는 것은 아니므로 각각의 대표 예문과 함께 익히는 것이 좋다."},"eg":[{"z":"流了一整天的汗，我的衣服<em>不能不</em>洗。","py":"Liúle yī zhěngtiān de hàn, wǒ de yīfú bù néng bù xǐ.","j":"一日中汗をかいたので、私の服は洗わないわけにはいかない。","e":"After sweating all day, I have no choice but to wash my clothes.","k":"하루 종일 땀을 흘려서, 내 옷은 빨지 않을 수 없다."},{"z":"因為工作太忙，他<em>不得不</em>取消旅行計畫。","py":"Yīnwèi gōngzuò tài máng, tā bù dé bù qǔxiāo lǚxíng jìhuà.","j":"仕事があまりに忙しいので、彼は旅行の計画を取り消さざるを得なかった。","e":"Because he was too busy with work, he had no choice but to cancel his travel plans.","k":"일이 너무 바빠서, 그는 어쩔 수 없이 여행 계획을 취소했다."}]},
{"id":"g4-251","cat":"比較","t":"跟/和......比起來","g":{"j":"〜と比べると","e":"compared to...","k":"~와/과 비교하면"},"p":{"j":"跟/和 ＋ A ＋ 比起來，B......","e":"Gēn/hé + A + bǐqǐlái, B...","k":"跟/和 + A + 比起來, B..."},"ex":{"j":"比較の対象を明確に示す表現。『跟』と『和』は入れ替え可能で意味は同じ。単純な『比』とは違い、背景や状況全体を対比するニュアンスが強い。","e":"Introduces an explicit point of comparison before stating how B differs. 跟 and 和 are interchangeable here. Unlike the simple '比' comparison, this pattern emphasizes contrasting whole situations, not just one quality.","k":"비교 대상을 먼저 제시한 뒤 그와 다른 점을 말하는 표현. 跟과 和는 서로 바꿔 쓸 수 있다. 단순 비교의 '比'보다 전체적인 상황을 대비하는 느낌이 강하다."},"eg":[{"z":"<em>跟在國內讀書比起來</em>，出國留學是更大的挑戰。","py":"Gēn zài guónèi dúshū bǐqǐlái, chūguó liúxué shì gèng dà de tiǎozhàn.","j":"国内で勉強するのに比べて、海外留学はもっと大きな挑戦だ。","e":"Compared to studying in one's own country, studying abroad is a bigger challenge.","k":"국내에서 공부하는 것에 비해, 해외 유학은 더 큰 도전이다."},{"z":"<em>跟坐公車比起來</em>，搭捷運方便多了。","py":"Gēn zuò gōngchē bǐqǐlái, dā jiéyùn fāngbiàn duōle.","j":"バスに乗るのに比べて、MRTに乗るほうがずっと便利だ。","e":"Compared to taking the bus, taking the MRT is much more convenient.","k":"버스를 타는 것에 비해, MRT를 타는 게 훨씬 편리하다."}]},
{"id":"g4-252","cat":"比較","t":"A像B一樣......","g":{"j":"AはBと同じように〜","e":"A is like B, ...","k":"A는 B와 같이~"},"p":{"j":"A ＋ 像 ＋ B ＋ 一樣 ＋（形容詞／動詞）","e":"A + xiàng + B + yíyàng + (adj./verb)","k":"A + 像 + B + 一樣 + (형용사/동사)"},"ex":{"j":"AとBを比較し、同じ性質や状態であることを示す。後ろに形容詞や動詞句が続く。否定は『不像』『不再像』の形でよく使われる。","e":"States that A shares the same quality or state as B, typically followed by an adjective or verb phrase. Negation commonly appears as 不像 or 不再像, as in the official example.","k":"A와 B가 같은 성질·상태임을 나타내며 뒤에 형용사나 동사구가 온다. 부정은 不像, 不再像 형태로 자주 쓰인다."},"eg":[{"z":"畢業後，我們不再<em>像以前一樣</em>經常見面。","py":"Bìyè hòu, wǒmen búzài xiàng yǐqián yíyàng jīngcháng jiànmiàn.","j":"卒業後、私たちは以前のようにはもう頻繁に会わなくなった。","e":"After graduation, we no longer meet often like we used to.","k":"졸업 후, 우리는 예전처럼 자주 만나지 않는다."},{"z":"他個性<em>像爸爸一樣</em>固執。","py":"Tā gèxìng xiàng bàba yíyàng gùzhí.","j":"彼の性格はお父さんと同じくらい頑固だ。","e":"His personality is as stubborn as his father's.","k":"그의 성격은 아버지처럼 고집이 세다."}]},
{"id":"g4-253","cat":"比較","t":"A不如B","g":{"j":"AはBに及ばない","e":"A is not as good as B","k":"A는 B만 못하다"},"p":{"j":"A ＋ 不如 ＋ B","e":"A + bùrú + B","k":"A + 不如 + B"},"ex":{"j":"AとBを比べ、AがBに劣る・及ばないことを述べる。『不如』は『〜ほどではない』という意味を持つ動詞的表現で、後ろに形容詞を伴い『不如B＋形容詞』の形になることも多い。","e":"Compares A to B and states that A falls short of B. 不如 functions as a verb meaning 'not as good as' and can be followed directly by an adjective (不如 B + adj.) to specify in what way.","k":"A와 B를 비교하여 A가 B에 못 미친다고 말한다. 不如는 그 자체로 '~만 못하다'는 뜻의 동사적 표현이며, 뒤에 형용사가 붙어 구체적으로 비교하기도 한다."},"eg":[{"z":"最近幾年，火車站附近的發展<em>不如新市區</em>。","py":"Zuìjìn jǐ nián, huǒchēzhàn fùjìn de fāzhǎn bùrú xīn shìqū.","j":"最近数年、駅周辺の発展は新市街地に及ばない。","e":"In recent years, development near the train station hasn't kept pace with the new district.","k":"최근 몇 년 동안 기차역 근처의 발전은 신시가지만 못하다."},{"z":"這家店的咖啡<em>不如樓下那家</em>好喝。","py":"Zhè jiā diàn de kāfēi bùrú lóuxià nà jiā hǎohē.","j":"この店のコーヒーは階下の店ほどおいしくない。","e":"This shop's coffee isn't as good as the one downstairs.","k":"이 가게 커피는 아래층 가게만큼 맛있지 않다."}]},
{"id":"g4-254","cat":"特殊構文","t":"多Vs啊","g":{"j":"なんて〜だろう！（感嘆）","e":"How...!","k":"정말 ~하구나!"},"p":{"j":"多 ＋ 形容詞 ＋ 啊","e":"duō + adjective + a","k":"多 + 형용사 + 啊"},"ex":{"j":"程度の高さに感動や驚きを表す感嘆文。『多』は疑問詞『どれくらい』に由来するが、ここでは感嘆を作る。文末の『啊』は話し言葉ではほぼ必須。","e":"An exclamatory pattern expressing how high a degree is. 多 originates as an interrogative ('how much') but here builds an exclamation; the sentence-final 啊 is nearly obligatory in speech.","k":"정도가 매우 높음에 감탄하는 표현. 多는 원래 '얼마나'라는 의문사지만 여기서는 감탄문을 만든다. 문장 끝의 啊는 구어에서 거의 필수적이다."},"eg":[{"z":"他的新髮型<em>多漂亮啊</em>！","py":"Tā de xīn fǎxíng duō piàoliang a!","j":"彼の新しい髪型は、なんてきれいなんだろう！","e":"His new hairstyle is so good-looking!","k":"그의 새 헤어스타일은 정말 예쁘구나!"},{"z":"這個房間<em>多乾淨啊</em>！","py":"Zhège fángjiān duō gānjìng a!","j":"この部屋、なんてきれいなんだろう！","e":"This room is so clean!","k":"이 방은 정말 깨끗하구나!"}]},
{"id":"g4-255","cat":"副詞","t":"差一點（就）......","g":{"j":"もう少しで〜するところだった","e":"almost / nearly did...","k":"하마터면 ~할 뻔했다"},"p":{"j":"差一點（就）＋ 動詞句","e":"chà yìdiǎn (jiù) + verb phrase","k":"差一點（就）+ 동사구"},"ex":{"j":"実際には起こらなかったが、あと少しで起こりそうだった状況を表す。話し手の安心や後悔などの気持ちを含むことが多い。『就』は強調のための任意の要素。","e":"Expresses that something nearly happened but ultimately did not, often carrying the speaker's relief or regret. 就 is optional and adds emphasis.","k":"실제로는 일어나지 않았지만 거의 일어날 뻔했던 상황을 나타내며, 화자의 안도나 후회의 뉘앙스를 담는 경우가 많다. 就는 강조를 위해 임의로 넣을 수 있다."},"eg":[{"z":"他<em>差一點就遲到了</em>。","py":"Tā chāyìdiǎn jiù chídào le.","j":"彼はもう少しで遅刻するところだった。","e":"He almost was late.","k":"그는 하마터면 지각할 뻔했다."},{"z":"我<em>差一點忘了</em>帶鑰匙。","py":"Wǒ chāyìdiǎn wàngle dài yàoshi.","j":"私はもう少しで鍵を持って来るのを忘れるところだった。","e":"I almost forgot to bring my keys.","k":"나는 하마터면 열쇠 가져오는 걸 잊을 뻔했다."}]},
{"id":"g4-256","cat":"介詞","t":"跟......（沒）有關","g":{"j":"〜と関係がある","e":"related to ~","k":"~와/과 관계가 있다"},"p":{"j":"跟＋A＋（沒）有關","e":"gēn + A + (méi) yǒuguān","k":"跟 + A + (沒)有關"},"ex":{"j":"「跟」は「〜について」ではなく「〜と」を表す介詞で、原因や関連を述べる。「因為」と違い、直接の理由ではなく漠然とした関連性を示す時に使う。","e":"\"跟...有關\" states that two things are related, using 跟 as \"with,\" not \"about.\" Unlike 因為, it shows a loose association, not a direct cause.","k":"\"跟...有關\"은 두 대상이 서로 관련이 있음을 나타내며, 跟은 '~와/과'의 뜻이다. 因為와 달리 직접적 원인이 아닌 막연한 관련성을 나타낼 때 쓴다."},"eg":[{"z":"現代人生病往往都<em>跟壓力有關</em>。","py":"Xiàndài rén shēngbìng wǎngwǎng dōu gēn yālì yǒuguān.","j":"現代人が病気になるのは、たいていストレスと関係がある。","e":"Modern people's illnesses are often related to stress.","k":"현대인이 병에 걸리는 것은 대개 스트레스와 관련이 있다."},{"z":"他的皮膚問題可能<em>跟壓力有關</em>。","py":"Tā de pífū wèntí kěnéng gēn yālì yǒuguān.","j":"彼の皮膚トラブルはストレスと関係があるかもしれない。","e":"His skin problems might be related to stress.","k":"그의 피부 문제는 스트레스와 관련이 있을지도 모른다."}]},
{"id":"g4-257","cat":"特殊構文","t":"給......帶來......","g":{"j":"〜に〜をもたらす","e":"bring ~ to ~","k":"~에게 ~을/를 가져다주다"},"p":{"j":"A＋給＋B＋帶來＋C","e":"A + gěi + B + dàilái + C","k":"A + 給 + B + 帶來 + C"},"ex":{"j":"「帶來」は具体的な物ではなく、影響・結果・感情など抽象的なものを「もたらす」時に使う。「給」は対象(誰に)を示し、省略できない。","e":"\"給...帶來...\" means \"bring [abstract result] to [someone]\" — 帶來 is for effects or consequences, not physical objects, and 給 marking the recipient cannot be omitted.","k":"\"給...帶來...\"는 구체적인 물건이 아니라 영향, 결과, 감정 등 추상적인 것을 '가져다준다'는 뜻이며, 給은 대상을 나타내고 생략할 수 없다."},"eg":[{"z":"持續工作可以<em>給我們帶來穩定的收入</em>。","py":"Chíxù gōngzuò kěyǐ gěi wǒmen dàilái wěndìng de shōurù.","j":"続けて働くことは私たちに安定した収入をもたらしてくれる。","e":"Continuing to work can bring us a stable income.","k":"계속 일하는 것은 우리에게 안정적인 수입을 가져다 줄 수 있다."},{"z":"運動可以<em>給身體帶來很多好處</em>。","py":"Yùndòng kěyǐ gěi shēntǐ dàilái hěnduō hǎochù.","j":"運動は体に多くの良い影響をもたらしてくれる。","e":"Exercise can bring the body a lot of benefits.","k":"운동은 몸에 많은 좋은 점을 가져다 줄 수 있다."}]},
{"id":"g4-258","cat":"接続","t":"不......不......","g":{"j":"〜しなければ〜しない","e":"if not A, then not B","k":"~하지 않으면 ~하지 않다"},"p":{"j":"不＋A，（就）不＋B","e":"bù + A, (jiù) bù + B","k":"不 + A, (就) 不 + B"},"ex":{"j":"前半の「不A」は仮定条件、後半の「不B」がその結果を示す。「如果不…就不…」の「如果」を省略した口語的な言い方で、話し言葉でよく使われる。","e":"\"不...不...\" states \"if you don't do A, then B won't happen\" — a colloquial way of omitting 如果 from 如果不...就不..., common in spoken Mandarin.","k":"앞의 \"不A\"는 가정 조건이고 뒤의 \"不B\"는 그 결과이다. \"如果不...就不...\"에서 如果를 생략한 구어체 표현으로 회화에서 자주 쓰인다."},"eg":[{"z":"你<em>不</em>來，活動就<em>不</em>能開始。","py":"Nǐ bù lái, huódòng jiù bù néng kāishǐ.","j":"あなたが来なければ、イベントは始められない。","e":"If you don't come, the event can't start.","k":"네가 오지 않으면 행사가 시작될 수 없다."},{"z":"我們<em>不</em>努力，就<em>不</em>會成功。","py":"Wǒmen bù nǔlì, jiù bú huì chénggōng.","j":"私たちが努力しなければ、成功することはできない。","e":"If we don't work hard, we won't succeed.","k":"우리가 노력하지 않으면 성공할 수 없다."}]},
{"id":"g4-259","cat":"特殊構文","t":"看/要看/得看","g":{"j":"〜次第だ、〜による","e":"it depends on ~","k":"~에 달려 있다"},"p":{"j":"（要/得）看＋（誰／什麼／怎麼樣等）","e":"(yào/děi) kàn + (question-word clause)","k":"（要/得）看 + (의문사절)"},"ex":{"j":"「看」の後に疑問詞を含む節を置き、「〜次第だ」という意味を表す。「要看」は一般的な言い方、「得看」は必須・避けられない条件のニュアンスが強い。","e":"\"看/要看/得看\" + a clause with a question word means \"it depends on ~.\" 要看 is neutral, while 得看 emphasizes an unavoidable, necessary condition.","k":"\"看\" 뒤에 의문사가 포함된 절을 두어 '~에 달려 있다'는 뜻을 나타낸다. 要看는 일반적인 표현이고, 得看는 반드시 필요한 조건이라는 뉘앙스가 강하다."},"eg":[{"z":"遇到問題時，<em>要看每個人用什麼態度去面對它</em>，處理方式就會不一樣。","py":"Yùdào wèntí shí, yào kàn měi ge rén yòng shénme tàidù qù miànduì tā, chǔlǐ fāngshì jiù huì bù yíyàng.","j":"問題に遭遇した時、それぞれの人がどんな態度でそれに向き合うかによって、対処の仕方も違ってくる。","e":"When you encounter a problem, it depends on what attitude each person takes to face it — the way of handling it will be different.","k":"문제에 부딪혔을 때, 각자가 어떤 태도로 그것을 마주하느냐에 따라 대처 방식도 달라진다."},{"z":"這次比賽誰會贏，<em>要看選手當天的表現</em>。","py":"Zhè cì bǐsài shéi huì yíng, yào kàn xuǎnshǒu dàngtiān de biǎoxiàn.","j":"この試合で誰が勝つかは、選手のその日の調子次第だ。","e":"Who wins this match depends on the athletes' performance on that day.","k":"이번 경기에서 누가 이길지는 선수들의 그날 컨디션에 달려 있다."}]},
{"id":"g4-260","cat":"接続","t":"不論/無論","g":{"j":"〜であろうと(条件に関わらず)","e":"no matter (whether) ~","k":"~든지 상관없이"},"p":{"j":"不論/無論＋疑問詞・或／是…或…","e":"bùlùn/wúlùn + question word / A huò B","k":"不論/無論 + 의문사 / A 或 B"},"ex":{"j":"後半に「都」「也」を伴い、「どんな条件でも結果は同じ」ことを表す。「無論」はやや書き言葉的で改まった印象、「不論」は口語・書き言葉どちらでも使える。","e":"\"不論/無論\" pairs with 都/也 later in the sentence to mean \"regardless of the condition, the result is the same.\" 無論 sounds slightly more formal/written than 不論, which fits both speech and writing.","k":"뒤에 都/也와 함께 쓰여 '어떤 조건이든 결과는 같다'는 뜻을 나타낸다. 無論은 다소 격식 있는 문어체 느낌이고, 不論은 구어와 문어 모두에서 쓸 수 있다."},"eg":[{"z":"近年來<em>不論是企業或個人</em>，使用網路的情況都越來越普遍。","py":"Jìnnián lái bùlùn shì qìyè huò gèrén, shǐyòng wǎnglù de qíngkuàng dōu yuè lái yuè pǔbiàn.","j":"近年、企業であれ個人であれ、インターネットを使う状況はますます一般的になっている。","e":"In recent years, whether it's businesses or individuals, internet usage has become more and more common.","k":"최근 몇 년 동안 기업이든 개인이든 인터넷 사용 상황은 점점 더 보편화되고 있다."},{"z":"<em>無論下雨或晴天</em>，我們都要出發。","py":"Wúlùn xiàyǔ huò qíngtiān, wǒmen dōu yào chūfā.","j":"雨が降ろうと晴れようと、私たちは出発しなければならない。","e":"Whether it rains or shines, we have to set out.","k":"비가 오든 날이 맑든 우리는 출발해야 한다."}]},
{"id":"g4-261","cat":"接続","t":"只是","g":{"j":"ただ〜だけ(軽い転折)","e":"it's just that... (mild contrast)","k":"다만 ~일 뿐(가벼운 전환)"},"p":{"j":"A，只是 B","e":"A, only B (mild qualification)","k":"A, 只是 B"},"ex":{"j":"「只是」は前の内容をほぼ肯定しつつ、軽い例外や欠点を付け加える。「但是」より語気が弱く、全体の評価を覆さない点に注意。","e":"\"只是\" softly adds a minor exception or drawback without overturning the main point, unlike the stronger \"但是/可是\" which can signal a full contrast.","k":"\"只是\"는 앞 내용을 거의 인정하면서 가벼운 예외나 단점을 덧붙인다. \"但是\"보다 어조가 약하고 전체 평가를 뒤집지 않는다."},"eg":[{"z":"他身體很健康，<em>只是</em>眼睛不太好。","py":"Tā shēntǐ hěn jiànkāng, zhǐshì yǎnjīng bú tài hǎo.","j":"彼は体はとても健康だが、ただ目があまりよくない。","e":"He's very healthy, it's just that his eyes aren't very good.","k":"그는 몸은 아주 건강한데, 다만 눈이 별로 안 좋다."},{"z":"這家餐廳的菜很好吃，<em>只是</em>價錢有點貴。","py":"Zhè jiā cāntīng de cài hěn hǎochī, zhǐshì jiàqián yǒudiǎn guì.","j":"このレストランの料理はとてもおいしいが、ただ値段が少し高い。","e":"The food at this restaurant is delicious, it's just that the price is a bit high.","k":"이 식당 음식은 아주 맛있는데, 다만 가격이 좀 비싸다."}]},
{"id":"g4-262","cat":"副詞","t":"卻","g":{"j":"かえって、意外にも(予想に反する転折)","e":"yet/unexpectedly (contrary to expectation)","k":"오히려(예상과 반대)"},"p":{"j":"A，(但)B 卻 C","e":"A, (but) B 卻 + unexpected result","k":"A, (但) B 卻 C"},"ex":{"j":"「卻」は副詞で動詞・形容詞の前に置き、予想と反対の結果を強調する。「但是」と一緒に使うことも多いが、「卻」だけでも転折を表せる点に注意。","e":"\"卻\" is an adverb placed before the verb/adjective to stress an outcome contrary to expectation; it can appear with or without \"但是\" and still shows contrast on its own.","k":"\"卻\"는 부사로 동사/형용사 앞에 놓여 예상과 반대되는 결과를 강조한다. \"但是\"와 함께 쓰이기도 하지만 \"卻\"만으로도 전환을 나타낼 수 있다."},"eg":[{"z":"外面太陽很大，但溫度<em>卻</em>很低。","py":"Wàimiàn tàiyáng hěn dà, dàn wēndù què hěn dī.","j":"外は日差しがとても強いのに、気温はかえってとても低い。","e":"It's very sunny outside, but the temperature is surprisingly low.","k":"밖은 햇볕이 아주 강한데, 기온은 오히려 아주 낮다."},{"z":"他很努力唸書，成績<em>卻</em>沒有進步。","py":"Tā hěn nǔlì niànshū, chéngjī què méiyǒu jìnbù.","j":"彼はとても頑張って勉強しているのに、成績はかえって伸びない。","e":"He studies very hard, but his grades haven't improved at all.","k":"그는 아주 열심히 공부하는데, 성적은 오히려 나아지지 않는다."}]},
{"id":"g4-263","cat":"接続","t":"（要）不然","g":{"j":"そうしないと〜(でなければ)","e":"otherwise / or else","k":"그렇지 않으면"},"p":{"j":"A，（要）不然 B","e":"A, (or) otherwise B","k":"A, (要)不然 B"},"ex":{"j":"「不然」は前の内容を実行しなければ起こる好ましくない結果を導く。「要不然」も同じ意味で口語でよく使われ、「如果不…的話」よりくだけた言い方。","e":"\"不然\" (or \"要不然\") introduces the undesirable result if the preceding condition isn't followed — a casual, spoken alternative to a more formal \"如果不…的話\".","k":"\"不然\"(또는 \"要不然\")은 앞의 조건을 따르지 않으면 생기는 나쁜 결과를 이끈다. 격식적인 \"如果不…的話\"보다 구어체에서 자주 쓰인다."},"eg":[{"z":"爸爸叫我們動作快，<em>（要）不然</em>船要開走了。","py":"Bàba jiào wǒmen dòngzuò kuài, (yào) bùrán chuán yào kāizǒu le.","j":"お父さんは私たちに早く動けと言った、じゃないと船が出発してしまう。","e":"Dad told us to hurry up, otherwise the boat is going to leave.","k":"아빠는 우리에게 빨리 움직이라고 했다, 안 그러면 배가 떠나 버릴 거야."},{"z":"你要趕快寫作業，<em>不然</em>明天會被老師罵。","py":"Nǐ yào gǎnkuài xiě zuòyè, bùrán míngtiān huì bèi lǎoshī mà.","j":"早く宿題をやらないと、明日先生に叱られるよ。","e":"You'd better hurry and do your homework, or you'll get scolded by the teacher tomorrow.","k":"빨리 숙제를 해야지, 안 그러면 내일 선생님한테 혼날 거야."}]},
{"id":"g4-264","cat":"特殊構文","t":"是","g":{"j":"確かに〜だ(強調の是)","e":"indeed/really (emphatic 是 before adjective)","k":"확실히 ~하다(강조의 是)"},"p":{"j":"(話題) ＋ 是 ＋ 形容詞","e":"(Topic) + 是 + Adjective (for emphasis)","k":"(화제) + 是 + 형용사(강조)"},"ex":{"j":"この「是」は「A是B」のイコール文ではなく、形容詞の前に置いて前の発言に同意・確認する強調用法。「真的」に近いが、より書き言葉的で相手の発言を受けて使うことが多い。","e":"This \"是\" isn't the equational \"A是B\"; placed before an adjective it emphasizes agreement/confirmation with something just said, close to \"真的\" but more often used to affirm a prior remark.","k":"이 \"是\"는 \"A是B\" 형태의 동등문이 아니라 형용사 앞에서 앞선 발언에 동의·확인하는 강조 용법이다. \"真的\"와 비슷하지만 상대방 말을 받아 확인할 때 자주 쓰인다."},"eg":[{"z":"（出版旅遊雜誌的）成本<em>是</em>很高。","py":"(Chūbǎn lǚyóu zázhì de) chéngběn shì hěn gāo.","j":"(旅行雑誌を出版する)コストは確かに高い。","e":"(The cost of publishing a travel magazine) is indeed high.","k":"(여행 잡지를 출판하는) 비용은 확실히 높다."},{"z":"那部電影<em>是</em>很好看，你應該去看。","py":"Nà bù diànyǐng shì hěn hǎokàn, nǐ yīnggāi qù kàn.","j":"あの映画は確かに面白いから、見に行くべきだよ。","e":"That movie really is very good, you should go watch it.","k":"그 영화는 확실히 재미있으니까 보러 가야 해."}]},
{"id":"g4-265","cat":"特殊構文","t":"哪裡......","g":{"j":"まさか〜とは(予想外を表す反語)","e":"who would have known... (rhetorical, expresses the unexpected)","k":"뜻밖에도 ~일 줄이야(반어적 표현)"},"p":{"j":"A，哪裡知道 B","e":"A, 哪裡知道(哪裡想到) + unexpected B","k":"A, 哪裡知道 B"},"ex":{"j":"「哪裡」は疑問詞だが、ここでは場所を尋ねず「知道/想到」とセットで反語となり、「予想もしなかった」という意外な事実を強調する。単純な場所の質問「哪裡」と混同しないよう注意。","e":"Here \"哪裡\" isn't asking about location — paired with \"知道/想到\" it forms a rhetorical question meaning \"how could one have known,\" stressing an unexpected fact; don't confuse it with the literal \"where\" question.","k":"여기서 \"哪裡\"는 장소를 묻는 게 아니라 \"知道/想到\"와 결합해 반어문이 되어 \"전혀 예상하지 못했다\"는 뜻밖의 사실을 강조한다. 단순한 장소 질문의 \"哪裡\"와 혼동하지 말 것."},"eg":[{"z":"他本來打算去租影片，<em>哪裡知道</em>那間店在三天前竟然關了！","py":"Tā běnlái dǎsuàn qù zū yǐngpiàn, nǎlǐ zhīdào nà jiān diàn zài sān tiān qián jìngrán guān le!","j":"彼はもともとDVDを借りに行くつもりだったが、まさかその店が3日前に閉店していたなんて。","e":"He originally planned to go rent a movie, but who would have known that store had actually closed three days earlier!","k":"그는 원래 영화를 빌리러 갈 생각이었는데, 그 가게가 3일 전에 뜻밖에도 문을 닫았을 줄이야!"},{"z":"我以為考試會很簡單，<em>哪裡知道</em>題目這麼難！","py":"Wǒ yǐwéi kǎoshì huì hěn jiǎndān, nǎlǐ zhīdào tímù zhème nán!","j":"試験は簡単だと思っていたのに、まさか問題がこんなに難しいとは。","e":"I thought the exam would be easy, but who knew the questions would be this hard!","k":"시험이 쉬울 거라 생각했는데, 문제가 이렇게 어려울 줄이야!"}]},
{"id":"g4-266","cat":"特殊構文","t":"說......就......","g":{"j":"言うが早いか～する／急に変わる","e":"as soon as said, done / changes suddenly","k":"말하자마자 ~하다 / 갑자기 변하다"},"p":{"j":"說＋Ｖ＋就＋Ｖ","e":"shuō + V + jiù + V","k":"說+V+就+V"},"ex":{"j":"「說Ｖ就Ｖ」は言ってすぐ実行する、または予告なく急に変わることを表す。決断の速さや予測不能さを強調する構文。「馬上」と違い、突然さ・意外性を含む点に注意。","e":"\"Shuō X jiù X\" means doing X right after saying it, or something changing abruptly with no warning — it stresses suddenness or unpredictability, unlike the neutral \"馬上\".","k":"\"說V就V\"는 말하자마자 바로 하거나 예고 없이 갑자기 변하는 것을 나타내며 돌발성과 예측불가능성을 강조한다. \"馬上\"과 달리 뜻밖의 느낌을 담는다."},"eg":[{"z":"山上的天氣不太穩定，常常<em>說變就變</em>。","py":"Shān shàng de tiānqì bú tài wěndìng, chángcháng shuō biàn jiù biàn.","j":"山の天気はあまり安定しておらず、よく急に変わる。","e":"The weather in the mountains isn't very stable — it often changes just like that.","k":"산 위의 날씨는 그다지 안정적이지 않아서 자주 갑자기 변한다."},{"z":"他<em>說走就走</em>，行李都沒收拾就出門了。","py":"Tā shuō zǒu jiù zǒu, xínglǐ dōu méi shōushí jiù chūmén le.","j":"彼は言うが早いか出て行った、荷物もまとめずに出かけてしまった。","e":"He just up and left — he went out without even packing his bags.","k":"그는 말하자마자 바로 떠났다, 짐도 안 싸고 나가 버렸다."}]},
{"id":"g4-267","cat":"介詞","t":"通過","g":{"j":"～を通じて","e":"through / by means of","k":"~을 통해"},"p":{"j":"通過＋方法／事件，＋結果","e":"通過 + means/event, + result","k":"通過+수단/사건, +결과"},"ex":{"j":"「通過＋手段」は、ある方法や経路を通じて結果を得ることを示す、やや書き言葉的な表現。「經過」との違いは、「經過」が時間・過程の経過を強調するのに対し、「通過」は手段・方法を強調する点。","e":"\"通過 + means\" indicates achieving a result via a certain method or channel; it's fairly formal/written. Unlike \"經過\" (which stresses the passing of time/process), \"通過\" stresses the means used.","k":"\"通過+수단\"은 어떤 방법이나 경로를 통해 결과를 얻는 것을 나타내며 다소 문어적이다. \"經過\"는 시간·과정의 경과를 강조하는 반면 \"通過\"는 수단·방법을 강조한다는 점이 다르다."},"eg":[{"z":"<em>通過</em>這次溝通，老師又更理解學生的想法了。","py":"Tōngguò zhè cì gōutōng, lǎoshī yòu gèng lǐjiě xuéshēng de xiǎngfǎ le.","j":"今回のコミュニケーションを通じて、先生は学生の考えをさらによく理解するようになった。","e":"Through this conversation, the teacher came to understand the students' thoughts even better.","k":"이번 소통을 통해 선생님은 학생들의 생각을 더 잘 이해하게 되었다."},{"z":"<em>通過</em>這次比賽，我們學到了不少團隊合作的經驗。","py":"Tōngguò zhè cì bǐsài, wǒmen xuédào le bù shǎo tuánduì hézuò de jīngyàn.","j":"今回の試合を通して、私たちはチームワークの経験をたくさん学んだ。","e":"Through this competition, we learned a lot about teamwork.","k":"이번 경기를 통해 우리는 팀워크에 대한 많은 경험을 배웠다."}]},
{"id":"g4-268","cat":"介詞","t":"經過","g":{"j":"～を経て","e":"after (a period of time / process)","k":"~을 거쳐"},"p":{"j":"經過＋時間／過程（之後），＋結果","e":"經過 + time/process (之後), + result","k":"經過+시간/과정(之後), +결과"},"ex":{"j":"「經過＋時間／過程」は、物事が経てきた時間や段階を強調し、よく「之後」を伴う。「通過」との違いは、「經過」が時間の経過や過程そのものに重点を置く点。","e":"\"經過 + time/process\" stresses the duration or stage something has gone through, often followed by \"之後\". Unlike \"通過\", it focuses on the passage of time/process itself, not the means to a result.","k":"\"經過+시간/과정\"은 어떤 일이 거쳐온 시간이나 단계를 강조하며 흔히 \"之後\"와 함께 쓰인다. \"通過\"와 달리 시간의 경과나 과정 자체에 초점을 둔다."},"eg":[{"z":"<em>經過</em>一段時間之後，他已經可以適應研究所的生活了。","py":"Jīngguò yí duàn shíjiān zhīhòu, tā yǐjīng kěyǐ shìyìng yánjiùsuǒ de shēnghuó le.","j":"しばらく時間が経ってから、彼はもう大学院の生活に慣れることができるようになった。","e":"After some time had passed, he was already able to adapt to graduate school life.","k":"얼마간의 시간이 지난 후, 그는 이미 대학원 생활에 적응할 수 있게 되었다."},{"z":"<em>經過</em>幾個月的練習，她的中文進步了很多。","py":"Jīngguò jǐ ge yuè de liànxí, tā de Zhōngwén jìnbù le hěn duō.","j":"数ヶ月の練習を経て、彼女の中国語はとても上達した。","e":"After several months of practice, her Chinese improved a lot.","k":"몇 달간의 연습을 거쳐, 그녀의 중국어는 많이 향상되었다."}]},
{"id":"g4-269","cat":"特殊構文","t":"拿","g":{"j":"～を使って／～を持ち出して","e":"use X as/to do Y","k":"~을 가지고 / 이용해서"},"p":{"j":"拿＋Ｎ＋來＋Ｖ","e":"ná + N + lái + V","k":"拿+명사+來+동사"},"ex":{"j":"「拿＋名詞＋來＋動詞」は、あるものを手段・材料として後の動作を行うことを表す。ここでの「拿」は手で持つ具体的動作ではなく、「〜を用いて」という抽象的な意味。","e":"\"拿 + noun + 來 + verb\" means using something as a means or material for the following action. Here \"拿\" isn't the literal act of holding something, but the abstract sense of \"using/taking X as.\"","k":"\"拿+명사+來+동사\"는 어떤 것을 수단이나 소재로 삼아 뒤의 동작을 하는 것을 나타낸다. 여기서 \"拿\"는 손으로 잡는 구체적 동작이 아니라 \"~을 가지고/이용해서\"라는 추상적 의미다."},"eg":[{"z":"上課的時候，老師常常<em>拿自己的經驗來作例子</em>。","py":"Shàngkè de shíhòu, lǎoshī chángcháng ná zìjǐ de jīngyàn lái zuò lìzi.","j":"授業のとき、先生はよく自分の経験を例として使う。","e":"During class, the teacher often uses their own experience as examples.","k":"수업 시간에 선생님은 자주 자신의 경험을 예로 든다."},{"z":"他常常<em>拿電影的台詞來開玩笑</em>。","py":"Tā chángcháng ná diànyǐng de táicí lái kāiwánxiào.","j":"彼はよく映画のセリフを持ち出して冗談を言う。","e":"He often uses movie lines to make jokes.","k":"그는 자주 영화 대사를 가지고 농담을 한다."}]},
{"id":"g4-270","cat":"介詞","t":"按照","g":{"j":"～に従って","e":"according to","k":"~에 따라"},"p":{"j":"按照＋規定／說明，＋動作","e":"按照 + standard/instruction, + action","k":"按照+기준/설명, +동작"},"ex":{"j":"「按照＋規則・説明」は、ある基準や根拠に従って行動することを表し、やや改まった言い方。「根據」と意味が近いが、「按照」は「その通りに実行する」ことを強調し、「根據」は「事実に基づいて判断する」ことに重点がある。","e":"\"按照 + rule/instruction\" means acting in accordance with a standard, and sounds fairly formal. It's close to \"根據\", but \"按照\" stresses following something exactly, while \"根據\" stresses basing a judgment on facts.","k":"\"按照+규정/설명\"은 어떤 기준이나 근거에 따라 행동하는 것을 나타내며 다소 격식적이다. \"根據\"와 비슷하지만 \"按照\"는 \"그대로 따라 실행함\"을 강조하고 \"根據\"는 \"사실에 근거한 판단\"에 중점을 둔다."},"eg":[{"z":"他們<em>按照</em>旅遊書上的介紹，安排了三天兩夜的旅行。","py":"Tāmen ànzhào lǚyóushū shàng de jièshào, ānpái le sān tiān liǎng yè de lǚxíng.","j":"彼らは旅行ガイドブックの紹介に従って、2泊3日の旅行を計画した。","e":"They planned a three-day, two-night trip according to the guidebook's recommendations.","k":"그들은 여행 가이드북의 소개에 따라 2박 3일 여행을 계획했다."},{"z":"請<em>按照</em>老師的指示完成作業。","py":"Qǐng ànzhào lǎoshī de zhǐshì wánchéng zuòyè.","j":"先生の指示に従って宿題を完成させてください。","e":"Please complete the homework according to the teacher's instructions.","k":"선생님의 지시에 따라 숙제를 완성해 주세요."}]},
{"id":"g4-271","cat":"介詞","t":"照（著）","g":{"j":"〜のやり方どおりに","e":"following/according to (a method)","k":"~하는 대로"},"p":{"j":"A ＋ 照（著）＋ B ＋ V","e":"A + 照（著）+ B + V","k":"A + 照（著）+ B + V"},"ex":{"j":"「〜のやり方・手本どおりに」という意味。「照」は方法や手本に従う動作を表し、「著」は省略可。「按照」に近いがより口語的。","e":"Means \"following/according to\" a method or model. \"照\" shows imitation of a way of doing something; \"著\" is optional. Close to \"按照\" but more colloquial.","k":"'~하는 대로, ~을 따라서'라는 뜻. '照'는 방법이나 본보기를 따르는 동작을 나타내며 '著'는 생략 가능. '按照'와 비슷하지만 더 구어적이다."},"eg":[{"z":"我<em>照著</em>媽媽的做法包水餃。","py":"Wǒ zhàozhe māma de zuòfǎ bāo shuǐjiǎo.","j":"私は母のやり方どおりに水餃子を作る。","e":"I make dumplings the way my mom does.","k":"나는 엄마의 방법대로 만두를 빚는다."},{"z":"你可以<em>照著</em>食譜做菜。","py":"Nǐ kěyǐ zhàozhe shípǔ zuò cài.","j":"あなたはレシピどおりに料理を作ればいい。","e":"You can cook according to the recipe.","k":"너는 레시피대로 요리하면 돼."}]},
{"id":"g4-272","cat":"介詞","t":"趁（著）","g":{"j":"〜の機会を利用して","e":"taking advantage of / while","k":"~을 틈타서"},"p":{"j":"趁（著）＋ 時間／機會 ＋ V","e":"趁（著）+ time/opportunity + V","k":"趁（著）+ 시간/기회 + V"},"ex":{"j":"「〜の機会を利用して、〜のうちに」という意味。時間や状況がまだそうであるうちに行動することを表す。「著」は省略可。","e":"Means \"taking advantage of / while (a time or condition still holds)\". Expresses acting before an opportunity or state changes. \"著\" is optional.","k":"'~을 이용해서, ~인 김에'라는 뜻. 시간이나 상황이 아직 그러할 때 행동함을 나타낸다. '著'는 생략 가능하다."},"eg":[{"z":"<em>趁著</em>年節的時候，爸爸拜訪了很多親戚。","py":"Chènzhe niánjié de shíhòu, bàba bàifǎng le hěn duō qīnqī.","j":"旧正月の時期を利用して、父はたくさんの親戚を訪ねた。","e":"Taking advantage of the New Year holiday, Dad visited a lot of relatives.","k":"설 명절을 틈타 아빠는 많은 친척을 방문했다."},{"z":"<em>趁著</em>放假，我們去台南玩。","py":"Chènzhe fàngjià, wǒmen qù Táinán wán.","j":"休みを利用して、私たちは台南へ遊びに行った。","e":"Taking advantage of the holiday, we went to Tainan to have fun.","k":"방학을 틈타 우리는 타이난에 놀러 갔다."}]},
{"id":"g4-273","cat":"介詞","t":"離","g":{"j":"〜から(時間・距離)","e":"distance from (time/space)","k":"~에서/까지 (거리)"},"p":{"j":"A ＋ 離 ＋ B ＋ 還/只/有 ＋ 距離","e":"A + 離 + B + 還/只/有 + distance","k":"A + 離 + B + 還/只/有 + 거리"},"ex":{"j":"二点間の時間的・空間的な隔たりを表す介詞。「離＋基準点＋還/只/有＋距離」の形をとる。出発点を表す「從」と混同しないこと。","e":"A preposition marking distance between two points in time or space: \"離 + reference point + 還/只/有 + distance\". Don't confuse with \"從\", which marks a starting point, not a distance.","k":"시간이나 공간상 두 지점 사이의 거리를 나타내는 개사. '離+기준점+還/只/有+거리' 형태. 출발점을 나타내는 '從'과 혼동하지 않도록 주의."},"eg":[{"z":"<em>離</em>過年只剩兩天了，火車票幾乎全賣完了。","py":"Lí guònián zhǐ shèng liǎng tiān le, huǒchē piào jīhū quán mài wán le.","j":"旧正月まであと二日しかなく、電車の切符はほとんど売り切れた。","e":"There are only two days left until Chinese New Year, and train tickets are almost all sold out.","k":"설날까지 이틀밖에 안 남아서 기차표가 거의 다 팔렸다."},{"z":"<em>離</em>捷運站不遠，走路五分鐘就到了。","py":"Lí jiéyùn zhàn bù yuǎn, zǒulù wǔ fēnzhōng jiù dào le.","j":"MRTの駅から遠くなく、歩いて5分で着く。","e":"It's not far from the MRT station — five minutes on foot and you're there.","k":"지하철역에서 멀지 않아서 걸어서 5분이면 도착해요."}]},
{"id":"g4-274","cat":"特殊構文","t":"V著V著......就......了","g":{"j":"〜しているうちに、いつの間にか","e":"while V-ing, unexpectedly...","k":"~하다가 어느새"},"p":{"j":"V著V著就……了","e":"V著V著 + jiù + ... + le","k":"V著V著就……了"},"ex":{"j":"「〜しているうちに、いつの間にか〜した」という意味。動詞を重ねて動作が続いていたことを示し、その途中で予期しない変化が起きたことを表す。","e":"Means \"while doing V, V, (unexpectedly) ... happened\". Repeating the same verb shows the action was continuing, and \"就...了\" marks a sudden, often unnoticed change that followed.","k":"'~하다가 어느새 ~했다'라는 뜻. 같은 동사를 반복해 동작이 계속되고 있었음을 나타내고, 그 도중에 예기치 않은 변화가 일어났음을 보여준다."},"eg":[{"z":"弟弟常常在床上看書，<em>看著看著就睡著了</em>。","py":"Dìdi chángcháng zài chuáng shàng kànshū, kànzhe kànzhe jiù shuìzháo le.","j":"弟はよくベッドで本を読んでいて、読んでいるうちにいつの間にか眠ってしまう。","e":"My younger brother often reads in bed, and before he knows it, he falls asleep.","k":"남동생은 자주 침대에서 책을 읽다가 읽다 보면 어느새 잠들어 버린다."},{"z":"他一直在滑手機，<em>滑著滑著就忘記時間了</em>。","py":"Tā yīzhí zài huá shǒujī, huázhe huázhe jiù wàngjì shíjiān le.","j":"彼はずっとスマホをいじっていて、いじっているうちに時間を忘れてしまった。","e":"He kept scrolling on his phone, and before he knew it, he'd forgotten the time.","k":"그는 계속 휴대폰을 보다가 보다 보니 시간 가는 줄 몰랐다."}]},
{"id":"g4-275","cat":"副詞","t":"早就......了","g":{"j":"とっくに〜した","e":"already long ago","k":"진작에 ~했다"},"p":{"j":"早就 ＋ V(過) ＋ 了","e":"早就 + V(過) + 了","k":"早就 + V(過) + 了"},"ex":{"j":"「とっくに〜した／〜だった」という意味。「早」だけより強調度が高く、話し手が予想より早い、あるいは当然だという気持ちを含む。","e":"Means \"already long ago\" — stronger emphasis than \"早\" alone, often implying the speaker feels it happened earlier than expected or that it's obvious.","k":"'진작에 ~했다'라는 뜻으로 '早'만 쓸 때보다 강조가 강하며, 화자가 예상보다 일찍 그랬다거나 당연하다는 느낌을 담고 있다."},"eg":[{"z":"說點別的吧，這個故事他<em>早就聽過了</em>。","py":"Shuō diǎn bié de ba, zhège gùshì tā zǎojiù tīngguò le.","j":"別の話をしようよ、この話は彼がとっくに聞いたことがある。","e":"Let's talk about something else — he already heard this story a long time ago.","k":"다른 얘기 좀 하자, 이 이야기는 그가 진작에 들어봤어."},{"z":"別擔心，我<em>早就做完功課了</em>。","py":"Bié dānxīn, wǒ zǎojiù zuò wán gōngkè le.","j":"心配しないで、私はもうとっくに宿題を終わらせたよ。","e":"Don't worry, I finished my homework a long time ago.","k":"걱정하지 마, 나는 벌써 숙제를 다 끝냈어."}]},
{"id":"g4-276","cat":"数量","t":"......以內/之內","g":{"j":"〜以内に","e":"within","k":"~이내에"},"p":{"j":"時間/數量 ＋ 以內/之內","e":"Time/Quantity + 以內/之內","k":"시간/수량 ＋ 以內/之內"},"ex":{"j":"「之內」「以內」は範囲・期限を表し、数量や期間の後ろに置く。「以內」は数値の上限(〜以下)、「之內」は範囲全般に使えるが、時間表現では入れ替え可能なことが多い。","e":"Both mark \"within\" a range or deadline, placed after a quantity/time expression. \"以內\" often implies an upper limit (at most), while \"之內\" is more general; with time words they're often interchangeable.","k":"'之內'와 '以內'는 범위나 기한을 나타내며 수량·시간 표현 뒤에 온다. '以內'는 상한(이하)을 나타내는 경우가 많고 '之內'는 더 일반적이지만 시간 표현에서는 서로 바꿔 써도 되는 경우가 많다."},"eg":[{"z":"網站的使用人數在<em>一天之內</em>就增加了十倍。","py":"Wǎngzhàn de shǐyòng rénshù zài yì tiān zhīnèi jiù zēngjiāle shí bèi.","j":"そのウェブサイトの利用者数は1日以内に10倍に増えた。","e":"The website's number of users increased tenfold within a single day.","k":"그 웹사이트의 이용자 수는 하루 안에 열 배나 늘어났다."},{"z":"他答應在<em>三天以內</em>把報告寫完。","py":"Tā dāyìng zài sān tiān yǐnèi bǎ bàogào xiěwán.","j":"彼は3日以内にレポートを書き終えると約束した。","e":"He promised to finish writing the report within three days.","k":"그는 3일 안에 보고서를 다 쓰겠다고 약속했다."}]},
{"id":"g4-277","cat":"特殊構文","t":"一會兒......，一會兒......","g":{"j":"〜かと思うと〜","e":"now...now...","k":"어떤 때는 ~ 어떤 때는 ~"},"p":{"j":"一會兒＋A，一會兒＋B","e":"一會兒 + A, 一會兒 + B","k":"一會兒＋A，一會兒＋B"},"ex":{"j":"「一會兒A,一會兒B」は状態や動作が短い間隔で交互に変わることを表す。似た「一下A一下B」より書き言葉的でやや上品な印象がある。","e":"\"一會兒A, 一會兒B\" shows a state or action alternating rapidly between two things. It reads slightly more neutral/written than the more colloquial \"一下A一下B\".","k":"'一會兒A, 一會兒B'는 상태나 동작이 짧은 간격으로 번갈아 바뀜을 나타낸다. 더 구어적인 '一下A一下B'보다 약간 더 격식 있는 느낌이다."},"eg":[{"z":"他一個人就扮演了四、五個角色，<em>一會兒是公車司機，一會兒是老闆</em>。","py":"Tā yí ge rén jiù bànyǎnle sì, wǔ ge juésè, yìhuǐer shì gōngchē sījī, yìhuǐer shì lǎobǎn.","j":"彼は一人で四、五役も演じ、ある時はバスの運転手、ある時は社長だった。","e":"He played four or five roles all by himself — one moment a bus driver, the next moment a boss.","k":"그는 혼자서 네다섯 역을 연기했는데, 어떤 때는 버스 기사였고 어떤 때는 사장이었다."},{"z":"妹妹<em>一會兒哭，一會兒笑</em>，讓人猜不透她在想什麼。","py":"Mèimei yìhuǐer kū, yìhuǐer xiào, ràng rén cāibútòu tā zài xiǎng shénme.","j":"妹は泣いたかと思うと笑ったりして、何を考えているのか誰にも分からない。","e":"My little sister cries one moment and laughs the next — no one can figure out what she's thinking.","k":"여동생은 울다가도 금방 웃곤 해서, 무슨 생각을 하는지 아무도 알 수가 없다."}]},
{"id":"g4-278","cat":"特殊構文","t":"一下......一下......","g":{"j":"〜たり〜たり(口語)","e":"now...now... (colloquial)","k":"~했다가 ~했다가 (구어)"},"p":{"j":"一下＋A、一下＋B","e":"一下 + A, 一下 + B","k":"一下＋A、一下＋B"},"ex":{"j":"「一下A、一下B」は状態・動作が目まぐるしく交互に変わる様子を表す口語的な言い方。「一會兒A,一會兒B」とほぼ同じ意味だが、より話し言葉らしくカジュアル。","e":"\"一下A, 一下B\" is a colloquial way to describe a state or action changing back and forth rapidly. It's nearly synonymous with \"一會兒A, 一會兒B\" but sounds more casual and spoken.","k":"'一下A、一下B'는 상태나 동작이 빠르게 번갈아 바뀌는 모습을 나타내는 구어적 표현이다. '一會兒A,一會兒B'와 거의 같은 뜻이지만 더 구어적이고 캐주얼하다."},"eg":[{"z":"春天的天氣<em>一下冷、一下熱</em>，很容易讓人感冒。","py":"Chūntiān de tiānqì yíxià lěng, yíxià rè, hěn róngyì ràng rén gǎnmào.","j":"春の天気は寒くなったり暑くなったりして、とても風邪をひきやすい。","e":"Spring weather is cold one moment and hot the next, so it's very easy to catch a cold.","k":"봄 날씨는 추웠다 더웠다 해서 감기에 걸리기가 아주 쉽다."},{"z":"這孩子<em>一下哭、一下笑</em>，媽媽都被他弄糊塗了。","py":"Zhè háizi yíxià kū, yíxià xiào, māma dōu bèi tā nòng hútú le.","j":"この子は泣いたり笑ったりして、お母さんはすっかり困惑してしまった。","e":"This kid cries one moment and laughs the next — his mom is totally confused.","k":"이 아이는 울다가 웃다가 해서 엄마가 완전히 헷갈려 버렸다."}]},
{"id":"g4-279","cat":"接続","t":"既......又......","g":{"j":"〜でもあり〜でもある","e":"both...and...","k":"~하기도 하고 ~하기도 하다"},"p":{"j":"既＋A，又＋B","e":"既 + A, 又 + B","k":"既＋A，又＋B"},"ex":{"j":"「既A又B」は二つの性質や動作が同時に成り立つことを表す書き言葉寄りの表現。AとBは通常似た長さ・品詞で対句のように並べる。","e":"\"既A又B\" shows two qualities or actions both being true at once; it's a slightly more written-style expression, and A/B are usually parallel in length and part of speech.","k":"'既A又B'는 두 가지 성질이나 동작이 동시에 성립함을 나타내는 다소 문어적인 표현이다. A와 B는 보통 길이와 품사가 비슷하게 대구를 이룬다."},"eg":[{"z":"這家賣的水果<em>既新鮮又好吃</em>。","py":"Zhè jiā mài de shuǐguǒ jì xīnxiān yòu hǎochī.","j":"この店が売っている果物は新鮮でおいしい。","e":"The fruit this shop sells is both fresh and delicious.","k":"이 가게에서 파는 과일은 신선하고 맛있다."},{"z":"這個工作<em>既輕鬆又能賺不少錢</em>，大家都想做。","py":"Zhège gōngzuò jì qīngsōng yòu néng zhuàn bùshǎo qián, dàjiā dōu xiǎng zuò.","j":"この仕事は楽な上にけっこう稼げるので、みんなやりたがっている。","e":"This job is both easy and pays fairly well, so everyone wants to do it.","k":"이 일은 편하고 돈도 꽤 벌 수 있어서 다들 하고 싶어 한다."}]},
{"id":"g4-280","cat":"アスペクト","t":"一V起","g":{"j":"〜し始めると","e":"as soon as [action] starts","k":"~하기 시작하면"},"p":{"j":"一＋V＋起，S＋就/都...","e":"一 + V + 起, S + then...","k":"一＋V＋起，S＋就/都..."},"ex":{"j":"「一V起」は「〜し始めるとすぐに」という意味で、後ろにその結果として起こる変化や反応が続く。「一V就」と似ているが、「起」は話題や動作が「持ち上がる」語感を伴う。","e":"\"一V起\" means \"as soon as [action] starts\", followed by the resulting change or reaction. It's similar to \"一V就\", but \"起\" adds a sense of the topic/action \"coming up\" or being brought up.","k":"'一V起'는 '~하기 시작하자마자'라는 뜻으로, 뒤에 그로 인한 변화나 반응이 이어진다. '一V就'와 비슷하지만 '起'는 화제나 동작이 '떠오르다/시작되다'라는 어감을 더한다."},"eg":[{"z":"<em>一聊起</em>喜歡的食物，人們都變得十分感興趣。","py":"Yì liáoqǐ xǐhuān de shíwù, rénmen dōu biànde shífēn gǎn xìngqù.","j":"好きな食べ物の話になると、みんなとても興味を持つようになる。","e":"As soon as the topic turns to favorite foods, everyone becomes very interested.","k":"좋아하는 음식 이야기가 시작되면 사람들은 모두 아주 흥미로워한다."},{"z":"<em>一想起</em>小時候的事，奶奶就笑了。","py":"Yì xiǎngqǐ xiǎoshíhòu de shì, nǎinai jiù xiào le.","j":"おばあちゃんは子供のころのことを思い出すと、いつも笑う。","e":"As soon as Grandma recalls something from her childhood, she laughs.","k":"할머니는 어릴 때 일이 생각나면 바로 웃으신다."}]},
{"id":"g4-281","cat":"アスペクト","t":"V起N（來）","g":{"j":"動作や状態が始まる(意外な変化)","e":"starting a new action/role (often surprising)","k":"새로운 동작이나 상태가 시작됨(의외의 변화)"},"p":{"j":"V＋起＋N＋來(＋了)","e":"V + 起 + N + 來 (+ 了)","k":"V + 起 + N + 來(+了)"},"ex":{"j":"「V起N來」は動作や状態が始まったことを表し、多くは予想外の変化や態度の転換を伴う。目的語Nは起と來の間に挿入する。「V起來」(単純アスペクト、例:想起來)とは違い、目的語を挟む点に注意。","e":"\"V起N來\" marks the start of an action or state, often implying an unexpected change. The object N is inserted between 起 and 來. Don't confuse it with plain \"V起來\" (e.g. 想起來), which has no object slot.","k":"「V起N來」는 동작이나 상태가 시작됨을 나타내며 흔히 예상치 못한 변화를 뜻한다. 목적어 N은 起와 來 사이에 삽입한다. 목적어가 없는 단순 「V起來」(예: 想起來)와 혼동하지 말 것."},"eg":[{"z":"他最不愛上學，現在竟然<em>當起老師來</em>了。","py":"Tā zuì bú ài shàngxué, xiànzài jìngrán dāngqǐ lǎoshī lái le.","j":"彼はいちばん学校が嫌いだったのに、今では驚くことに先生になってしまった。","e":"He hated going to school the most, but now, surprisingly, he has actually become a teacher.","k":"그는 학교 가는 걸 가장 싫어했는데, 지금은 놀랍게도 선생님이 되어 버렸다."},{"z":"她畢業後找不到理想的工作，於是自己<em>做起生意來</em>了。","py":"Tā bìyè hòu zhǎo bú dào lǐxiǎng de gōngzuò, yúshì zìjǐ zuòqǐ shēngyì lái le.","j":"彼女は卒業後理想の仕事が見つからず、そこで自分でビジネスを始めた。","e":"After graduating, she couldn't find her ideal job, so she started her own business.","k":"그녀는 졸업 후 원하는 일을 찾지 못해서 직접 사업을 시작했다."}]},
{"id":"g4-282","cat":"補語","t":"V光","g":{"j":"すっかり…してしまう(何も残らない)","e":"completely used up / all gone (none left)","k":"완전히 다 써버림(하나도 안 남음)"},"p":{"j":"V＋光＋(了)","e":"V + 光 (+ 了)","k":"V + 光(+了)"},"ex":{"j":"「V光」は動作の結果、対象物が一つも残っていないことを表す完成補語。「V完」は単に動作の終了を表すのに対し、「V光」は「何も残らない」という結果に重点がある。","e":"\"V光\" is a resultative complement meaning the object is completely used up, none left. Unlike \"V完\" which just marks completion, \"V光\" emphasizes nothing remains at all.","k":"「V光」는 동작의 결과로 대상이 하나도 남지 않았음을 나타내는 결과보어이다. 단순히 동작의 종료를 뜻하는 「V完」과 달리, 「V光」은 '아무것도 안 남음'을 강조한다."},"eg":[{"z":"家裡的吐司都<em>吃光</em>了。","py":"Jiālǐ de tǔsī dōu chīguāng le.","j":"家にあるトーストは全部食べてしまった(残っていない)。","e":"All the bread at home has been eaten up (none left).","k":"집에 있는 토스트를 다 먹어버렸다(하나도 안 남음)."},{"z":"弟弟一個人把整包餅乾<em>吃光</em>了。","py":"Dìdi yí ge rén bǎ zhěng bāo bǐnggān chīguāng le.","j":"弟は一人で袋いっぱいのビスケットを全部食べてしまった。","e":"My younger brother ate up a whole bag of cookies all by himself.","k":"남동생이 혼자서 과자 한 봉지를 다 먹어버렸다."}]},
{"id":"g4-283","cat":"接続","t":"因為......的關係","g":{"j":"…のため/…という理由で(原因)","e":"because of ... (reason/cause)","k":"…때문에(원인)"},"p":{"j":"因為＋原因＋的關係，(結果)","e":"因為 + Reason + 的關係, (Result)","k":"因為 + 원인 + 的關係, (결과)"},"ex":{"j":"原因・理由を客観的・ぼかした言い方で述べる表現。単純な「因為」より柔らかく、責任を明確にしたくない場面でよく使う。後半に「所以」を伴うことが多い。","e":"A softer, more indirect way to state a cause than plain \"因為\", often used to avoid pinning blame directly. Commonly paired with \"所以\" in the result clause.","k":"단순한 「因為」보다 더 완곡하게 원인을 말하는 표현으로, 책임을 직접 밝히고 싶지 않을 때 자주 쓴다. 뒤에 「所以」와 함께 쓰이는 경우가 많다."},"eg":[{"z":"<em>因為工作的關係</em>，哥哥手機常常關機，所以很難聯絡到他。","py":"Yīnwèi gōngzuò de guānxì, gēge shǒujī chángcháng guānjī, suǒyǐ hěn nán liánluò dào tā.","j":"仕事のため、兄はよく携帯の電源を切っているので、なかなか連絡がつかない。","e":"Because of work, my older brother often turns off his phone, so it's hard to reach him.","k":"일 때문에 형(오빠)은 휴대폰을 자주 꺼놓아서 연락하기가 어렵다."},{"z":"<em>因為天氣的關係</em>，今天的活動改到室內舉行。","py":"Yīnwèi tiānqì de guānxì, jīntiān de huódòng gǎidào shìnèi jǔxíng.","j":"天気のため、今日の活動は室内で行われることに変更された。","e":"Because of the weather, today's event has been changed to be held indoors.","k":"날씨 때문에 오늘 행사는 실내에서 진행하도록 변경되었다."}]},
{"id":"g4-284","cat":"接続","t":"另外","g":{"j":"それ以外に/さらに(追加)","e":"additionally, separately (addition)","k":"그 외에/또한(추가)"},"p":{"j":"…，另外＋(還)＋補足內容","e":"..., 另外 (+ 還) + additional information","k":"…, 另外(+還)+추가 내용"},"ex":{"j":"前述の内容とは別に、追加の情報を提示するときに使う。「而且」は前の内容を強調して積み重ねるのに対し、「另外」は別立ての新しい事柄を付け加える点が違う。","e":"Used to add a separate, additional piece of information apart from what was just said. Unlike \"而且\", which piles on emphasis to the same point, \"另外\" introduces a distinct extra item.","k":"앞서 말한 내용과는 별도로 추가 정보를 제시할 때 쓴다. 앞의 내용을 강조하며 덧붙이는 「而且」와 달리, 「另外」는 별개의 새로운 사항을 추가한다는 점이 다르다."},"eg":[{"z":"這間餐廳環境很不錯，<em>另外</em>還提供兒童免費的遊戲空間。","py":"Zhè jiān cāntīng huánjìng hěn búcuò, lìngwài hái tígōng értóng miǎnfèi de yóuxì kōngjiān.","j":"このレストランは雰囲気がとても良く、それ以外に子ども向けの無料遊び場も提供している。","e":"This restaurant has a great atmosphere; additionally, it also offers a free play area for children.","k":"이 식당은 분위기가 정말 좋고, 그 외에 아이들을 위한 무료 놀이 공간도 제공한다."},{"z":"這家店的咖啡很好喝，<em>另外</em>甜點也很受歡迎。","py":"Zhè jiā diàn de kāfēi hěn hǎohē, lìngwài tiándiǎn yě hěn shòu huānyíng.","j":"この店のコーヒーはとてもおいしく、それ以外にデザートも人気がある。","e":"The coffee at this shop is delicious; additionally, the desserts are also very popular.","k":"이 가게 커피는 정말 맛있고, 그 외에 디저트도 인기가 많다."}]},
{"id":"g4-285","cat":"接続","t":"再加上","g":{"j":"それに加えて(累加・重ね理由)","e":"on top of that, in addition (cumulative reason)","k":"게다가/그 위에(누적 이유)"},"p":{"j":"…，再加上＋追加の原因/条件，(結果)","e":"..., 再加上 + additional cause/condition, (result)","k":"…, 再加上+추가 원인/조건, (결과)"},"ex":{"j":"既にある原因に別の原因・条件を積み重ねて、結果を強める言い方。「另外」が並列的な追加情報を出すのに対し、「再加上」は原因・理由が積み重なって結果に至る因果関係を強調する。","e":"Piles an extra cause or condition onto an existing one to strengthen the result, emphasizing cumulative causation. Unlike \"另外\", which adds parallel information, \"再加上\" stresses that the reasons stack up to produce the outcome.","k":"이미 있는 원인에 또 다른 원인이나 조건을 더해 결과를 강조하는 표현이다. 병렬적 추가 정보를 제시하는 「另外」와 달리, 「再加上」은 원인들이 쌓여 결과로 이어지는 인과관계를 강조한다."},"eg":[{"z":"哥哥現在工作穩定，<em>再加上</em>之前存的錢，所以日子過得還不錯。","py":"Gēge xiànzài gōngzuò wěndìng, zài jiāshàng zhīqián cún de qián, suǒyǐ rìzi guò de hái búcuò.","j":"兄は今仕事が安定していて、それに加えて以前貯めたお金もあるので、生活はまあ悪くない。","e":"My older brother's job is stable now, and on top of that he has money saved from before, so life is going pretty well.","k":"형(오빠)은 지금 일이 안정적이고, 게다가 예전에 모아둔 돈도 있어서 생활이 꽤 괜찮다."},{"z":"這家店位置好，<em>再加上</em>老闆很親切，所以生意一直很好。","py":"Zhè jiā diàn wèizhì hǎo, zài jiāshàng lǎobǎn hěn qīnqiè, suǒyǐ shēngyì yìzhí hěn hǎo.","j":"この店は場所がよく、さらに店主がとても親切なので、いつも繁盛している。","e":"This shop has a great location, and on top of that the owner is very friendly, so business is always good.","k":"이 가게는 위치가 좋고, 게다가 주인이 아주 친절해서 장사가 늘 잘된다."}]},
{"id":"g4-286","cat":"接続","t":"不只......而且/還/也......","g":{"j":"「〜だけでなく、その上/さらに/も〜」","e":"not only...but also...","k":"~뿐만 아니라 게다가/또한 ~"},"p":{"j":"A + 不只 + B1，而且/還/也 + B2","e":"A + 不只 + B1, 而且/還/也 + B2","k":"A + 不只 + B1, 而且/還/也 + B2"},"ex":{"j":"「不只」は「不僅」と同義で、後半の「而且/還/也」のどれかと必ずペアで使い、前の内容にさらに一段階付け加える。「不只」だけを単独で使うと文が未完成に感じられる点に注意。","e":"\"不只\" pairs with 而且/還/也 to add an extra point beyond the first, like \"not only...but also.\" A common mistake is dropping the second half, leaving 不只 alone, which sounds incomplete.","k":"「不只」는 반드시 而且/還/也 중 하나와 짝을 이뤄 앞 내용에 정보를 더할 때 쓴다. 뒤의 짝을 빼고 不只만 쓰면 문장이 미완성처럼 들린다."},"eg":[{"z":"這個杯子的設計<em>不只好看而且還很方便</em>。","py":"Zhège bēizi de shèjì bùzhǐ hǎokàn érqiě hái hěn fāngbiàn.","j":"このコップのデザインはきれいなだけでなく、その上とても使いやすい。","e":"This cup's design is not only good-looking, but also very convenient.","k":"이 컵의 디자인은 예쁠 뿐만 아니라 게다가 아주 편리하다."},{"z":"這家餐廳<em>不只便宜，而且還很好吃</em>。","py":"Zhè jiā cāntīng bùzhǐ piányí, érqiě hái hěn hǎochī.","j":"このレストランは安いだけでなく、しかもとてもおいしい。","e":"This restaurant is not only cheap, but also very delicious.","k":"이 식당은 저렴할 뿐만 아니라 게다가 아주 맛있다."}]},
{"id":"g4-287","cat":"接続","t":"除了......之外......","g":{"j":"「〜のほかに(も)〜」「〜以外は〜」","e":"besides/except for...","k":"~외에(도)/~외에는~"},"p":{"j":"除了 + A + 之外，(也/還/都/不) + B","e":"除了 + A + 之外, (也/還/都/不) + B","k":"除了 + A + 之외, (也/還/都/不) + B"},"ex":{"j":"「除了A之外」は後ろに「也/還」が続けば「Aに加えて」という追加の意味、この例のように「不/都」が続けば「A以外は〜ない」という限定・排他の意味になる。どちらか文脈で見極める必要がある。","e":"\"除了...之外\" means \"in addition to\" when followed by 也/還, but here it pairs with 不 to mean \"except for/only,\" as in \"besides water, she drinks nothing else.\" Learners often mistranslate it as always additive.","k":"「除了...之외」는 뒤에 也/還가 오면 '~외에도'라는 추가 의미이지만, 이 문장처럼 不와 함께 쓰이면 '~외에는 안 한다'는 배타적 의미가 된다. 항상 추가 의미로 오역하지 않도록 주의."},"eg":[{"z":"姐姐平常<em>除了喝水之外</em>，不喝其他的飲料。","py":"Jiějie píngcháng chúle hē shuǐ zhīwài, bù hē qítā de yǐnliào.","j":"姉は普段、水を飲む以外、ほかの飲み物は飲まない。","e":"Besides drinking water, my older sister usually doesn't drink any other beverages.","k":"언니는 평소에 물 마시는 것 외에는 다른 음료를 마시지 않는다."},{"z":"我<em>除了中文之外</em>，還會說一點日文。","py":"Wǒ chúle Zhōngwén zhīwài, hái huì shuō yìdiǎn Rìwén.","j":"私は中国語のほかに、日本語も少し話せる。","e":"Besides Chinese, I can also speak a little Japanese.","k":"나는 중국어 외에도 일본어를 조금 할 수 있다."}]},
{"id":"g4-288","cat":"特殊構文","t":"像......什麼的","g":{"j":"「〜とか〜など」(口語の例示列挙)","e":"like...and so on","k":"~같은 것들"},"p":{"j":"像 + 例1、例2、例3 + 什麼的","e":"像 + example1, example2, example3 + 什麼的","k":"像 + 예1, 예2, 예3 + 什麼的"},"ex":{"j":"「像A、B、C什麼的」は口語で具体例をいくつか挙げて「〜など」とまとめる表現。「等等」よりくだけた言い方で、あらたまった書きことばにはあまり使わない。","e":"\"像...什麼的\" lists a few examples casually and closes with \"and so on,\" similar to spoken \"like...and stuff.\" It's more colloquial than 等等 and is rarely used in formal writing.","k":"「像...什麼的」는 구어체로 몇 가지 예를 나열하고 '~같은 것들'로 마무리하는 표현이다. 等等보다 캐주얼하며 문어체에는 잘 쓰지 않는다."},"eg":[{"z":"臺灣有些食物，<em>像臭豆腐、大腸麵線、豬血糕什麼的</em>，都是以前我沒吃過的。","py":"Táiwān yǒuxiē shíwù, xiàng chòudòufu, dàcháng miànxiàn, zhūxiěgāo shénme de, dōu shì yǐqián wǒ méi chīguò de.","j":"台湾には臭豆腐や大腸麵線、豚血糕などの食べ物があり、どれも私が以前食べたことのなかったものだ。","e":"Taiwan has some foods — like stinky tofu, pig-intestine noodles, and pig's-blood cake — that I had never eaten before.","k":"대만에는 취두부, 다창몐셴, 주쉐가오 같은 음식들이 있는데, 모두 내가 예전에 먹어본 적 없는 것들이다."},{"z":"這家店賣的東西，<em>像珍珠奶茶、雞排什麼的</em>，都很受歡迎。","py":"Zhè jiā diàn mài de dōngxi, xiàng zhēnzhū nǎichá, jīpái shénme de, dōu hěn shòu huānyíng.","j":"この店で売っているもの、例えばタピオカミルクティーやフライドチキンなどは、みんなとても人気がある。","e":"The things this shop sells, like bubble milk tea and fried chicken and so on, are all very popular.","k":"이 가게에서 파는 것들, 예를 들면 버블밀크티, 프라이드치킨 같은 것들은 모두 인기가 많다."}]},
{"id":"g4-289","cat":"特殊構文","t":"......而已","g":{"j":"「〜にすぎない、〜だけだ」","e":"just/only, nothing more","k":"~일 뿐이다"},"p":{"j":"(只/只不過) + 動詞句/是〜 + 而已","e":"(只/只不過) + verb phrase/是〜 + 而已","k":"(只/只不過) + 동사구/是~ + 而已"},"ex":{"j":"文末の「而已」は「只」「只不過」とセットで使われ、「〜にすぎない」と程度・範囲を小さく見せる働きをする。「而已」単独でも使えるが、「只」等と併用する方が自然で意味も強調される。","e":"The sentence-final particle 而已 downplays scope, meaning \"just/merely,\" and is usually paired with 只 or 只不過 for emphasis. Using 而已 alone without 只 is possible but sounds less natural.","k":"문미 조사 「而已」는 只/只不過와 함께 쓰여 '~에 불과하다'는 뜻으로 범위를 축소한다. 只 없이 而已만 써도 되지만 함께 쓰는 것이 더 자연스럽다."},"eg":[{"z":"第一次上課的內容<em>只不過是教一些基本動作而已</em>。","py":"Dì-yī cì shàngkè de nèiróng zhǐbúguò shì jiāo yìxiē jīběn dòngzuò éryǐ.","j":"初回の授業の内容は、いくつかの基本動作を教えるだけにすぎなかった。","e":"The content of the first class was merely teaching some basic movements.","k":"첫 수업 내용은 그저 몇 가지 기본 동작을 가르치는 것에 불과했다."},{"z":"我不是生氣，<em>只是有點累而已</em>。","py":"Wǒ bú shì shēngqì, zhǐshì yǒudiǎn lèi éryǐ.","j":"私は怒っているのではなく、ただちょっと疲れているだけだ。","e":"I'm not angry, just a bit tired, that's all.","k":"나는 화난 게 아니라 그냥 좀 피곤할 뿐이다."}]},
{"id":"g4-290","cat":"介詞","t":"以+內/外/左/右/東/西/南/北（位置）","g":{"j":"「〜以内/以外/以東/以西/以南/以北」など(基準点からの位置・範囲)","e":"within/outside/east/west... of a reference point","k":"~이내/이외/동쪽/서쪽 등 (기준점 위치)"},"p":{"j":"基準點 + 以 + 內/外/左/右/東/西/南/北","e":"reference point + 以 + 內/外/左/右/東/西/南/北","k":"기준점 + 以 + 內/外/左/右/東/西/南/北"},"ex":{"j":"「以」は基準となる場所や物の後ろに付けて範囲や方向を示す。「以內」は基準を含む場合が多いが文脈次第。「以左/以右」は日常会話より地図や書面でよく使われる。","e":"\"以\" attaches after a reference point to mark range or direction; \"以內\" usually includes the boundary itself, though context matters. \"以左/以右\" appear more in maps or formal writing than in everyday speech.","k":"「以」는 기준점 뒤에 붙어 범위나 방향을 나타낸다. 「以內」는 대개 그 경계를 포함하지만 문맥에 따라 다르다. 「以左/以右」는 일상 회화보다 지도나 문서에서 더 자주 쓰인다."},"eg":[{"z":"捷運站黃線<em>以內</em>的範圍不能吃東西。","py":"Jiéyùn zhàn huángxiàn yǐnèi de fànwéi bù néng chī dōngxi.","j":"MRT駅の黄色い線の内側の範囲では、物を食べてはいけない。","e":"You can't eat inside the yellow line at the MRT station.","k":"MRT역 노란 선 안쪽 구역에서는 음식을 먹으면 안 된다."},{"z":"這條線<em>以外</em>的地方就不是我們學校的範圍了。","py":"Zhè tiáo xiàn yǐwài de dìfāng jiù bú shì wǒmen xuéxiào de fànwéi le.","j":"この線の外側は、もう私たちの学校の範囲ではない。","e":"The area outside this line is no longer within our school's boundary.","k":"이 선 바깥쪽은 이제 우리 학교 구역이 아니다."}]},
{"id":"g4-291","cat":"特殊構文","t":"說到/談到/講到","g":{"j":"話題を切り出す","e":"introducing a topic","k":"화제를 꺼내다"},"p":{"j":"說到/談到/講到＋話題，…","e":"說到/談到/講到 + topic, ...","k":"說到/談到/講到 + 화제, …"},"ex":{"j":"「說到/談到/講到」は新しい話題を切り出す時に文頭で使う。「話題について言えば」の意味。「對……來說」(立場)や「拿……來說」(例示)と役割が違うので混同しないこと。","e":"Use 說到/談到/講到 at the start of a sentence to open a new topic, like \"speaking of X.\" It only shifts topic, unlike 對……來說 (stance) or 拿……來說 (example) taught nearby.","k":"說到/談到/講到는 새로운 화제를 꺼낼 때 문장 맨 앞에 쓴다. 입장을 말하는 對……來說, 예시를 드는 拿……來說와 역할이 다르니 혼동하지 말아야 한다."},"eg":[{"z":"<em>談到</em>資訊設備，這間圖書館的電腦都是最新的。","py":"Tándào zīxùn shèbèi, zhè jiān túshūguǎn de diànnǎo dōu shì zuìxīn de.","j":"情報設備について言えば、この図書館のパソコンはすべて最新のものだ。","e":"Speaking of IT equipment, all the computers in this library are the latest models.","k":"정보 기기로 말하자면, 이 도서관의 컴퓨터는 모두 최신형이다."},{"z":"<em>說到</em>旅遊，我最想去的地方是日本。","py":"Shuōdào lǚyóu, wǒ zuì xiǎng qù de dìfāng shì Rìběn.","j":"旅行と言えば、私が一番行きたいところは日本だ。","e":"Speaking of travel, the place I most want to go is Japan.","k":"여행으로 말하자면, 내가 가장 가고 싶은 곳은 일본이다."}]},
{"id":"g4-292","cat":"特殊構文","t":"拿......來說","g":{"j":"例を挙げて言うと","e":"taking X as an example","k":"X를 예로 들면"},"p":{"j":"拿＋X＋來說，…","e":"拿 + X + 來說, ...","k":"拿 + X + 來說, …"},"ex":{"j":"「拿……來說」は具体例を挙げる時に使い、「Xを例にとると」の意味。Xの後の「來說」は省略できない。「對……來說」(立場を述べる)とは目的が違うので注意。","e":"拿……來說 introduces a concrete example, meaning \"taking X for example.\" Never drop 來說 after X. Unlike 對……來說, which states a viewpoint, this pattern is for illustrating with a case.","k":"拿……來說는 구체적인 예를 들 때 쓰며 \"X를 예로 들면\"이라는 뜻이다. X 뒤의 來說는 생략할 수 없다. 입장을 말하는 對……來說와 목적이 다르니 주의해야 한다."},"eg":[{"z":"<em>拿臺灣來說</em>，現在的老年人口越來越多，出生率卻越來越低。","py":"Ná Táiwān lái shuō, xiànzài de lǎonián rénkǒu yuè lái yuè duō, chūshēnglǜ què yuè lái yuè dī.","j":"台湾を例にとると、今は高齢者人口がますます増えているのに、出生率はますます下がっている。","e":"Taking Taiwan as an example, the elderly population keeps growing while the birth rate keeps falling.","k":"대만을 예로 들면, 지금 노인 인구는 갈수록 늘어나는데 출생률은 갈수록 낮아지고 있다."},{"z":"<em>拿捷運來說</em>，尖峰時間真的很擠。","py":"Ná jiéyùn lái shuō, jiānfēng shíjiān zhēn de hěn jǐ.","j":"MRTを例にとると、ラッシュアワーは本当に混雑している。","e":"Take the MRT for example — it's really crowded during rush hour.","k":"대만 지하철(MRT)을 예로 들면, 러시아워에는 정말 붐빈다."}]},
{"id":"g4-293","cat":"特殊構文","t":"對......來說","g":{"j":"Xの立場から言うと","e":"from X's perspective","k":"X의 입장에서 보면"},"p":{"j":"對＋X＋來說，…","e":"對 + X + 來說, ...","k":"對 + X + 來說, …"},"ex":{"j":"「對……來說」は「Xの立場から言うと」の意味で、話し手の視点や評価を述べる。「拿……來說」(例示)と混同しないこと。Xの後の「來說」は省略できない。","e":"對……來說 means \"from X's point of view,\" used to state how something appears or matters to X. Don't confuse it with 拿……來說 (giving an example); never omit 來說 after X.","k":"對……來說는 \"X의 입장에서 보면\"이라는 뜻으로 화자의 관점이나 평가를 말할 때 쓴다. 예시를 드는 拿……來說와 혼동하지 말고, X 뒤의 來說는 생략할 수 없다."},"eg":[{"z":"<em>對幼兒來說</em>，遊戲就是他生活中最重要的事。","py":"Duì yòu'ér lái shuō, yóuxì jiùshì tā shēnghuó zhōng zuì zhòngyào de shì.","j":"幼児にとって、遊びは彼の生活の中で最も重要なことだ。","e":"For a young child, playing is the most important thing in his life.","k":"유아에게 있어 놀이는 그의 생활에서 가장 중요한 일이다."},{"z":"<em>對外國人來說</em>，寫繁體字比認繁體字難多了。","py":"Duì wàiguórén lái shuō, xiě fántǐzì bǐ rèn fántǐzì nán duō le.","j":"外国人にとって、繁体字を書くのは繁体字を読むより、ずっと難しい。","e":"For foreigners, writing traditional characters is much harder than recognizing them.","k":"외국인에게 있어 번체자를 쓰는 것은 번체자를 알아보는 것보다 훨씬 더 어렵다."}]},
{"id":"g4-294","cat":"否定","t":"不是","g":{"j":"婉曲な否定(あまり~ない)","e":"softened negation (\"not really/very\")","k":"완곡한 부정 (그다지 ~ 아니다)"},"p":{"j":"不是＋很/太＋形容詞","e":"不是 + 很/太 + adjective","k":"不是 + 很/太 + 형용사"},"ex":{"j":"ここでの「不是」は「不是＋很/太＋形容詞」の形で、断定を避け婉曲に否定する言い方。単純な「不」より柔らかい語気になる。「~ではない」という判断文の「不是」と混同しないこと。","e":"Here 不是 + 很/太 + adjective softens a negative statement, like \"not really/not very,\" gentler than plain 不. Don't mistake this for 不是 used as \"is not\" in an identity sentence.","k":"여기서 不是는 \"不是+很/太+형용사\" 형태로 단정을 피하고 완곡하게 부정하는 표현이다. 단순한 不보다 어조가 부드럽다. \"~이 아니다\"라는 판단문의 不是와 혼동하지 않아야 한다."},"eg":[{"z":"這句話的意思<em>不是</em>很清楚，可以說明一下嗎？","py":"Zhè jù huà de yìsi bú shì hěn qīngchǔ, kěyǐ shuōmíng yíxià ma?","j":"この文の意味はあまりはっきりしません。説明していただけますか？","e":"The meaning of this sentence isn't very clear — could you explain it?","k":"이 문장의 뜻이 그다지 분명하지 않은데, 설명해 주실 수 있나요?"},{"z":"這家店的東西<em>不是</em>很貴，你可以放心買。","py":"Zhè jiā diàn de dōngxi bú shì hěn guì, nǐ kěyǐ fàngxīn mǎi.","j":"この店のものはそれほど高くないので、安心して買っていいですよ。","e":"The things at this shop aren't very expensive, so you can buy with confidence.","k":"이 가게 물건은 그다지 비싸지 않으니 안심하고 사도 돼요."}]},
{"id":"g4-295","cat":"数量","t":"不到","g":{"j":"(数量が)~に満たない","e":"less than (a quantity)","k":"(수량이) ~에 못 미치다"},"p":{"j":"不到＋数量","e":"不到 + quantity","k":"不到 + 수량"},"ex":{"j":"「不到」は数量や時間の前に置き、「~に満たない」という意味を表す。「不夠」(足りない、主観的な不足感)とは異なり、「不到」は客観的にある数値に達していないことを述べる。","e":"不到 goes before a number or amount to mean \"less than / not even X,\" stating an objective shortfall. Distinguish it from 不夠 (\"not enough\"), which expresses subjective insufficiency, not a precise quantity.","k":"不到는 수량이나 시간 앞에 놓여 \"~에 못 미치다/~가 안 되다\"라는 뜻을 나타낸다. 주관적 부족을 말하는 不夠와 달리, 不到는 특정 수치에 도달하지 못했다는 객관적 사실을 나타낸다."},"eg":[{"z":"身高<em>不到</em>九十公分的兒童可以免費入場。","py":"Shēngāo bú dào jiǔshí gōngfēn de értóng kěyǐ miǎnfèi rùchǎng.","j":"身長が90センチに満たない子供は無料で入場できる。","e":"Children under 90 centimeters tall can enter for free.","k":"키가 90센티미터가 안 되는 어린이는 무료로 입장할 수 있다."},{"z":"這場電影<em>不到</em>兩個小時就結束了。","py":"Zhè chǎng diànyǐng bú dào liǎng ge xiǎoshí jiù jiéshù le.","j":"この映画は2時間もかからずに終わった。","e":"This movie ended in less than two hours.","k":"이 영화는 두 시간도 안 돼서 끝났다."}]},
{"id":"g4-296","cat":"特殊構文","t":"怎麼（一）回事","g":{"j":"「どういうことか」を尋ねる","e":"asking what happened / what's going on","k":"\"무슨 일인지\" 묻기"},"p":{"j":"是＋怎麼（一）回事＋（嗎）","e":"shì + zěnme (yī) huí shì (+ ma)","k":"是 + 怎麼（一）回事 (+ 嗎)"},"ex":{"j":"「怎麼回事」は起きた事情や原因を尋ねる口語表現。「一」を入れても意味は同じで語気がやや柔らかい。疑問詞「什麼」と混同して「什麼回事」にしないよう注意。","e":"\"怎麼(一)回事\" is a colloquial way to ask what happened or why something occurred; adding \"一\" softens the tone slightly without changing meaning. Don't confuse it with \"什麼事\" (what matter), which just asks about a topic, not a cause.","k":"\"怎麼(一)回事\"은 무슨 일이 있었는지, 원인이 무엇인지 구어체로 묻는 표현이다. \"一\"를 넣어도 의미는 같고 어감만 약간 부드러워진다. \"什麼事\"(무슨 일)와 혼동해서 원인을 묻는 뉘앙스를 잃지 않도록 주의."},"eg":[{"z":"聽說姐姐跟室友吵架了，你知道是<em>怎麼一回事</em>嗎？","py":"Tīngshuō jiějie gēn shìyǒu chǎojià le, nǐ zhīdào shì zěnme yì huí shì ma?","j":"姐が ルームメート と喧嘩したと聞いたけど、どういうことか知ってる？","e":"I heard your older sister had a fight with her roommate — do you know what happened?","k":"언니가 룸메이트랑 싸웠다고 들었는데, 무슨 일인지 알아?"},{"z":"我今天早上手機突然打不開，到底是<em>怎麼一回事</em>？","py":"Wǒ jīntiān zǎoshang shǒujī túrán dǎ bù kāi, dàodǐ shì zěnme yì huí shì?","j":"今朝携帯が急に開かなくなった、いったいどういうことなんだろう？","e":"My phone suddenly wouldn't turn on this morning — what on earth is going on?","k":"오늘 아침에 휴대폰이 갑자기 안 켜지는데, 도대체 무슨 일이야?"}]},
{"id":"g4-297","cat":"数量","t":"量詞重疊","g":{"j":"量詞を重ねて「どれも／みんな」の意味を表す","e":"doubling a measure word to mean \"every single one\"","k":"양사를 겹쳐 써서 \"하나하나 다\"라는 뜻을 나타냄"},"p":{"j":"量詞＋量詞（＋都）＋VP","e":"MW + MW (+ dōu) + VP","k":"量詞 + 量詞 (+ 都) + VP"},"ex":{"j":"量詞を AA の形で重ねると「例外なく全部」という意味になり、後ろによく「都」を伴う。すべての量詞が重ねられるわけではなく、「個個・張張・件件・朵朵」など限られた語で使う。","e":"Reduplicating a measure word (AA form) means \"every single one without exception,\" and is usually followed by \"都\". Not all measure words can be doubled this way — it's common with words like 個個, 張張, 件件, 朵朵, but not with every measure word.","k":"양사를 AA 형태로 겹치면 \"예외 없이 전부\"라는 뜻이 되며 뒤에 흔히 \"都\"가 온다. 모든 양사를 겹쳐 쓸 수 있는 것은 아니고 個個, 張張, 件件, 朵朵처럼 정해진 단어들에서 주로 쓰인다."},"eg":[{"z":"今年的玫瑰花<em>朵朵</em>都開得很好。","py":"Jīnnián de méiguīhuā duǒduǒ dōu kāi de hěn hǎo.","j":"今年のバラは一輪一輪(どれも)よく咲いている。","e":"This year's roses have all bloomed beautifully, every single one.","k":"올해 장미는 송이송이 다 예쁘게 피었다."},{"z":"這次比賽的選手<em>個個</em>都很厲害。","py":"Zhè cì bǐsài de xuǎnshǒu gègè dōu hěn lìhài.","j":"今回の試合の選手はみんなすごい。","e":"The athletes in this competition are all amazing, each and every one.","k":"이번 경기 선수들은 다들 대단하다."}]},
{"id":"g4-298","cat":"特殊構文","t":"害","g":{"j":"好ましくない結果を引き起こす「〜のせいで」","e":"\"because of X, (a bad result happens)\"","k":"좋지 않은 결과를 초래함, \"~때문에\""},"p":{"j":"（原因）＋害＋（人）＋（負面結果）","e":"(cause) + hài + (person) + (negative result)","k":"(원인) + 害 + (사람) + (부정적 결과)"},"ex":{"j":"「害」は原因が誰かに悪い結果や迷惑をもたらしたことを表す動詞。「因為」が単なる理由説明なのに対し、「害」には話し手の不満や被害の気持ちが含まれる点が違う。","e":"\"害\" is a verb meaning \"to cause (someone) a bad result,\" carrying a sense of blame or annoyance. Unlike the neutral \"因為\" (because), \"害\" implies the speaker feels inconvenienced or wronged by the cause.","k":"\"害\"는 원인이 누군가에게 나쁜 결과나 피해를 가져왔음을 나타내는 동사다. 단순히 이유를 설명하는 \"因為\"와 달리 \"害\"에는 화자의 불만이나 피해 의식이 담겨 있다."},"eg":[{"z":"他忘了帶手機，<em>害我一整天都找不到他</em>。","py":"Tā wàng le dài shǒujī, hài wǒ yì zhěng tiān dōu zhǎo bú dào tā.","j":"彼は携帯電話を持ってくるのを忘れて、そのせいで私は一日中彼を見つけられなかった。","e":"He forgot to bring his phone, so I couldn't find him all day because of it.","k":"그는 휴대폰 가져오는 걸 잊어버려서, 그 때문에 나는 하루 종일 그를 찾을 수 없었다."},{"z":"下雨<em>害</em>我們的野餐取消了。","py":"Xià yǔ hài wǒmen de yěcān qǔxiāo le.","j":"雨が降ったせいで私たちのピクニックは中止になった。","e":"The rain ruined our picnic — it got canceled because of it.","k":"비가 와서 우리 소풍이 취소됐다."}]},
{"id":"g4-299","cat":"特殊構文","t":"把 ......V成......","g":{"j":"「把」構文で対象をある状態・結果に変える","e":"use \"把\" to change an object into a new state or result","k":"\"把\" 구문으로 대상을 어떤 상태·결과로 바꾸다"},"p":{"j":"把＋Ｏ＋Ｖ成＋結果","e":"bǎ + Object + V + chéng + result","k":"把 + 목적어 + 동사 + 成 + 결과"},"ex":{"j":"「把Ｏ Ｖ成……」は目的語を動作によって別のものや状態に変化させたことを表し、必ず「把」とともに使う。「變成」は主語自身の変化を表すのに対し、こちらは対象への処理の結果を示す点が違う。","e":"\"把...V成...\" shows that an object was transformed into a different thing or state through an action, and must be used with \"把\". Don't confuse it with \"變成\", which describes the subject itself changing, not something being changed by an action on an object.","k":"\"把...V成...\"은 목적어가 동작을 통해 다른 것이나 다른 상태로 바뀌었음을 나타내며 \"把\"와 함께 써야 한다. 주어 자신이 변하는 \"變成\"과 달리, 대상을 동작으로 바꾼 결과를 나타낸다는 점이 다르다."},"eg":[{"z":"請你<em>把英文翻成中文</em>。","py":"Qǐng nǐ bǎ Yīngwén fānchéng Zhōngwén.","j":"英語を中国語に翻訳してください。","e":"Please translate the English into Chinese.","k":"영어를 중국어로 번역해 주세요."},{"z":"媽媽<em>把客廳布置成</em>聖誕節的樣子。","py":"Māma bǎ kètīng bùzhì chéng Shèngdànjié de yàngzi.","j":"お母さんはリビングをクリスマスの雰囲気に飾りつけた。","e":"Mom decorated the living room to look like Christmas.","k":"엄마는 거실을 크리스마스 분위기로 꾸몄다."}]},
{"id":"g4-300","cat":"特殊構文","t":"把......V作/做......","g":{"j":"「把」構文である事物を〜と見なす／扱う","e":"use \"把\" to treat/regard something as X","k":"\"把\" 구문으로 어떤 것을 ~로 여기다/취급하다"},"p":{"j":"把＋Ｏ＋當作／當做＋Ｎ","e":"bǎ + Object + dàngzuò + N","k":"把 + 목적어 + 當作/當做 + 명사"},"ex":{"j":"「把Ｏ當作／當做Ｎ」は対象をある物事だと見なす、扱うという意味。「Ｖ成」が実際に形や状態を変化させるのに対し、「當作／做」は認識・扱い方の変化で、実体そのものは変わらない点が違う。","e":"\"把...當作/當做...\" means to regard or treat an object as something (a role, purpose, or category), without physically changing it. This differs from \"把...V成...\", where the object actually changes into a new state or form.","k":"\"把...當作/當做...\"는 대상을 어떤 것으로 여기거나 취급한다는 뜻으로, 실제로 형태가 바뀌는 것은 아니다. 실제로 상태나 형태가 변하는 \"把...V成...\"과 다른 점이다."},"eg":[{"z":"爺爺<em>把旅行當作退休之後最重要的活動</em>。","py":"Yéye bǎ lǚxíng dàngzuò tuìxiū zhīhòu zuì zhòngyào de huódòng.","j":"おじいさんは旅行を退職後最も大切な活動だと考えている。","e":"Grandpa regards traveling as the most important activity after retirement.","k":"할아버지는 여행을 은퇴 후 가장 중요한 활동으로 여긴다."},{"z":"很多人<em>把運動當作</em>紓解壓力的方法。","py":"Hěn duō rén bǎ yùndòng dàngzuò shūjiě yālì de fāngfǎ.","j":"多くの人は運動をストレス解消の方法だと考えている。","e":"Many people regard exercise as a way to relieve stress.","k":"많은 사람들은 운동을 스트레스를 푸는 방법으로 여긴다."}]},
{"id":"g4-301","cat":"特殊構文","t":"被......V作/做......","g":{"j":"~に…とみなされる(被害の受身)","e":"be regarded/treated as (passive)","k":"~로 여겨지다(피동)"},"p":{"j":"N1 ＋ 被 ＋ N2 ＋ 當作/看作 ＋ N3","e":"N1 + 被 + N2 + 當作/看作 + N3","k":"N1 + 被 + N2 + 當作/看作 + N3"},"ex":{"j":"「被+動作主+V作/做+N」で「~に…とみなされる/扱われる」を表す。「當作」「看作」など限られた動詞と結びつく点に注意。単純な受身文(被+V)と違い、結果が「~as N」であることを明示する。","e":"\"Bei + agent + V作/做 + N\" means \"is regarded/treated as N by agent.\" Only pairs with a small set of verbs like 當作/看作. Unlike a plain 被 passive, it specifies the resulting identity.","k":"\"被+행위자+V作/做+N\"는 \"~에게 …로 여겨지다/취급받다\"를 나타낸다. 當作/看作 등 제한된 동사와만 결합한다. 단순 피동문과 달리 결과가 N임을 명시한다."},"eg":[{"z":"他<em>被鄰居當作</em>小偷。","py":"Tā bèi línjū dàngzuò xiǎotōu.","j":"彼は隣人に泥棒だと思われた。","e":"He was mistaken for a thief by his neighbor.","k":"그는 이웃에게 도둑으로 오해받았다."},{"z":"那件舊外套<em>被他當作</em>睡衣穿。","py":"Nà jiàn jiù wàitào bèi tā dàngzuò shuìyī chuān.","j":"あの古い上着は彼にパジャマ代わりに着られている。","e":"That old jacket is worn by him as pajamas.","k":"그 낡은 외투는 그가 잠옷으로 입는다."}]},
{"id":"g4-302","cat":"特殊構文","t":"被......V成......","g":{"j":"~の結果…になる(被害の受身)","e":"be turned into (passive result)","k":"~로 되다(피동 결과)"},"p":{"j":"N1 ＋ 被 ＋ N2 ＋ V ＋ 成 ＋ 結果","e":"N1 + 被 + N2 + V + 成 + result","k":"N1 + 被 + N2 + V + 成 + 결과"},"ex":{"j":"「被+動作主+V成+結果」は動作の結果、ある状態や形に変化したことを表す。「V作/做」が身分・扱いを表すのに対し、「V成」は形・状態の変化を表す点が異なる。","e":"\"Bei + agent + V成 + result\" shows the action changed something into a resulting state or form. Unlike V作/做 (identity/treatment), V成 marks a change of shape or condition.","k":"\"被+행위자+V成+결과\"는 동작으로 인해 어떤 상태나 형태로 변화했음을 나타낸다. V作/做가 신분·취급을 뜻하는 것과 달리 V成은 형태·상태의 변화를 뜻한다."},"eg":[{"z":"他<em>被人打成</em>重傷。","py":"Tā bèi rén dǎ chéng zhòngshāng.","j":"彼は何者かに殴られて重傷を負った。","e":"He was beaten by someone and seriously injured.","k":"그는 누군가에게 맞아서 중상을 입었다."},{"z":"蛋糕<em>被他切成</em>八塊。","py":"Dàngāo bèi tā qiē chéng bā kuài.","j":"ケーキは彼によって8切れに切られた。","e":"The cake was cut by him into eight pieces.","k":"케이크는 그에 의해 여덟 조각으로 잘렸다."}]},
{"id":"g4-303","cat":"特殊構文","t":"賓+受（N）+V","g":{"j":"~の影響を受けて…","e":"be affected by N","k":"~의 영향을 받아"},"p":{"j":"N(主語) ＋ 受 ＋ N(原因) ＋ V(影響/歡迎等)","e":"N(subject) + 受 + N(cause) + V (影響/歡迎, etc.)","k":"N(주어) + 受 + N(원인) + V(影響/歡迎 등)"},"ex":{"j":"「(主語)受+N+V(影響など)」で「~の影響を受けて…する」ことを表す。受身の「被」と違い、「受」は良い/悪い影響どちらにも使え、「受影響」「受歡迎」のように限られた語と結びつくことが多い。","e":"\"(Subject) 受 + N + V (like 影響)\" means \"affected by N, ...happens.\" Unlike 被, 受 works for both good and bad influence and commonly pairs with fixed phrases like 受影響/受歡迎.","k":"\"(주어) 受+N+V(影響 등)\"는 \"N의 영향을 받아 ~하다\"를 뜻한다. 被와 달리 受는 좋은/나쁜 영향 모두에 쓰이며 受影響/受歡迎처럼 고정된 표현과 자주 결합한다."},"eg":[{"z":"今年香蕉<em>受產量影響</em>，價格跌得很低。","py":"Jīnnián xiāngjiāo shòu chǎnliàng yǐngxiǎng, jiàgé diē de hěn dī.","j":"今年のバナナは生産量の影響を受け、価格がとても安くなった。","e":"This year, bananas were affected by production volume, so the price dropped very low.","k":"올해 바나나는 생산량의 영향을 받아서 가격이 매우 낮게 떨어졌다."},{"z":"這次考試<em>受天氣影響</em>，很多人遲到了。","py":"Zhè cì kǎoshì shòu tiānqì yǐngxiǎng, hěn duō rén chídào le.","j":"今回の試験は天気の影響を受けて、多くの人が遅刻した。","e":"This exam was affected by the weather, so many people were late.","k":"이번 시험은 날씨의 영향을 받아서 많은 사람이 지각했다."}]},
{"id":"g4-304","cat":"副詞","t":"一般來說","g":{"j":"一般的に言うと","e":"generally speaking","k":"일반적으로 말하면"},"p":{"j":"一般來說，＋ 文","e":"一般來說, + clause","k":"一般來說, + 문장"},"ex":{"j":"文頭に置き、個別の例外を除いた「普通の場合/大まかな傾向」を述べるときに使う。断定を和らげる働きがあり、後に例外を述べる文が続くこともある。","e":"Placed at the start of a sentence to state a general tendency, setting aside exceptions. It softens an assertion and is often followed by a contrasting exception.","k":"문장 앞에 놓여 예외를 제외한 \"일반적인 경우/대체적인 경향\"을 말할 때 쓴다. 단정을 완화하는 역할을 하며 뒤에 예외를 언급하는 문장이 이어지기도 한다."},"eg":[{"z":"<em>一般來說</em>，收入越多，花費會越高。","py":"Yìbān láishuō, shōurù yuè duō, huāfèi huì yuè gāo.","j":"一般的に言えば、収入が多いほど、支出も多くなる。","e":"Generally speaking, the more income one has, the higher one's spending tends to be.","k":"일반적으로 말하면, 수입이 많을수록 지출도 많아진다."},{"z":"<em>一般來說</em>，台北的冬天比南部冷。","py":"Yìbān láishuō, Táiběi de dōngtiān bǐ nánbù lěng.","j":"一般的に言えば、台北の冬は南部より寒い。","e":"Generally speaking, winter in Taipei is colder than in the south.","k":"일반적으로 말하면, 타이베이의 겨울은 남부보다 춥다."}]},
{"id":"g4-305","cat":"話しことば","t":"你說","g":{"j":"ねえ、~だと思う?","e":"tell me, don't you think...?","k":"있잖아, ~라고 생각해?"},"p":{"j":"你說，＋ 文(疑問文など)","e":"你說, + clause (often a question)","k":"你說, + 문장(주로 의문문)"},"ex":{"j":"文頭で使い、相手に意見や判断を求めながら自分の疑問・驚きを表す話しことば表現。「你說」は文字通り「言う」ではなく「ねえ/どう思う?」に近い前置き。","e":"Used at the start of a spoken sentence to invite the listener's opinion while expressing one's own doubt or surprise. \"你說\" here isn't literal \"you say\" but more like \"tell me / what do you think.\"","k":"문장 앞에서 상대의 의견을 구하면서 자신의 의문이나 놀라움을 나타내는 구어 표현이다. \"你說\"는 문자 그대로 \"말하다\"가 아니라 \"있잖아/어떻게 생각해?\"에 가깝다."},"eg":[{"z":"<em>你說</em>這麼晚了，他還會回來吃飯嗎？","py":"Nǐ shuō zhème wǎn le, tā hái huì huílái chīfàn ma?","j":"ねえ、こんなに遅いのに、彼はまだ帰って来てご飯を食べるかな?","e":"Tell me, it's so late already—do you think he'll still come back to eat?","k":"말해봐, 이렇게 늦었는데 그가 아직 돌아와서 밥을 먹을까?"},{"z":"<em>你說</em>這種天氣，我們還要出門嗎？","py":"Nǐ shuō zhè zhǒng tiānqì, wǒmen hái yào chūmén ma?","j":"ねえ、こんな天気なのに、私たちは出かけないといけないの?","e":"Tell me, with weather like this, do we still need to go out?","k":"말해봐, 이런 날씨에 우리가 그래도 나가야 할까?"}]},
{"id":"g4-306","cat":"副詞","t":"看樣子","g":{"j":"見たところ〜のようだ","e":"it looks like / it seems that","k":"보아하니 ~인 것 같다"},"p":{"j":"看樣子＋推測內容","e":"看樣子 + inference","k":"看樣子 + 추측 내용"},"ex":{"j":"話し手の観察・印象に基づく推測を表す。「好像」と似るが、「看樣子」は視覚的な手がかりから判斷する場面でよく使われる。断定を避けたい時に使う。","e":"Expresses an inference based on what the speaker observes; similar to 好像, but 看樣子 emphasizes a judgment drawn from visible clues. Avoid using it for facts already confirmed.","k":"화자가 관찰한 것을 바탕으로 한 추측을 나타낸다. 好像와 비슷하지만 看樣子는 눈에 보이는 단서로 판단할 때 자주 쓰인다. 이미 확인된 사실에는 쓰지 않는다."},"eg":[{"z":"哥哥的身材很好，<em>看樣子</em>平時有運動的習慣。","py":"Gēge de shēncái hěn hǎo, kàn yàngzi píngshí yǒu yùndòng de xíguàn.","j":"兄は体型がいい、見たところ普段から運動する習慣があるようだ。","e":"My older brother is in great shape; it looks like he has a habit of exercising regularly.","k":"오빠는 몸매가 좋아, 보아하니 평소에 운동하는 습관이 있는 것 같다."},{"z":"天空很暗，<em>看樣子</em>快要下雨了。","py":"Tiānkōng hěn àn, kàn yàngzi kuàiyào xiàyǔ le.","j":"空が暗い、どうやらもうすぐ雨が降りそうだ。","e":"The sky is dark; it looks like it's about to rain.","k":"하늘이 어둡다, 보아하니 곧 비가 올 것 같다."}]},
{"id":"g4-307","cat":"特殊構文","t":"誰知道","g":{"j":"意外にも〜だった","e":"who would have known / unexpectedly","k":"뜻밖에도 ~하다"},"p":{"j":"誰知道＋意外な結果","e":"誰知道 + unexpected result","k":"誰知道 + 뜻밖의 결과"},"ex":{"j":"予想外の結果に対する驚きや不満を表す。文字通り「誰が知っていたか」という反語的な意味から来ている。実際の疑問文ではない点に注意。","e":"Expresses surprise or dissatisfaction at an unexpected outcome; literally a rhetorical \"who knew,\" not a real question — don't mistake it for an interrogative sentence.","k":"예상 밖의 결과에 대한 놀람이나 불만을 나타낸다. 문자 그대로 \"누가 알았겠는가\"라는 반어적 의미이며, 실제 의문문이 아니라는 점에 주의해야 한다."},"eg":[{"z":"才下了一個鐘頭的雨，<em>誰知道</em>家裡就淹水了。","py":"Cái xiàle yí ge zhōngtóu de yǔ, shéi zhīdào jiā lǐ jiù yānshuǐ le.","j":"たった1時間雨が降っただけなのに、思いがけず家が浸水してしまった。","e":"It had only rained for an hour, but who would have guessed the house would flood.","k":"겨우 한 시간 비가 내렸을 뿐인데, 뜻밖에도 집에 물이 찼다."},{"z":"他平常很小心，<em>誰知道</em>這次還是出了車禍。","py":"Tā píngcháng hěn xiǎoxīn, shéi zhīdào zhè cì háishì chūle chēhuò.","j":"彼は普段とても注意深いのに、思いがけず今回は事故に遭ってしまった。","e":"He's usually very careful, but who would have thought he'd still get into a car accident this time.","k":"그는 평소에 아주 조심스러운데, 뜻밖에도 이번에는 결국 교통사고를 당했다."}]},
{"id":"g4-308","cat":"話しことば","t":"所以啦","g":{"j":"だから〜だよ","e":"so, that's why (casual)","k":"그러니까 ~야"},"p":{"j":"所以啦＋結論","e":"所以啦 + conclusion","k":"所以啦 + 결론"},"ex":{"j":"「所以」に語気助詞「啦」がついた口語表現で、話し手の納得や軽い強調を表す。書きことばでは使わない。「所以」だけより感情がこもる。","e":"A colloquial form of 所以 with the particle 啦 added, showing the speaker's realization or mild emphasis; not used in written registers. Carries more feeling than plain 所以.","k":"所以에 어기조사 啦가 붙은 구어체 표현으로, 화자의 납득이나 가벼운 강조를 나타낸다. 문어체에는 쓰지 않으며, 所以만 쓸 때보다 감정이 더 실린다."},"eg":[{"z":"<em>所以啦</em>，下次應該早點去排隊。","py":"Suǒyǐ la, xiàcì yīnggāi zǎodiǎn qù páiduì.","j":"だから、次は早めに並びに行くべきだよ。","e":"So yeah, next time we should go line up earlier.","k":"그러니까 말이야, 다음에는 일찍 가서 줄을 서야 해."},{"z":"大家都說那家店很好吃，<em>所以啦</em>，我們今天就去吃吃看。","py":"Dàjiā dōu shuō nà jiā diàn hěn hǎochī, suǒyǐ la, wǒmen jīntiān jiù qù chīchi kàn.","j":"みんながあの店はおいしいと言っているから、だから今日食べに行ってみようよ。","e":"Everyone says that shop is delicious, so let's go try it today.","k":"다들 그 가게가 맛있다고 하니까, 그러니까 오늘 한번 먹으러 가보자."}]},
{"id":"g4-309","cat":"副詞","t":"可4","g":{"j":"本当に〜だと言える(強調)","e":"really / truly can be said to (emphatic)","k":"정말로 ~라고 할 수 있다(강조)"},"p":{"j":"可＋算是/說是＋評價","e":"可 + 算是/說是 + evaluation","k":"可 + 算是/說是 + 평가"},"ex":{"j":"「可」が副詞として「算是」「說是」などの前に置かれ、話し手の強い確信や評価を強調する。疑問や許可を表す「可以」の「可」とは別の用法なので混同しないこと。","e":"Here 可 functions as an adverb before verbs like 算是/說是 to emphasize the speaker's strong conviction; distinct from the 可 in 可以 (permission) — don't confuse the two uses.","k":"여기서 可는 부사로 算是/說是 앞에 놓여 화자의 강한 확신이나 평가를 강조한다. 허가를 나타내는 可以의 可와는 다른 용법이므로 혼동하지 않아야 한다."},"eg":[{"z":"這間牛肉麵店<em>可</em>算是臺北最有名的了。","py":"Zhè jiān niúròumiàn diàn kě suànshì Táiběi zuì yǒumíng de le.","j":"この牛肉麺の店は台北で最も有名だと言ってもいいくらいだ。","e":"This beef noodle restaurant can really be said to be the most famous one in Taipei.","k":"이 우육면 가게는 타이베이에서 정말 가장 유명하다고 할 수 있다."},{"z":"這部電影<em>可</em>說是今年最感人的作品。","py":"Zhè bù diànyǐng kě shuō shì jīnnián zuì gǎnrén de zuòpǐn.","j":"この映画は今年最も感動的な作品だと言ってもいいだろう。","e":"This movie can really be called the most moving film of the year.","k":"이 영화는 올해 가장 감동적인 작품이라고 할 수 있다."}]},
{"id":"g4-310","cat":"接続","t":"與1","g":{"j":"〜と(書きことばの接続詞)","e":"and / with (formal, written)","k":"~와/과(문어체 접속사)"},"p":{"j":"A＋與＋B","e":"A + 與 + B","k":"A + 與 + B"},"ex":{"j":"「和」「跟」の書きことば版で、正式な文章や書面でよく使われる。口語会話では「和」「跟」の方が自然。","e":"A formal written equivalent of 和/跟, common in formal writing and documents; in everyday speech 和/跟 sounds more natural.","k":"和/跟의 문어체 형태로 공식적인 글이나 문서에서 자주 쓰인다. 일상 구어에서는 和/跟가 더 자연스럽다."},"eg":[{"z":"日月潭<em>與</em>阿里山都是臺灣有名的旅遊地點。","py":"Rìyuètán yǔ Ālǐshān dōu shì Táiwān yǒumíng de lǚyóu dìdiǎn.","j":"日月潭と阿里山はどちらも台湾で有名な観光地だ。","e":"Sun Moon Lake and Alishan are both famous tourist spots in Taiwan.","k":"르웨탄과 아리산은 모두 대만에서 유명한 관광지이다."},{"z":"老師<em>與</em>學生都應該遵守學校的規定。","py":"Lǎoshī yǔ xuéshēng dōu yīnggāi zūnshǒu xuéxiào de guīdìng.","j":"先生と学生はどちらも学校の規則を守るべきだ。","e":"Both teachers and students should follow the school's rules.","k":"선생님과 학생은 모두 학교의 규정을 지켜야 한다."}]},
{"id":"g4-311","cat":"介詞","t":"與2","g":{"j":"〜と(一緒に)","e":"with (someone)","k":"~와/과 (함께)"},"p":{"j":"(動詞)＋與＋人＋(動詞)","e":"(verb) + yǔ + person + (verb)","k":"(동사)+與+사람+(동사)"},"ex":{"j":"與は書き言葉でよく使われる前置詞で、口語の跟とほぼ同じ意味。「與＋人＋動詞」の形で「〜と一緒に…する」を表す。日常会話では跟のほうが自然。","e":"Yǔ is a formal, written-style preposition meaning 'with,' similar to the more colloquial gēn. It appears as 'yǔ + person + verb.' In everyday speech, gēn sounds more natural than yǔ.","k":"與는 문어체에서 자주 쓰이는 전치사로 구어의 跟과 거의 같은 뜻이다. '與+사람+동사' 형태로 '~와 함께 …하다'를 나타내며, 일상 회화에서는 跟이 더 자연스럽다."},"eg":[{"z":"這位作家很喜歡<em>與</em>讀者分享生活的感動。","py":"Zhè wèi zuòjiā hěn xǐhuān yǔ dúzhě fēnxiǎng shēnghuó de gǎndòng.","j":"この作家は読者と生活の中の感動を分かち合うのがとても好きだ。","e":"This writer loves to share life's touching moments with readers.","k":"이 작가는 독자와 삶의 감동을 나누는 것을 매우 좋아한다."},{"z":"他喜歡<em>與</em>朋友分享旅行的照片。","py":"Tā xǐhuān yǔ péngyǒu fēnxiǎng lǚxíng de zhàopiàn.","j":"彼は友達と旅行の写真を分かち合うのが好きだ。","e":"He likes to share travel photos with friends.","k":"그는 친구와 여행 사진을 나누는 것을 좋아한다."}]},
{"id":"g4-312","cat":"介詞","t":"由1","g":{"j":"〜から(起点)","e":"from (a starting point)","k":"~부터(시작점)"},"p":{"j":"由＋起点＋動詞＋到＋終点","e":"yóu + starting point + verb + dào + endpoint","k":"由+시작점+동사+到+끝점"},"ex":{"j":"由は変化や範囲の起点を表す書き言葉的な介詞で、「由＋起点＋動詞＋到＋終点」の形でよく使われる。人が動作の担い手であることを表す由(例:這件事由我負責)とは意味が異なるので注意。","e":"Yóu is a formal preposition marking the starting point of a change or range, often used as 'yóu + starting point + verb + dào + endpoint.' Don't confuse it with the other use of yóu that marks who is responsible for an action (e.g., zhè jiàn shì yóu wǒ fùzé).","k":"由는 변화나 범위의 시작점을 나타내는 문어체 전치사로 '由+시작점+동사+到+끝점' 형태로 자주 쓰인다. 행위의 담당자를 나타내는 由(예: 這件事由我負責)와는 뜻이 다르므로 주의해야 한다."},"eg":[{"z":"深夜山上的溫度<em>由</em>十度降到零度以下。","py":"Shēnyè shānshàng de wēndù yóu shí dù jiàngdào líng dù yǐxià.","j":"深夜、山の上の気温は10度から0度以下まで下がる。","e":"Late at night, the temperature on the mountain drops from ten degrees to below zero.","k":"심야에 산 위의 기온은 10도에서 영하로 떨어진다."},{"z":"他的體重<em>由</em>六十公斤減到五十五公斤。","py":"Tā de tǐzhòng yóu liùshí gōngjīn jiǎndào wǔshíwǔ gōngjīn.","j":"彼の体重は60キロから55キロに減った。","e":"His weight decreased from sixty kilograms to fifty-five kilograms.","k":"그의 몸무게는 60킬로그램에서 55킬로그램으로 줄었다."}]},
{"id":"g4-313","cat":"副詞","t":"多少2","g":{"j":"いくらか、多少","e":"somewhat, a little","k":"어느 정도, 다소"},"p":{"j":"多少＋動詞(＋了)","e":"duōshǎo + verb (+ le)","k":"多少+동사(+了)"},"ex":{"j":"この多少は疑問詞ではなく、「いくらか、多少なりとも」という意味の副詞。動詞の前に置いて「ある程度〜した」ことを表す。疑問文の「多少錢?」(いくらですか)と混同しないよう注意。","e":"Here duōshǎo is not the question word 'how much/many' but an adverb meaning 'to some extent, a little.' Placed before a verb, it shows something happened to a certain degree. Don't confuse it with the interrogative duōshǎo qián (how much money).","k":"여기서 多少는 의문사가 아니라 '어느 정도, 다소'라는 뜻의 부사이다. 동사 앞에 놓여 '어느 정도 ~했다'는 것을 나타내며, 의문문 多少錢(얼마예요)과 혼동하지 않아야 한다."},"eg":[{"z":"他<em>多少</em>存了點錢，所以你不用擔心。","py":"Tā duōshǎo cún le diǎn qián, suǒyǐ nǐ búyòng dānxīn.","j":"彼は少しお金を貯めているから、心配しなくていいよ。","e":"He's saved up a bit of money, so you don't need to worry.","k":"그는 어느 정도 돈을 모아뒀으니까 걱정하지 않아도 돼."},{"z":"這件事我<em>多少</em>知道一些，你可以問我。","py":"Zhè jiàn shì wǒ duōshǎo zhīdào yìxiē, nǐ kěyǐ wèn wǒ.","j":"この件について私は少し知っているから、聞いてもいいよ。","e":"I know a little about this matter, so you can ask me.","k":"이 일에 대해 나는 어느 정도 알고 있으니까 나한테 물어봐도 돼."}]},
{"id":"g4-314","cat":"副詞","t":"都2","g":{"j":"もう、すでに(強調)","e":"already (emphatic)","k":"이미, 벌써(강조)"},"p":{"j":"都＋動詞(＋過)＋…＋了","e":"dōu + verb (+ guò) + ... + le","k":"都+동사(+過)+…+了"},"ex":{"j":"この都は「全部」ではなく、「もう、すでに」という強調を表す副詞。「都＋動詞(＋過)＋…＋了」の形で、不満やあきれた気持ちを込めてよく使われる。全体を指す都(大家都來了)と混同しないこと。","e":"This dōu doesn't mean 'all' but emphasizes that something has already happened, used as 'dōu + verb (+ guò) + ... + le' to express frustration or exasperation. Don't confuse it with the dōu meaning 'all/everyone' (e.g., dàjiā dōu lái le).","k":"이 都는 '전부'가 아니라 '이미, 벌써'라는 강조의 뜻을 나타내는 부사이다. '都+동사(+過)+…+了' 형태로 불만이나 어이없음을 나타낼 때 자주 쓰이며, 전체를 가리키는 都(大家都來了)와 혼동하지 않아야 한다."},"eg":[{"z":"<em>都</em>提醒過幾次了，他還是忘記還書。","py":"Dōu tíxǐngguò jǐ cì le, tā háishì wàngjì huán shū.","j":"何度も注意したのに、彼はまだ本を返すのを忘れる。","e":"I've already reminded him several times, but he still forgets to return the books.","k":"몇 번이나 일깨워 줬는데도 그는 여전히 책 반납하는 걸 잊어버린다."},{"z":"<em>都</em>跟你說過很多次了，你怎麼還是遲到？","py":"Dōu gēn nǐ shuōguò hěn duō cì le, nǐ zěnme háishì chídào?","j":"何度もあなたに言ったのに、どうしてまだ遅刻するの?","e":"I've already told you many times, why are you still late?","k":"몇 번이나 말했는데 왜 아직도 지각하는 거야?"}]},
{"id":"g4-315","cat":"補語","t":"V去2","g":{"j":"〜て取り除く(結果補語)","e":"away, off (resultative complement)","k":"~해서 없애다(결과보어)"},"p":{"j":"V＋去","e":"V + qù","k":"V+去"},"ex":{"j":"この去は「行く」という意味ではなく、動詞の後について動作の結果、対象が取り除かれる/なくなることを表す結果補語。除去・抹去・失去などでよく使われ、後ろに場所を続けない点に注意。","e":"Here qù is not the main verb 'to go' but a resultative complement after a verb, showing that something is removed or disappears as a result — as in chúqù, mǒqù, shīqù. Note that this qù does not take a following location.","k":"여기서 去는 '가다'라는 뜻이 아니라 동사 뒤에 붙어 그 동작의 결과로 대상이 제거되거나 사라짐을 나타내는 결과보어이다. 除去·抹去·失去처럼 쓰이며, 뒤에 장소가 오지 않는다는 점에 주의해야 한다."},"eg":[{"z":"他把名字從名單上除<em>去</em>。","py":"Tā bǎ míngzi cóng míngdān shàng chúqù.","j":"彼は名簿からその名前を消した。","e":"He removed the name from the list.","k":"그는 명단에서 그 이름을 지웠다."},{"z":"老師把黑板上的字抹<em>去</em>。","py":"Lǎoshī bǎ hēibǎn shàng de zì mǒqù.","j":"先生は黒板の字を消した。","e":"The teacher wiped the words off the blackboard.","k":"선생님은 칠판의 글씨를 지웠다."}]},
{"id":"g4-316","cat":"補語","t":"V過來2","g":{"j":"悪い状態から正しい状態へ改める","e":"to change/correct (something) back to the right state","k":"잘못된 것을 바로잡아 올바른 상태로 되돌리다"},"p":{"j":"主語＋把＋O＋動詞＋過來","e":"Subject + bǎ + O + V + guòlái","k":"주어 + 把 + O + 동사 + 過來"},"ex":{"j":"この「過來」は方向補語ではなく、悪い状態から正しい状態へ変わる結果を表す。「把」文と組み合わせて使われることが多く、単純な「来る」の意味と混同しないこと。","e":"Here \"過來\" is a resultative complement meaning a shift from a bad/wrong state to a correct one, often paired with 把. Don't confuse it with the literal directional \"come over.\"","k":"여기서 過來는 방향보어가 아니라 나쁜 상태에서 올바른 상태로 바뀌는 결과를 나타낸다. 把 구문과 자주 함께 쓰이며, 단순히 '오다'라는 뜻과 혼동하지 말 것."},"eg":[{"z":"父母用教育的方式把孩子不好的行為<em>改過來</em>。","py":"Fùmǔ yòng jiàoyù de fāngshì bǎ háizi bù hǎo de xíngwéi gǎi guòlái.","j":"親は教育的な方法で子どもの悪い行動を正した。","e":"Parents use educational methods to correct their child's bad behavior.","k":"부모는 교육적인 방법으로 아이의 나쁜 행동을 바로잡는다."},{"z":"他終於把說錯的發音<em>改過來</em>了。","py":"Tā zhōngyú bǎ shuōcuò de fāyīn gǎi guòlái le.","j":"彼はついに間違えて発音していたのを正した。","e":"He finally corrected the pronunciation he had been saying wrong.","k":"그는 마침내 잘못 발음하던 것을 바로잡았다."}]},
{"id":"g4-317","cat":"副詞","t":"還2","g":{"j":"まあまあ〜だ(それなりに)","e":"fairly / passably ~ (a moderate, acceptable degree)","k":"그런대로/꽤 ~하다"},"p":{"j":"主語＋還＋算＋形容詞","e":"Subject + hái + suàn + adjective","k":"주어 + 還 + 算 + 형용사"},"ex":{"j":"「還算」は控えめな肯定評価を表す固定表現。「還是」(依然として)や「還有」(まだある)の「還」とは意味が異なるので混同しないこと。","e":"\"還算\" is a set phrase expressing a modest, qualified positive assessment. Don't confuse this 還 with 還是 (still) or 還有 (also/there's still), which use different senses.","k":"還算은 절제된 긍정 평가를 나타내는 고정 표현이다. '아직도'를 뜻하는 還是나 '~도 있다'의 還有와는 다른 용법이므로 혼동하지 말 것."},"eg":[{"z":"這組沙發的價格<em>還算</em>便宜。","py":"Zhè zǔ shāfā de jiàgé hái suàn piányí.","j":"このソファのセットの値段はまあまあ安い。","e":"The price of this sofa set is fairly cheap.","k":"이 소파 세트의 가격은 그런대로 저렴하다."},{"z":"這家店的服務<em>還算</em>不錯。","py":"Zhè jiā diàn de fúwù hái suàn búcuò.","j":"この店のサービスはまあまあいい。","e":"This shop's service is fairly good.","k":"이 가게의 서비스는 그런대로 괜찮다."}]},
{"id":"g4-318","cat":"副詞","t":"才5","g":{"j":"「才不〜」で強い否定・反発を表す","e":"\"才不~\" expresses strong, defiant denial or disagreement","k":"'才不~'는 강한 반박·거부의 어감을 나타냄"},"p":{"j":"主語＋才＋不＋動詞(句)＋(呢)","e":"Subject + cái + bù + VP + (ne)","k":"주어 + 才 + 不 + 동사(구) + (呢)"},"ex":{"j":"事実や理由を表す才1〜4とは違い、この「才」は話者の強い反発・不服を示す語気的用法。文末の「呢」と組み合わせて感情を強調することが多く、「〜してはじめて」の才と混同しないこと。","e":"Unlike the 才 marking fact/reason/condition (才1–4), this 才 signals the speaker's strong pushback, often paired with 呢 for emphasis. Don't confuse it with the \"not until ~\" sense of 才.","k":"사실·이유·조건을 나타내는 才1~4와 달리, 이 才는 화자의 강한 반발·불복 어감을 나타내며 문미의 呢와 함께 쓰여 감정을 강조하는 경우가 많다. '~해야 비로소'라는 뜻의 才와 혼동하지 말 것."},"eg":[{"z":"這麼短的裙子他<em>才不敢穿</em>呢！","py":"Zhème duǎn de qúnzi tā cái bù gǎn chuān ne!","j":"こんな短いスカート、彼は絶対に着る勇気なんてないよ!","e":"A skirt this short — no way he'd dare wear it!","k":"이렇게 짧은 치마, 그는 절대 입을 용기가 없다니까!"},{"z":"我<em>才不相信</em>他的話呢！","py":"Wǒ cái bù xiāngxìn tā de huà ne!","j":"私は彼の言うことなんて絶対に信じないよ!","e":"I definitely don't believe what he says!","k":"나는 그의 말 따위 절대 안 믿어!"}]},
{"id":"g4-319","cat":"比較","t":"A有B（這/那麼）......","g":{"j":"AはBほど(これくらい/あれくらい)〜だ","e":"\"A is as (this/that) ~ as B\" — A reaches the same degree as B","k":"'A는 B만큼 (이렇게/저렇게) ~하다'는 정도 비교"},"p":{"j":"A＋有＋B＋這麼/那麼＋形容詞","e":"A + yǒu + B + zhème/nàme + adjective","k":"A + 有 + B + 這麼/那麼 + 형용사"},"ex":{"j":"「有」を使い二つのものの程度が同等であることを示す。「這麼」は身近な基準、「那麼」は離れた基準を指す。「比」構文と違い優劣ではなく程度の一致を表す点に注意。","e":"This pattern uses 有 to say two things reach the same degree; 這麼 refers to something near, 那麼 to something more distant. Unlike 比 (which shows superiority), this shows equal degree, not \"more than.\"","k":"有를 사용해 두 대상의 정도가 같음을 나타내는 구문. 這麼는 가깝거나 눈앞의 기준, 那麼는 더 먼 기준을 가리킨다. 우열을 나타내는 比 비교문과 달리 '더 ~하다'가 아니라 '정도가 같음'을 나타낸다는 점에 유의."},"eg":[{"z":"這間教室<em>有一個籃球場這麼大</em>。","py":"Zhè jiān jiàoshì yǒu yí ge lánqiúchǎng zhème dà.","j":"この教室はバスケットボールコート一面ほどの大きさがある。","e":"This classroom is as big as a basketball court.","k":"이 교실은 농구장 하나만큼 크다."},{"z":"這隻狗<em>有小孩子那麼高</em>。","py":"Zhè zhī gǒu yǒu xiǎoháizi nàme gāo.","j":"この犬は子どもくらいの高さがある。","e":"This dog is as tall as a small child.","k":"이 개는 어린아이만큼 키가 크다."}]},
{"id":"g4-320","cat":"比較","t":"比......來得 Vs","g":{"j":"「AはBよりも〜だ」をやや書き言葉的に表す","e":"\"A is more ~ than B\" — a somewhat formal/literary comparative","k":"'A가 B보다 더 ~하다'를 다소 문어체로 표현"},"p":{"j":"A＋比＋B＋來得＋形容詞","e":"A + bǐ + B + láide + adjective","k":"A + 比 + B + 來得 + 형용사"},"ex":{"j":"「來得」は「比」構文の後に置かれ、比較の結果をやや書き言葉的に強調する言い方で「比…更/還」に近い。形容詞(状態動詞)の前でしか使えず、動作動詞には使いにくい点に注意。","e":"\"來得\" follows a 比 comparison to state the result in a formal/literary tone, close to 比...更/還. Note it precedes only adjectives/stative verbs, not action verbs.","k":"來得는 比 비교문 뒤에서 비교 결과를 문어체로 강조하는 표현으로 比...更/還와 의미가 비슷하다. 다만 형용사(상태동사) 앞에서만 쓰이고 동작동사에는 쓰기 어렵다."},"eg":[{"z":"弟弟的身高<em>比同年紀的孩子來得高</em>。","py":"Dìdi de shēngāo bǐ tóng niánjì de háizi láide gāo.","j":"弟の身長は同い年の子どもより高い。","e":"My younger brother is taller than kids his age.","k":"남동생의 키는 동갑 아이들보다 크다."},{"z":"搭捷運<em>比開車來得方便</em>。","py":"Dā jiéyùn bǐ kāichē láide fāngbiàn.","j":"MRTに乗るほうが車を運転するより便利だ。","e":"Taking the MRT is more convenient than driving.","k":"지하철(MRT)을 타는 것이 운전하는 것보다 편리하다."}]},
{"id":"g4-321","cat":"補語","t":"Vs得沒話說","g":{"j":"〜には文句のつけようがない（最高に良い）","e":"so (good) that there's nothing to say","k":"말할 것도 없이 (아주 좋다)"},"p":{"j":"V/Adj ＋ 得沒話說","e":"V/Adj ＋ 得沒話說","k":"V/Adj ＋ 得沒話說"},"ex":{"j":"「得」の後に「沒話說」をつけて、程度がこれ以上ないほど高いことを表す強い賞讚。「得很」より強調され、悪い意味には使わない。","e":"Adding 沒話說 after 得 shows a degree so extreme there's nothing to criticize — a strong compliment, stronger than 得很. Never used for negative traits.","k":"得 뒤에 沒話說를 붙여 정도가 더할 나위 없이 높음을 나타내는 강한 칭찬 표현이다. 得很보다 강조되며 부정적인 의미로는 쓰이지 않는다."},"eg":[{"z":"他們家姊妹的感情<em>好得沒話說</em>，幾乎從來沒有吵過架。","py":"Tāmen jiā zǐmèi de gǎnqíng hǎo de méihuàshuō, jīhū cónglái méiyǒu chǎoguòjià.","j":"彼らの家の姉妹の仲は文句のつけようがないほど良く、ほとんど喧嘩をしたことがない。","e":"The sisters in that family get along so well there's nothing to complain about — they've almost never fought.","k":"그 집 자매의 사이는 나무랄 데 없이 좋아서 거의 싸운 적이 없다."},{"z":"這家店的服務<em>好得沒話說</em>，大家都想再來。","py":"Zhè jiā diàn de fúwù hǎo de méihuàshuō, dàjiā dōu xiǎng zàilái.","j":"この店のサービスは文句のつけようがないほど良く、みんなまた来たいと思っている。","e":"This shop's service is so good there's nothing to complain about — everyone wants to come back.","k":"이 가게의 서비스는 나무랄 데 없이 좋아서 다들 또 오고 싶어 한다."}]},
{"id":"g4-322","cat":"介詞","t":"向","g":{"j":"〜に対して（借りる・尋ねる等の相手・出所）","e":"toward/from (someone), for borrowing or asking","k":"~에게(서) (빌리다·묻다 등의 대상)"},"p":{"j":"A ＋ 向 ＋ B ＋ V","e":"A ＋ 向 ＋ B ＋ V","k":"A ＋ 向 ＋ B ＋ V"},"ex":{"j":"「向」は動作の向かう相手や出所を示す。「跟」より書き言葉的でやや硬い。借りる・尋ねる・学ぶなど一方向の行為によく使う。態度の対象を示す「對」と混同しないこと。","e":"向 marks the person an action is directed toward or drawn from (e.g. borrowing, asking, learning) — more formal than 跟. Don't confuse it with 對, which marks the target of an attitude or opinion.","k":"向는 동작이 향하는 상대나 출처를 나타내며 跟보다 문어체적이다. 빌리다·묻다·배우다 등 일방향 동작에 자주 쓰이고, 태도의 대상을 나타내는 對와 혼동하지 않도록 주의한다."},"eg":[{"z":"我<em>向</em>爸爸借了一千塊。","py":"Wǒ xiàng bàba jiè le yìqiān kuài.","j":"私は父から千元借りた。","e":"I borrowed a thousand dollars from Dad.","k":"나는 아빠에게 천 위안을 빌렸다."},{"z":"學生<em>向</em>老師請教問題。","py":"Xuéshēng xiàng lǎoshī qǐngjiào wèntí.","j":"学生は先生に質問した。","e":"The students asked the teacher questions.","k":"학생이 선생님께 질문을 드렸다."}]},
{"id":"g4-323","cat":"介詞","t":"為","g":{"j":"〜のために/〜に対して","e":"for (the benefit of)","k":"~을 위해"},"p":{"j":"為 ＋ N ＋ V（帶來/做…）","e":"為 ＋ N ＋ V（帶來/做…）","k":"為 ＋ N ＋ V（帶來/做…）"},"ex":{"j":"「為」は動作の受益者・対象を示す前置詞で、「給」よりやや硬い書き言葉。「為你帶來」＝あなたにもたらす。理由を表す「因為」と混同しないこと。","e":"為 introduces the beneficiary or target of an action (like 給, but more formal/written), often with verbs like 帶來/做/爭取. Don't confuse it with 因為, which means 'because.'","k":"為는 동작의 수혜자나 대상을 나타내는 전치사로 給보다 문어체적이며 帶來/做/爭取 등과 자주 함께 쓰인다. 이유를 뜻하는 因為와 혼동하지 않도록 주의한다."},"eg":[{"z":"換工作有時會<em>為</em>你帶來新的機會。","py":"Huàn gōngzuò yǒushí huì wèi nǐ dàilái xīn de jīhuì.","j":"転職は時にあなたに新しいチャンスをもたらすことがある。","e":"Changing jobs can sometimes bring you new opportunities.","k":"이직은 때로는 당신에게 새로운 기회를 가져다줄 수 있다."},{"z":"老師<em>為</em>學生準備了很多資料。","py":"Lǎoshī wèi xuéshēng zhǔnbèi le hěnduō zīliào.","j":"先生は学生のためにたくさんの資料を準備した。","e":"The teacher prepared a lot of materials for the students.","k":"선생님은 학생들을 위해 많은 자료를 준비했다."}]},
{"id":"g4-324","cat":"接続","t":"既然......就......","g":{"j":"すでに〜なのだから、〜","e":"since / given that... then...","k":"이미 ~이니까, ~하다"},"p":{"j":"既然 ＋ A，就 ＋ B","e":"既然 ＋ A，就 ＋ B","k":"既然 ＋ A，就 ＋ B"},"ex":{"j":"「既然」は既に成立している事実を提示し、「就」でその事実に基づく結論・提案を導く。単純な因果を示す「因為〜所以」と違い、「そうである以上は」という含みがある。","e":"既然 presents an already-established fact, and 就 draws a conclusion or suggestion from it — implying 'given that this is so.' Unlike plain cause-effect 因為...所以..., it often carries a tone of advice.","k":"既然는 이미 성립된 사실을 제시하고 就는 그에 따른 결론이나 제안을 이끈다. 단순 인과관계인 因為...所以...와 달리 '이왕 그러니'라는 뉘앙스를 담는다."},"eg":[{"z":"<em>既然</em>在學校上課，<em>就</em>可以利用時間好好使用學校的資源。","py":"Jìrán zài xuéxiào shàngkè, jiù kěyǐ lìyòng shíjiān hǎohǎo shǐyòng xuéxiào de zīyuán.","j":"すでに学校で授業を受けているのだから、時間を利用してしっかり学校の資源を活用すればいい。","e":"Since you're already attending classes at school, you might as well make good use of the time to take advantage of the school's resources.","k":"이왕 학교에서 수업을 듣고 있으니, 시간을 이용해서 학교의 자원을 잘 활용하면 된다."},{"z":"<em>既然</em>你已經決定了，<em>就</em>不要再猶豫了。","py":"Jìrán nǐ yǐjīng juédìng le, jiù búyào zài yóuyù le.","j":"もう決めたのだから、これ以上迷わないほうがいい。","e":"Since you've already decided, don't hesitate anymore.","k":"이미 결정했으니, 더 이상 망설이지 마."}]},
{"id":"g4-325","cat":"接続","t":"不/沒（有）......，就......","g":{"j":"〜しなければ、〜","e":"if not... then...","k":"~하지 않으면, ~하다"},"p":{"j":"不/沒（有）＋ A，就 ＋ B","e":"不/沒（有）＋ A，就 ＋ B","k":"不/沒（有）＋ A，就 ＋ B"},"ex":{"j":"「不/沒(有)」で条件を否定し、「就」でその結果を導く。習慣・未然なら「不」、完了・過去なら「沒(有)」を使い分ける。規則や案内文などの書き言葉でよく使われる。","e":"不/沒(有) negates the condition, and 就 states the resulting consequence. Use 不 for habitual/future situations and 沒(有) for completed/past ones. Common in written rules and notices.","k":"不/沒(有)로 조건을 부정하고 就로 그 결과를 나타낸다. 습관·미래는 不, 완료·과거는 沒(有)를 선택해서 쓴다. 규정이나 안내문 등 문어체에 자주 쓰인다."},"eg":[{"z":"<em>沒有</em>填寫信箱，申請<em>就</em>不會成功。","py":"Méiyǒu tiánxiě xìnxiāng, shēnqǐng jiù búhuì chénggōng.","j":"メールアドレスを記入しなければ、申請は成功しない。","e":"If you don't fill in your email address, the application won't succeed.","k":"이메일 주소를 기입하지 않으면, 신청은 성공하지 못한다."},{"z":"<em>不</em>早點出門，<em>就</em>會遲到。","py":"Bù zǎodiǎn chūmén, jiù huì chídào.","j":"早く出かけなければ、遅刻してしまう。","e":"If you don't leave early, you'll be late.","k":"일찍 나가지 않으면, 지각하게 될 것이다."}]},
{"id":"g4-326","cat":"接続","t":"再不......就......了","g":{"j":"今すぐ～しなければ、すぐ～になる(警告)","e":"if you don't... right now, then... soon (warning)","k":"지금 곧 ~하지 않으면 곧 ~된다(경고)"},"p":{"j":"再不＋動詞＋就＋(要)＋結果＋了","e":"zài bù + Verb + jiù + (yào) + Result + le","k":"再不＋동사＋就＋(要)＋결과＋了"},"ex":{"j":"「今すぐ行動しないと悪い結果になる」という切迫した警告を表す。単なる仮定の「如果不」より緊迫感が強く、後半に「就要...了」を伴うことが多い。","e":"Expresses an urgent warning: \"if you don't act right now, a bad result will follow soon.\" Carries more urgency than a plain \"如果不\" conditional, and the second clause often pairs with \"就要...了\".","k":"\"지금 당장 하지 않으면 곧 나쁜 결과가 생긴다\"는 다급한 경고를 나타낸다. 단순 가정인 \"如果不\"보다 긴박감이 강하며, 뒷절에 \"就要...了\"가 자주 함께 쓰인다."},"eg":[{"z":"我必須先離開了，<em>再不走就要遲到了</em>。","py":"Wǒ bìxū xiān líkāi le, zài bù zǒu jiù yào chídào le.","j":"私は先に出なければなりません。今すぐ出発しないと遅刻してしまいます。","e":"I have to leave now — if I don't go right away, I'll be late.","k":"저는 먼저 가야 해요. 지금 당장 안 나가면 지각할 거예요."},{"z":"你<em>再不吃就</em>涼<em>了</em>。","py":"Nǐ zài bù chī jiù liáng le.","j":"あなたが今食べないと、すぐ冷めちゃうよ。","e":"If you don't eat now, it'll get cold soon.","k":"너 지금 안 먹으면 금방 식어버려."}]},
{"id":"g4-327","cat":"接続","t":"非......不（可）","g":{"j":"どうしても～しなければならない","e":"absolutely must...","k":"반드시 ~해야만 한다"},"p":{"j":"非＋動詞(句)＋不可／不","e":"fēi + Verb(Phrase) + bùkě / bù","k":"非＋동사(구)＋不可／不"},"ex":{"j":"二重否定で強い義務・必然性を表す。「不可」を省略して「非...不」だけで使うこともあるが、口語では「非...不可」の方が自然。「一定要」より書き言葉的で強調が強い。","e":"A double-negative construction expressing strong necessity or obligation. \"不可\" can be dropped, leaving just \"非...不\", but \"非...不可\" is more natural in speech. More formal and emphatic than \"一定要\".","k":"이중부정으로 강한 의무·필연성을 나타낸다. \"不可\"를 생략하고 \"非...不\"만 쓰기도 하지만 회화에서는 \"非...不可\"가 더 자연스럽다. \"一定要\"보다 문어적이고 강조가 강하다."},"eg":[{"z":"我開會快遲到了，現在<em>非走不可</em>了。","py":"Wǒ kāihuì kuài chídào le, xiànzài fēi zǒu bùkě le.","j":"会議に遅れそうなので、今どうしても出発しなければなりません。","e":"I'm about to be late for the meeting, so I absolutely have to leave now.","k":"회의에 늦을 것 같아서 지금 반드시 가야 해요."},{"z":"這件事很重要，我<em>非做不可</em>。","py":"Zhè jiàn shì hěn zhòngyào, wǒ fēi zuò bùkě.","j":"この件はとても重要だから、私がやらなければならない。","e":"This matter is very important, so I must do it.","k":"이 일은 매우 중요해서 내가 반드시 해야 한다."}]},
{"id":"g4-328","cat":"接続","t":"即使......也......","g":{"j":"たとえ～でも(仮定・譲歩)","e":"even if... (hypothetical concession)","k":"설령 ~하더라도"},"p":{"j":"即使＋子句A(仮定・極端な状況)＋(主語)＋也＋子句B","e":"jíshǐ + Clause A (hypothetical/extreme) + (Subject) + yě + Clause B","k":"即使＋절A(가정・극단적 상황)＋(주어)＋也＋절B"},"ex":{"j":"まだ起きていない事や事実に反する仮定にも使える譲歩構文。既に起きた事実を述べる「雖然...但是」と違い、「即使」は仮定・極端な状況を想定する点が異なる。","e":"A concessive construction usable for hypothetical or even counterfactual situations. Unlike \"雖然...但是\", which describes an already-true fact, \"即使\" sets up a hypothetical or extreme scenario.","k":"아직 일어나지 않은 일이나 사실과 반대되는 가정에도 쓸 수 있는 양보 구문이다. 이미 일어난 사실을 말하는 \"雖然...但是\"와 달리, \"即使\"는 가정·극단적 상황을 전제로 한다는 점이 다르다."},"eg":[{"z":"<em>即使大學畢業了，平時自己也要多學習新的知識</em>。","py":"Jíshǐ dàxué bìyè le, píngshí zìjǐ yě yào duō xuéxí xīn de zhīshì.","j":"たとえ大学を卒業しても、普段から自分で新しい知識をたくさん学ぶべきだ。","e":"Even after graduating from university, you should still keep learning new knowledge on your own.","k":"설령 대학을 졸업했더라도, 평소에 스스로 새로운 지식을 많이 배워야 한다."},{"z":"<em>即使天氣不好，我們也</em>要出門運動。","py":"Jíshǐ tiānqì bù hǎo, wǒmen yě yào chūmén yùndòng.","j":"たとえ天気が悪くても、私たちは外に出て運動する。","e":"Even if the weather is bad, we still go outside to exercise.","k":"설령 날씨가 나빠도 우리는 밖에 나가 운동한다."}]},
{"id":"g4-329","cat":"接続","t":"就是......，也......","g":{"j":"たとえ～としても(極端な仮定の譲歩)","e":"even if... (an extreme hypothetical concession)","k":"설사 ~일지라도"},"p":{"j":"就是＋子句A(極端な仮定)，也＋子句B","e":"jiùshì + Clause A (extreme case), yě + Clause B","k":"就是＋절A(극단적 가정)，也＋절B"},"ex":{"j":"「即使」とほぼ同義だが、口語色が強く、より極端な例を挙げて譲歩する場面で使われやすい。ここでの「就是」は「就算」とも置き換え可能。","e":"Nearly synonymous with \"即使\", but more colloquial, and typically used when citing an extreme example as the concession. Here \"就是\" is interchangeable with \"就算\".","k":"\"即使\"와 거의 같은 뜻이지만 구어적인 느낌이 강하고, 더 극단적인 예를 들어 양보할 때 자주 쓰인다. 이때의 \"就是\"는 \"就算\"과 바꿔 쓸 수 있다."},"eg":[{"z":"如果運動對健康有幫助，<em>就是花費多一點時間也是值得的</em>。","py":"Rúguǒ yùndòng duì jiànkāng yǒu bāngzhù, jiùshì huāfèi duō yìdiǎn shíjiān yě shì zhíde de.","j":"もし運動が健康に役立つなら、少し余分に時間をかけてもそれだけの価値がある。","e":"If exercise is good for your health, then even spending a bit more time on it is worthwhile.","k":"운동이 건강에 도움이 된다면, 시간을 좀 더 써도 가치가 있다."},{"z":"<em>就是下雨，我也</em>要去。","py":"Jiùshì xià yǔ, wǒ yě yào qù.","j":"雨が降っても、私は行くつもりだ。","e":"Even if it rains, I'll still go.","k":"비가 와도 나는 갈 거야."}]},
{"id":"g4-330","cat":"接続","t":"再......也......","g":{"j":"どんなに～でも(程度が極端でも変わらない)","e":"no matter how... still...","k":"아무리 ~해도"},"p":{"j":"再＋形容詞／動詞＋也＋結果(不變)","e":"zài + Adjective/Verb + yě + unchanged result","k":"再＋형용사／동사＋也＋결과(불변)"},"ex":{"j":"程度がどれほど高くても結果は変わらないことを表す。「再」は形容詞や心理動詞の前に置き、仮定の節を導く「即使」と違い、程度の強調に重点がある。","e":"Expresses that no matter how extreme the degree, the result stays the same. \"再\" precedes an adjective or stative verb to emphasize degree, unlike \"即使\", which frames a hypothetical clause.","k":"정도가 아무리 심해도 결과는 변하지 않음을 나타낸다. \"再\"는 형용사나 심리동사 앞에 놓여 정도를 강조하는 데 중점이 있으며, 가정절을 이끄는 \"即使\"와는 다르다."},"eg":[{"z":"他很喜歡彈鋼琴，所以平時練習<em>再辛苦也不怕</em>。","py":"Tā hěn xǐhuān tán gāngqín, suǒyǐ píngshí liànxí zài xīnkǔ yě bú pà.","j":"彼はピアノを弾くのがとても好きなので、普段の練習がどんなに辛くても平気だ。","e":"He loves playing the piano, so no matter how hard practicing is, he doesn't mind.","k":"그는 피아노 치는 것을 아주 좋아해서, 평소 연습이 아무리 힘들어도 두려워하지 않는다."},{"z":"天氣<em>再冷，他也</em>要去跑步。","py":"Tiānqì zài lěng, tā yě yào qù pǎobù.","j":"天気がどんなに寒くても、彼は走りに行く。","e":"No matter how cold the weather is, he still goes jogging.","k":"날씨가 아무리 추워도 그는 달리기하러 간다."}]},
{"id":"g4-331","cat":"接続","t":"就算......也......","g":{"j":"「たとえ〜でも」","e":"Even if... still...","k":"설령 ~하더라도"},"p":{"j":"就算＋A（仮定）＋也＋B（結果）","e":"就算 + A (hypothesis) + 也 + B (result)","k":"就算 + A(가정) + 也 + B(결과)"},"ex":{"j":"仮定の状況を認めた上で、結果が変わらないことを強調する。事実を述べる「雖然」と違い仮定に使う。「即使」とほぼ同義だが「就算」はより口語的。","e":"Concedes a hypothetical condition while stressing the result stays the same. Unlike 雖然 (a real fact), 就算 introduces a hypothesis. Near-synonym of 即使, but more colloquial.","k":"가정한 상황을 인정하면서도 결과는 바뀌지 않음을 강조한다. 사실을 말하는 雖然과 달리 가정에 쓰이며, 即使와 비슷하지만 더 구어적이다."},"eg":[{"z":"<em>就算</em>沒有相機，手機<em>也</em>可以拍照。","py":"Jiùsuàn méiyǒu xiàngjī, shǒujī yě kěyǐ pāizhào.","j":"たとえカメラがなくても、スマホでも写真が撮れる。","e":"Even without a camera, you can still take photos with your phone.","k":"설령 카메라가 없어도 휴대폰으로도 사진을 찍을 수 있다."},{"z":"<em>就算</em>你不同意，我<em>也</em>要去。","py":"Jiùsuàn nǐ bù tóngyì, wǒ yě yào qù.","j":"たとえ君が同意しなくても、僕は行くつもりだ。","e":"Even if you don't agree, I'm still going.","k":"설령 네가 동의하지 않아도 나는 갈 것이다."}]},
{"id":"g4-332","cat":"接続","t":"除非","g":{"j":"「〜しない限り」","e":"Unless...","k":"~하지 않는 한"},"p":{"j":"除非＋A（唯一の条件），否則／才＋B","e":"除非 + A (the only condition), 否則/才 + B","k":"除非 + A(유일한 조건), 否則/才 + B"},"ex":{"j":"唯一の条件を示し、後ろに「否則」や「才」を伴うことが多い。単純な「如果不」と違い、それが唯一の道であることを強調する。","e":"Names the one condition that avoids the outcome, often paired with 否則 or 才. Unlike plain 如果不 (if not), 除非 stresses that this is the only way.","k":"유일한 조건을 나타내며 뒤에 否則나 才가 자주 온다. 단순 부정 조건인 如果不와 달리 그 조건만이 유일한 길임을 강조한다."},"eg":[{"z":"<em>除非</em>你對教書很有興趣，否則很容易就會失去耐心。","py":"Chúfēi nǐ duì jiāoshū hěn yǒu xìngqù, fǒuzé hěn róngyì jiù huì shīqù nàixīn.","j":"教えることに強い興味がない限り、すぐに忍耐力を失ってしまいやすい。","e":"Unless you're very interested in teaching, you'll easily lose your patience.","k":"가르치는 일에 큰 흥미가 없는 한, 쉽게 인내심을 잃게 된다."},{"z":"<em>除非</em>明天不下雨，否則我們不去爬山。","py":"Chúfēi míngtiān bú xià yǔ, fǒuzé wǒmen bú qù páshān.","j":"明日雨が降らない限り、私たちは山登りに行かない。","e":"Unless it doesn't rain tomorrow, we won't go hiking.","k":"내일 비가 오지 않는 한, 우리는 등산을 가지 않을 것이다."}]},
{"id":"g4-333","cat":"接続","t":"否則","g":{"j":"「そうでなければ」","e":"Otherwise","k":"그렇지 않으면"},"p":{"j":"A，否則＋B（悪い結果）","e":"A, 否則 + B (negative consequence)","k":"A, 否則 + B(나쁜 결과)"},"ex":{"j":"前の内容が実現しない場合の悪い結果を導く。話し言葉の「不然」とほぼ同義だが、「否則」はやや書き言葉的でフォーマル。","e":"Introduces the negative consequence if the preceding statement doesn't hold. Nearly interchangeable with the more colloquial 不然, but 否則 leans more formal/written.","k":"앞 내용이 이루어지지 않을 때의 나쁜 결과를 이끈다. 구어적인 不然과 거의 같지만 否則이 더 격식 있고 문어적이다."},"eg":[{"z":"快去叫醒爸爸，<em>否則</em>他上班要遲到了。","py":"Kuài qù jiàoxǐng bàba, fǒuzé tā shàngbān yào chídào le.","j":"早くお父さんを起こしに行って、そうしないと会社に遅刻してしまうよ。","e":"Go wake up Dad quickly, otherwise he'll be late for work.","k":"빨리 아빠를 깨우러 가, 그렇지 않으면 출근 시간에 늦을 거야."},{"z":"記得帶雨傘，<em>否則</em>你會被淋濕。","py":"Jìde dài yǔsǎn, fǒuzé nǐ huì bèi línshī.","j":"傘を持って行くのを忘れないで、そうしないと雨に濡れてしまうよ。","e":"Remember to bring an umbrella, otherwise you'll get soaked.","k":"우산을 꼭 챙겨, 그렇지 않으면 비에 젖을 거야."}]},
{"id":"g4-334","cat":"接続","t":"假如...... （就）......","g":{"j":"「もし〜なら」","e":"If... then...","k":"만약 ~라면"},"p":{"j":"假如＋A（仮定），（就）＋B（結果）","e":"假如 + A (hypothesis), (就) + B (result)","k":"假如 + A(가정), (就) + B(결과)"},"ex":{"j":"仮定の前提を導き、結果節に「就」を添えると因果関係や即時性が強まる。「如果」とほぼ同義だが「假如」はやや書き言葉寄り。","e":"Introduces a hypothetical premise; an optional 就 in the result clause strengthens the sense of immediate consequence. Near-synonym of 如果, though 假如 leans more literary/formal.","k":"가정의 전제를 이끌며, 결과절의 就는 즉각적 인과관계를 강조한다. 如果와 거의 같지만 假如가 조금 더 문어적이다."},"eg":[{"z":"<em>假如</em>你吃不完的話，<em>就</em>當作下午的點心吧！","py":"Jiǎrú nǐ chībuwán dehuà, jiù dàngzuò xiàwǔ de diǎnxīn ba!","j":"もし食べきれないなら、午後のおやつにしておいてね！","e":"If you can't finish it, just save it as an afternoon snack!","k":"만약 다 못 먹으면 오후 간식으로 남겨 둬!"},{"z":"<em>假如</em>你有問題，<em>就</em>打電話給我。","py":"Jiǎrú nǐ yǒu wèntí, jiù dǎ diànhuà gěi wǒ.","j":"もし何か問題があれば、私に電話してね。","e":"If you have any problems, just call me.","k":"만약 문제가 있으면 나에게 전화해."}]},
{"id":"g4-335","cat":"副詞","t":"倒（是）","g":{"j":"「かえって／実は」","e":"Actually/on the contrary","k":"오히려/사실은"},"p":{"j":"主語＋倒（是）＋述語（意外な対比）","e":"Subject + 倒(是) + predicate (unexpected contrast)","k":"주어 + 倒(是) + 서술어(의외의 대조)"},"ex":{"j":"予想と違う意外な事実を強調する副詞で、主語の直後・動詞の前に置く。「卻」も逆接だが、「倒是」はより軽く、意外性や安心感を含むニュアンスがある。","e":"Highlights a fact that contrasts with expectation, placed right after the subject and before the verb. Similar to 卻, but 倒(是) often carries a lighter, more reassuring or mildly surprising nuance.","k":"예상과 다른 의외의 사실을 강조하며 주어 뒤, 동사 앞에 온다. 卻와 비슷한 역접이지만 倒(是)는 더 가볍고 다소 안도감이나 의외성을 담는다."},"eg":[{"z":"這間公司是值得投資的，至於投資多少<em>倒是</em>可以再討論。","py":"Zhè jiān gōngsī shì zhíde tóuzī de, zhìyú tóuzī duōshǎo dàoshì kěyǐ zài tǎolùn.","j":"この会社は投資する価値があるが、いくら投資するかについては改めて相談してもいい。","e":"This company is worth investing in; as for how much to invest, that can actually be discussed further.","k":"이 회사는 투자할 가치가 있고, 얼마를 투자할지는 오히려 다시 논의해도 된다."},{"z":"這件事很麻煩，他<em>倒是</em>一點都不擔心。","py":"Zhè jiàn shì hěn máfan, tā dàoshì yìdiǎn dōu bù dānxīn.","j":"この件はかなり面倒なのに、彼はまったく心配していない。","e":"This matter is quite troublesome, but he's actually not worried at all.","k":"이 일은 꽤 번거로운데, 그는 오히려 전혀 걱정하지 않는다."}]},
{"id":"g4-336","cat":"特殊構文","t":"寧願......也（不）要......","g":{"j":"〜するくらいなら、〜したい（したくない）","e":"would rather... than...","k":"차라리 ~할지언정 ~하고 싶다(싶지 않다)"},"p":{"j":"寧願＋A（受け入れる小さな犠牲）＋也（不）要＋B（望む結果）","e":"寧願 + A (the lesser cost accepted) + 也（不）要 + B (the desired outcome)","k":"寧願 + A(감수하는 작은 희생) + 也（不）要 + B(원하는 결과)"},"ex":{"j":"「寧願」は二つの選択肢の間で、一方を選ぶ個人的な気持ち・意志を表す。相手や状況への不満を含むことが多く、「寧可」よりやや感情的なニュアンスがある。","e":"\"寧願\" expresses a personal willingness to choose one option over another, often implying reluctance about the alternative — slightly more emotional in tone than \"寧可\".","k":"\"寧願\"는 두 선택지 중 하나를 원해서 택하는 개인적인 의지를 나타내며, 다른 쪽에 대한 불만을 담는 경우가 많아 \"寧可\"보다 다소 감정적이다."},"eg":[{"z":"他<em>寧願</em>少賺一點錢，<em>也不要</em>把時間都花在工作上。","py":"Tā níngyuàn shǎo zhuàn yìdiǎn qián, yě búyào bǎ shíjiān dōu huāzài gōngzuò shàng.","j":"彼は少し稼ぎが少なくなってもいいから、仕事に全部の時間を使いたくない。","e":"He would rather earn a little less money than spend all his time on work.","k":"그는 돈을 조금 덜 벌더라도 시간을 모두 일에 쓰고 싶지 않다."},{"z":"她<em>寧願</em>自己走路回家，<em>也不要</em>跟他一起搭車。","py":"Tā níngyuàn zìjǐ zǒulù huíjiā, yě búyào gēn tā yìqǐ dāchē.","j":"彼女は一人で歩いて帰る方がよくて、彼と一緒に車に乗りたくない。","e":"She would rather walk home alone than ride in the car with him.","k":"그녀는 차라리 혼자 걸어서 집에 가지, 그와 함께 차를 타고 싶지 않다."}]},
{"id":"g4-337","cat":"特殊構文","t":"寧可......也（不）要......","g":{"j":"比較したうえで〜する方を選ぶ","e":"would rather (choose)... than...","k":"비교해서 차라리 ~하다"},"p":{"j":"寧可＋A（比較して選ぶ方）＋也（不）要＋B","e":"寧可 + A (the option chosen after weighing) + 也（不）要 + B","k":"寧可 + A(비교 후 선택하는 쪽) + 也（不）要 + B"},"ex":{"j":"「寧可」は状況を比較したうえで下す決断を表し、「寧願」よりやや客観的・書き言葉的。「也要」「也不要」のどちらとも自然に結びつく。","e":"\"寧可\" expresses a deliberate choice made after weighing two options; it is more neutral and slightly more formal than \"寧願\", and combines naturally with either \"也要\" or \"也不要\".","k":"\"寧可\"는 상황을 비교한 뒤 내리는 결정을 나타내며 \"寧願\"보다 다소 객관적이고 격식 있다. \"也要\"와 \"也不要\" 어느 쪽과도 자연스럽게 결합한다."},"eg":[{"z":"我<em>寧可</em>少賺一點錢，<em>也要</em>有自己的休閒時間。","py":"Wǒ níngkě shǎo zhuàn yìdiǎn qián, yě yào yǒu zìjǐ de xiūxián shíjiān.","j":"私は少し稼ぎが少なくても構わないから、自分の余暇の時間を持ちたい。","e":"I would rather earn a little less money than have no leisure time of my own.","k":"나는 돈을 조금 덜 벌더라도 나만의 여가 시간을 갖고 싶다."},{"z":"他<em>寧可</em>餓肚子，<em>也要</em>把錢省下來買那台相機。","py":"Tā níngkě è dùzi, yě yào bǎ qián shěng xiàlái mǎi nà tái xiàngjī.","j":"彼はお腹を空かせてでも、お金を貯めてあのカメラを買いたい。","e":"He would rather go hungry than not save up money to buy that camera.","k":"그는 배를 곯더라도 돈을 모아 그 카메라를 사고 싶어 한다."}]},
{"id":"g4-338","cat":"副詞","t":"居然","g":{"j":"意外にも〜だ","e":"unexpectedly, surprisingly","k":"뜻밖에도, 놀랍게도"},"p":{"j":"(主語)＋居然＋動詞句(予想外の結果)","e":"(Subject) + 居然 + VP (unexpected but actual result)","k":"(주어) + 居然 + 동사구(예상 밖의 실제 결과)"},"ex":{"j":"「居然」は実際に起きた事実に対する驚きを表す。誇張ではなく本当にあったことに使う点で、誇張表現の「簡直」と混同しないよう注意。","e":"\"居然\" shows surprise at something that actually happened contrary to expectation — it marks a real fact, not exaggeration, so don't confuse it with \"簡直\".","k":"\"居然\"는 실제로 일어난 사실에 대한 놀라움을 나타낸다. 과장이 아니라 실제 일에 쓰이므로 과장 표현인 \"簡直\"와 혼동하지 않도록 주의한다."},"eg":[{"z":"他平時工作很忙，<em>居然</em>還有時間可以寫小說。","py":"Tā píngshí gōngzuò hěn máng, jūrán hái yǒu shíjiān kěyǐ xiě xiǎoshuō.","j":"彼は普段仕事がとても忙しいのに、意外にも小説を書く時間があるとは。","e":"He's usually very busy with work, but surprisingly he still has time to write novels.","k":"그는 평소에 일이 매우 바쁜데도, 뜻밖에 소설을 쓸 시간이 있다."},{"z":"她才學中文半年，<em>居然</em>可以看懂報紙了。","py":"Tā cái xué Zhōngwén bànnián, jūrán kěyǐ kàndǒng bàozhǐ le.","j":"彼女は中国語を学んでまだ半年なのに、なんと新聞が読めるようになった。","e":"She's only been studying Chinese for half a year, but she can surprisingly understand newspapers already.","k":"그녀는 중국어를 배운 지 겨우 반년인데, 뜻밖에도 신문을 이해할 수 있게 되었다."}]},
{"id":"g4-339","cat":"副詞","t":"簡直","g":{"j":"まるで〜も同然だ、ほとんど〜だ","e":"simply, practically (exaggeration)","k":"그야말로, 완전히(과장)"},"p":{"j":"簡直＋是/像＋誇張した内容","e":"簡直 + 是/像 + an exaggerated statement","k":"簡直 + 是/像 + 과장된 내용"},"ex":{"j":"「簡直」は誇張して強調する言い方で、事実そのものというより「まるで〜のようだ」という感覚を表す。実際の驚きを示す「居然」とは用法が異なる。","e":"\"簡直\" is used for exaggerated emphasis, meaning \"practically/simply\" rather than a literal fact — different from \"居然\", which marks genuine surprise at something real.","k":"\"簡直\"는 과장하여 강조하는 표현으로 실제 사실이라기보다 \"거의 ~와 다름없다\"는 느낌을 준다. 실제 놀라움을 나타내는 \"居然\"와는 쓰임이 다르다."},"eg":[{"z":"一天寫好一篇論文，<em>簡直</em>是不可能的事。","py":"Yìtiān xiěhǎo yìpiān lùnwén, jiǎnzhí shì bù kěnéng de shì.","j":"一日で論文を書き上げるなんて、まるで不可能なことだ。","e":"Finishing a paper in one day is simply impossible.","k":"하루 만에 논문을 다 쓰는 것은 그야말로 불가능한 일이다."},{"z":"這裡的風景美得<em>簡直</em>像一幅畫。","py":"Zhèlǐ de fēngjǐng měi de jiǎnzhí xiàng yìfú huà.","j":"ここの景色は美しくて、まるで一枚の絵のようだ。","e":"The scenery here is so beautiful it's simply like a painting.","k":"이곳의 풍경은 아름다워서 마치 한 폭의 그림 같다."}]},
{"id":"g4-340","cat":"副詞","t":"反正","g":{"j":"どうせ、いずれにせよ","e":"anyway, in any case","k":"어차피, 어쨌든"},"p":{"j":"(A也好，B也好，)反正＋結論(状況に関わらず変わらない事実)","e":"(A yěhǎo, B yěhǎo,) 反正 + conclusion (true regardless of circumstances)","k":"(A也好，B也好，) 反正 + 결론(상황과 무관하게 변하지 않는 사실)"},"ex":{"j":"「反正」は状況や理由に関係なく結論が変わらないことを表す。「〜也好、〜也好」や「不管〜」と一緒によく使われる。","e":"\"反正\" indicates that the conclusion stays the same no matter the circumstances; it's often paired with \"〜也好、〜也好\" or \"不管〜\".","k":"\"反正\"는 상황이나 이유와 관계없이 결론이 변하지 않음을 나타낸다. \"〜也好、〜也好\"나 \"不管〜\"과 자주 함께 쓰인다."},"eg":[{"z":"借錢也好，先賺錢再讀書也好，<em>反正</em>他一定要念完大學。","py":"Jiè qián yě hǎo, xiān zhuàn qián zài dúshū yě hǎo, fǎnzhèng tā yídìng yào niànwán dàxué.","j":"借金するにしても、先にお金を稼いでから勉強するにしても、とにかく彼は必ず大学を卒業するつもりだ。","e":"Whether by borrowing money or by earning money first and studying later, he's determined to finish university no matter what.","k":"돈을 빌리든, 먼저 돈을 벌고 나서 공부를 하든, 어쨌든 그는 반드시 대학을 졸업할 것이다."},{"z":"<em>反正</em>明天不用上班，我們晚一點睡也沒關係。","py":"Fǎnzhèng míngtiān búyòng shàngbān, wǒmen wǎn yìdiǎn shuì yě méi guānxi.","j":"どうせ明日は仕事に行かなくていいから、私たちは少し遅く寝ても構わない。","e":"Since we don't have to go to work tomorrow anyway, it's fine if we go to bed a bit later.","k":"어차피 내일 출근 안 해도 되니까, 우리 좀 늦게 자도 상관없어."}]},
{"id":"g4-341","cat":"副詞","t":"幸虧","g":{"j":"運よく〜のおかげで(危険を回避)","e":"fortunately (avoided something bad)","k":"다행히(나쁜 결과를 피함)"},"p":{"j":"幸虧＋原因，(不然/要不然)＋壞結果","e":"幸虧 + reason, (不然) + bad outcome that was avoided","k":"幸虧+원인, (不然)+나쁜 결과"},"ex":{"j":"「幸虧」は悪い結果を避けられた幸運な事情を述べる時に使う。後ろに「不然」「要不然」を続けて『もしそうでなければ』を示すことが多い。「幸好」とほぼ同義で、どちらも話し言葉でよく使われる。","e":"Use 幸虧 to describe a lucky factor that prevented a bad outcome; a clause with 不然/要不然 ('otherwise') often follows. It is very close in meaning to 幸好, both used in everyday speech, so don't overthink the difference.","k":"幸虧는 나쁜 결과를 피하게 해준 다행스러운 상황을 말할 때 쓴다. 뒤에 不然/要不然('그렇지 않았다면')이 자주 이어진다. 幸好와 뜻이 매우 비슷하며 둘 다 구어에서 자주 쓰인다."},"eg":[{"z":"他差點走錯路，<em>幸虧</em>停下來查了地圖。","py":"Tā chādiǎn zǒucuò lù, xìngkuī tíngxiàlái chále dìtú.","j":"彼はもう少しで道を間違えるところだったが、幸い立ち止まって地図を確認した。","e":"He almost took the wrong way, but fortunately he stopped to check the map.","k":"그는 하마터면 길을 잘못 갈 뻔했는데, 다행히 멈춰서 지도를 확인했다."},{"z":"我出門前<em>幸虧</em>多帶了一把傘，不然就淋濕了。","py":"Wǒ chūmén qián xìngkuī duō dàile yì bǎ sǎn, bùrán jiù línshīle.","j":"出かける前に幸い傘をもう一本多く持って行ったので、そうでなければ濡れてしまうところだった。","e":"Before I left, I luckily brought an extra umbrella, otherwise I would have gotten soaked.","k":"나가기 전에 다행히 우산을 하나 더 챙겼는데, 안 그랬으면 흠뻑 젖었을 것이다."}]},
{"id":"g4-342","cat":"疑問","t":"難道......（嗎）","g":{"j":"まさか〜ではないだろう(反語で強調)","e":"surely... isn't it? (rhetorical question)","k":"설마 ~겠어(반어법 강조)"},"p":{"j":"難道＋主語＋述語＋（嗎）？","e":"難道 + subject + predicate + (嗎)?","k":"難道+주어+서술어+(嗎)?"},"ex":{"j":"「難道」は反語文を作り、話し手がすでに答え(逆の内容)を確信していることを示す強調表現。文末の「嗎」は省略できることもあるが、初級者はつけておくと自然。単なる疑問文とは違い、実際には答えを求めていない点に注意。","e":"難道 turns a sentence into a rhetorical question, showing the speaker is already confident of the (opposite) answer. The final 嗎 can sometimes be dropped, but keeping it sounds natural for learners. Unlike a real question, no answer is actually expected.","k":"難道는 반어문을 만들어 화자가 이미 (반대되는) 답을 확신하고 있음을 강조한다. 문미의 嗎는 생략되기도 하지만 학습자는 붙이는 편이 자연스럽다. 실제 질문이 아니라 답을 기대하지 않는다는 점에 유의."},"eg":[{"z":"我們是二十年的老朋友了，<em>難道</em>我還不了解你<em>嗎</em>？","py":"Wǒmen shì èrshí nián de lǎopéngyǒu le, nándào wǒ hái bù liǎojiě nǐ ma?","j":"私たちは二十年来の親友じゃないか。まさか私が君のことを分かっていないとでも言うの?","e":"We've been close friends for twenty years — how could I possibly not understand you?","k":"우리는 20년 지기 친구인데, 설마 내가 너를 이해 못 하겠어?"},{"z":"他每天都遲到，<em>難道</em>他不知道遲到會被罵<em>嗎</em>？","py":"Tā měitiān dōu chídào, nándào tā bù zhīdào chídào huì bèimà ma?","j":"彼は毎日遅刻している。まさか遅刻したら叱られると知らないわけがないでしょう?","e":"He's late every single day — surely he knows he'll get scolded for being late, doesn't he?","k":"그는 매일 지각하는데, 설마 지각하면 혼난다는 걸 모르겠어?"}]},
{"id":"g4-343","cat":"特殊構文","t":"算（是）","g":{"j":"〜と見なせる、〜に該当する(評価・判断)","e":"count as / be considered (a judgment or evaluation)","k":"~인 셈이다, ~에 속한다(판단·평가)"},"p":{"j":"主語＋算（是）＋名詞/形容詞","e":"Subject + 算（是） + noun/adjective","k":"주어+算（是）+명사/형용사"},"ex":{"j":"「算」は話し手の主観的な評価・判断を表し、「〜のレベルに達している/相当する」というニュアンス。「是」を加えても(算是)意味はほぼ同じ。断定を避けたやわらかい言い方で、「是」だけの強い断定とは異なる。","e":"算 expresses the speaker's subjective judgment, meaning something reaches or fits a certain level/category. Adding 是 (算是) barely changes the meaning. It's a softer, less definite way of stating something than a plain 是 sentence.","k":"算은 화자의 주관적 판단을 나타내며 '어떤 수준/범주에 해당한다'는 뉘앙스다. 是를 붙여도(算是) 의미는 거의 같다. 단정적인 是 문장보다 더 부드러운 표현이다."},"eg":[{"z":"這次的颱風<em>算</em>強颱，你一定要先準備好水跟食物。","py":"Zhè cì de táifēng suàn qiángtái, nǐ yídìng yào xiān zhǔnbèihǎo shuǐ gēn shíwù.","j":"今回の台風は強い台風と言えるので、必ず先に水と食料を準備しておかなければならない。","e":"This typhoon counts as a strong one, so you really need to prepare water and food in advance.","k":"이번 태풍은 강한 태풍에 속하니, 꼭 미리 물과 음식을 준비해 둬야 한다."},{"z":"這家店的牛肉麵<em>算</em>便宜，才一百塊而已。","py":"Zhè jiā diàn de niúròumiàn suàn piányí, cái yìbǎi kuài éryǐ.","j":"この店の牛肉麺は安いほうで、たったの百元だ。","e":"This shop's beef noodles are considered cheap — only a hundred dollars.","k":"이 가게의 우육면은 저렴한 편이다. 겨우 100元밖에 안 한다."}]},
{"id":"g4-344","cat":"副詞","t":"難怪/怪不得","g":{"j":"道理で〜だ(理由が分かって納得)","e":"no wonder... (realizing the reason)","k":"어쩐지 ~더라(이유를 알고 납득)"},"p":{"j":"難怪/怪不得＋主語＋述語(理由を知って納得)","e":"難怪/怪不得 + clause (realization after learning the reason)","k":"難怪/怪不得+절(이유를 안 뒤의 납득)"},"ex":{"j":"「難怪」「怪不得」はどちらも『理由が分かって、なるほどと納得する』時に使い、意味はほぼ同じ。「怪不得」の方がやや口語的。前の文で理由が示され、後ろに納得した結果を続ける語順が多い。","e":"Both 難怪 and 怪不得 mean 'no wonder,' used when learning a reason clears up something puzzling; they're nearly interchangeable, with 怪不得 slightly more colloquial. The reason is often stated first, followed by the clause expressing realization.","k":"難怪와 怪不得는 모두 '어쩐지 ~더라'는 뜻으로, 이유를 알고 납득할 때 쓰며 의미가 거의 같다. 怪不得가 조금 더 구어적이다. 앞에서 이유가 나오고 뒤에 납득한 내용이 이어지는 경우가 많다."},"eg":[{"z":"果然是你，<em>難怪</em>我覺得聲音很熟悉。","py":"Guǒrán shì nǐ, nánguài wǒ juéde shēngyīn hěn shúxī.","j":"やっぱり君だったんだ、道理で声に聞き覚えがあると思った。","e":"It really was you — no wonder the voice sounded so familiar to me.","k":"역시 너였구나, 어쩐지 목소리가 익숙하다고 생각했어."},{"z":"他感冒了，<em>怪不得</em>今天看起來精神不好。","py":"Tā gǎnmàole, guàibude jīntiān kànqǐlái jīngshén bù hǎo.","j":"彼は風邪をひいたんだ、道理で今日は元気がなさそうに見えるわけだ。","e":"He caught a cold — no wonder he looks so unwell today.","k":"그는 감기에 걸렸구나, 어쩐지 오늘 기운이 없어 보이더라."}]},
{"id":"g4-345","cat":"副詞","t":"果然","g":{"j":"案の定、思ったとおり(予想が的中)","e":"sure enough, as expected (prediction confirmed)","k":"과연, 예상대로(예측이 적중함)"},"p":{"j":"(予想の内容)，果然＋結果","e":"(prediction), 果然 + result (that matches it)","k":"(예측 내용), 果然+결과"},"ex":{"j":"「果然」は事前の予想・推測が実際に当たったことを述べる副詞。文頭にも述語の前にも置ける。理由が分かって納得する「難怪」とは異なり、「果然」は予想が的中した時に使う。","e":"果然 states that an earlier prediction or guess actually came true; it can appear at the start of a sentence or right before the predicate. Unlike 難怪 (realizing a reason), 果然 is about a prediction matching reality.","k":"果然은 사전의 예상이나 추측이 실제로 맞아떨어졌음을 나타내는 부사로, 문두나 서술어 앞에 올 수 있다. 이유를 알고 납득하는 難怪와 달리, 果然은 예측이 적중했을 때 쓴다."},"eg":[{"z":"爸爸忘了戴帽子出門，回來<em>果然</em>曬傷了。","py":"Bàba wàngle dài màozi chūmén, huílái guǒrán shàishāngle.","j":"お父さんは帽子をかぶるのを忘れて出かけ、帰ってきたら案の定日焼けしていた。","e":"Dad forgot to wear a hat when he went out, and sure enough, he got sunburned when he came back.","k":"아빠는 모자 쓰는 것을 잊고 나갔는데, 돌아왔더니 역시 햇볕에 탔다."},{"z":"氣象預報說今天會下雨，出門<em>果然</em>下雨了。","py":"Qìxiàng yùbào shuō jīntiān huì xiàyǔ, chūmén guǒrán xiàyǔle.","j":"天気予報で今日は雨が降ると言っていたが、出かけたら案の定雨が降った。","e":"The weather forecast said it would rain today, and sure enough, it rained when I went out.","k":"일기예보에서 오늘 비가 온다고 했는데, 나가 보니 과연 비가 내렸다."}]},
{"id":"g4-346","cat":"副詞","t":"竟（然）","g":{"j":"意外にも〜だ","e":"surprisingly, actually","k":"놀랍게도 ~하다"},"p":{"j":"主語 ＋ 竟（然）＋ 意外な内容","e":"Subject + jìng(rán) + unexpected result","k":"주어 + 竟(然) + 의외의 내용"},"ex":{"j":"「竟然」は予想外の結果への強い驚きを表す。「居然」とほぼ同義で置き換え可能だが、やや書き言葉的。単独の「竟」は文章語でより簡潔に使われる。","e":"\"Jìngrán\" expresses surprise at an unexpected outcome. It's close in meaning to \"jūrán\" but slightly more formal; the bare form \"jìng\" alone is common in writing.","k":"\"竟然\"은 예상 밖의 결과에 대한 놀라움을 나타낸다. \"居然\"과 뜻이 비슷하지만 조금 더 격식 있으며, 단독으로 쓰이는 \"竟\"은 문어체에서 자주 쓰인다."},"eg":[{"z":"一個不到十歲的孩子，<em>竟然</em>會有這麼成熟的想法。","py":"Yī ge bú dào shí suì de háizi, jìngrán huì yǒu zhème chéngshú de xiǎngfǎ.","j":"十歳にも満たない子どもが、なんとこんなに成熟した考えを持っているとは。","e":"A child not even ten years old actually has such a mature way of thinking.","k":"열 살도 안 된 아이가 놀랍게도 이렇게 성숙한 생각을 가지고 있다니."},{"z":"他平常不太念書，這次考試<em>竟然</em>考了第一名。","py":"Tā píngcháng bú tài niànshū, zhè cì kǎoshì jìngrán kǎole dì-yī míng.","j":"彼は普段あまり勉強しないのに、今回のテストで意外にも一番になった。","e":"He doesn't usually study much, but this time he actually got first place on the test.","k":"그는 평소에 공부를 별로 안 하는데 이번 시험에서 뜻밖에도 1등을 했다."}]},
{"id":"g4-347","cat":"副詞","t":"照V","g":{"j":"規定・予定どおりに〜する","e":"do (V) as usual / as scheduled","k":"원래대로 ~하다"},"p":{"j":"照 ＋ V（＋名詞）","e":"zhào + V (+ Noun)","k":"照 + 동사(+명사)"},"ex":{"j":"「照」は動詞の前について「元の規定・計画どおりに行う」ことを示す。状況が変わっても基準を変えない点を強調するのが「還是」だけの表現との違い。","e":"\"Zhào\" before a verb means carrying it out according to the original rule or plan, regardless of a change in circumstances — it emphasizes an unchanged standard more than \"háishì\" alone.","k":"\"照\"는 동사 앞에 붙어 '원래 규정이나 계획대로 하다'를 나타낸다. 상황이 바뀌어도 기준이 그대로임을 강조하는 점이 \"還是\"만 쓸 때와 다르다."},"eg":[{"z":"雖然他月底才搬進來，這個月的房租還是<em>照付</em>。","py":"Suīrán tā yuèdǐ cái bān jìnlái, zhège yuè de fángzū háishì zhào fù.","j":"彼は月末になってようやく引っ越してきたが、今月の家賃はそれでも規定どおり支払う。","e":"Although he only moved in at the end of the month, he still pays this month's rent in full as usual.","k":"그는 월말에야 이사를 왔지만 이번 달 집세는 그래도 규정대로 낸다."},{"z":"就算老闆不同意，會議還是<em>照開</em>。","py":"Jiùsuàn lǎobǎn bù tóngyì, huìyì háishì zhào kāi.","j":"たとえ上司が同意しなくても、会議はそれでも予定どおり開かれる。","e":"Even if the boss doesn't agree, the meeting will still be held as scheduled.","k":"상사가 동의하지 않더라도 회의는 그래도 예정대로 열린다."}]},
{"id":"g4-348","cat":"副詞","t":"就是","g":{"j":"とにかく（変わらず）〜だ","e":"just (emphatic) — an unchanging trait","k":"그냥/그저 ~하다(강조)"},"p":{"j":"（不管…）＋ 主語 ＋ 就是 ＋ 形容詞/動詞","e":"(Bùguǎn...) + Subject + jiùshì + Adj/Verb","k":"(不管…) + 주어 + 就是 + 형용사/동사"},"ex":{"j":"ここでの「就是」は「〜である」の意味ではなく、状況が変わっても揺るがない性質や態度を強調する副詞的用法。「不管」「怎麼」などとよく呼応する。","e":"Here \"jiùshì\" is not the copula \"is\" but an emphatic adverb stressing a trait or stance that stays fixed no matter the circumstances; it often pairs with \"bùguǎn\" or \"zěnme.\"","k":"여기서 \"就是\"는 '~이다'라는 뜻이 아니라, 상황이 바뀌어도 변하지 않는 성질이나 태도를 강조하는 부사적 용법이다. \"不管\", \"怎麼\" 등과 자주 호응한다."},"eg":[{"z":"不管遇到什麼問題，他<em>就是</em>很有自信。","py":"Bùguǎn yùdào shénme wèntí, tā jiùshì hěn yǒu zìxìn.","j":"どんな問題に出くわしても、彼はとにかく自信満々だ。","e":"No matter what problem he runs into, he's just always confident.","k":"어떤 문제를 만나든 그는 그저 자신감이 넘친다."},{"z":"我怎麼勸他都沒用，他<em>就是</em>不肯道歉。","py":"Wǒ zěnme quàn tā dōu méiyòng, tā jiùshì bù kěn dàoqiàn.","j":"私がどう説得しても無駄で、彼はどうしても謝ろうとしない。","e":"No matter how I persuade him, it's no use — he just won't apologize.","k":"내가 아무리 설득해도 소용없다, 그는 그냥 사과하려 하지 않는다."}]},
{"id":"g4-349","cat":"特殊構文","t":"光N/V（O）就","g":{"j":"〜だけで、もう…","e":"just N/V(O) alone is enough to...","k":"~만으로도 이미…"},"p":{"j":"光 ＋ N/V（O）＋ 就 ＋ 結果","e":"Guāng + N/V(O) + jiù + Result","k":"光 + N/V(O) + 就 + 결과"},"ex":{"j":"「光」が「〜だけで」と範囲を限定し、「就」がそれだけで十分だという結果を導く構文。「只」より話し言葉的で強調のニュアンスが強い。","e":"\"Guāng\" limits the scope to \"just this alone,\" and \"jiù\" introduces the sufficient result that follows. It's more colloquial and emphatic than using \"zhǐ\" by itself.","k":"\"光\"이 '~만으로'라고 범위를 한정하고, \"就\"가 그것만으로 충분하다는 결과를 이끄는 구문이다. \"只\"보다 구어적이고 강조 느낌이 강하다."},"eg":[{"z":"<em>光從書名就</em>知道這是一本很有創意的書。","py":"Guāng cóng shūmíng jiù zhīdào zhè shì yī běn hěn yǒu chuàngyì de shū.","j":"書名だけで、これがとても独創的な本だとわかる。","e":"Just from the title alone, you can tell this is a very creative book.","k":"책 제목만 봐도 이것이 매우 창의적인 책이라는 걸 알 수 있다."},{"z":"<em>光看照片就</em>能感覺到那裡的風景有多漂亮。","py":"Guāng kàn zhàopiàn jiù néng gǎnjué dào nàlǐ de fēngjǐng yǒu duō piàoliang.","j":"写真を見ただけで、あそこの景色がどれほど美しいか感じられる。","e":"Just by looking at the photos, you can feel how beautiful the scenery there is.","k":"사진만 봐도 그곳 풍경이 얼마나 아름다운지 느낄 수 있다."}]},
{"id":"g4-350","cat":"副詞","t":"根本","g":{"j":"まったく〜ない／そもそも〜ない","e":"(not) at all, simply not","k":"전혀/애초에 ~하지 않다"},"p":{"j":"主語 ＋ 根本 ＋（不/沒）＋ V/形容詞","e":"Subject + gēnběn + (bù/méi) + V/Adj","k":"주어 + 根本 + (不/沒) + 동사/형용사"},"ex":{"j":"「根本」は否定文を強調し「そもそも／まったく」という語気を加える副詞。単なる「不/沒」より事態の深刻さや意外性を強調する。","e":"\"Gēnběn\" strengthens a negative statement, adding a sense of \"simply/at all\" — stronger than plain \"bù/méi,\" often implying the situation is more extreme than expected.","k":"\"根本\"은 부정문을 강조하여 '전혀/애초에'라는 어감을 더하는 부사이다. 단순한 \"不/沒\"보다 상황의 심각성이나 의외성을 강조한다."},"eg":[{"z":"他每天工作都很忙，<em>根本</em>沒時間與孩子們相處。","py":"Tā měitiān gōngzuò dōu hěn máng, gēnběn méi shíjiān yǔ háizimen xiāngchǔ.","j":"彼は毎日仕事がとても忙しくて、子どもたちと過ごす時間がまったくない。","e":"He's very busy with work every day, so he has basically no time at all to spend with his children.","k":"그는 매일 일이 너무 바빠서 아이들과 지낼 시간이 전혀 없다."},{"z":"他連捷運站在哪裡都不知道，<em>根本</em>沒去過台北。","py":"Tā lián jié yùn zhàn zài nǎlǐ dōu bù zhīdào, gēnběn méi qùguò Táiběi.","j":"彼はMRTの駅がどこにあるかさえ知らない、そもそも台北に行ったことがないのだ。","e":"He doesn't even know where the MRT station is — he's simply never been to Taipei at all.","k":"그는 MRT역이 어디 있는지도 모른다, 애초에 타이베이에 가 본 적이 전혀 없는 것이다."}]},
{"id":"g4-351","cat":"介詞","t":"靠/靠著","g":{"j":"〜に頼る、〜によって","e":"rely on / by means of","k":"~에 의지하다"},"p":{"j":"(人/事物)＋靠＋(對象)＋做...","e":"Subject + 靠 + means/support + verb phrase","k":"(사람/사물)+靠+(대상)+동사"},"ex":{"j":"「靠」は「〜に頼る/〜によって」という意味で、手段や拠り所を示す。「靠著」は動作や状態の持続を表しやすい。客観的根拠を示す「根據」と混同しないよう注意。","e":"\"靠\" means \"to rely on / by means of,\" introducing the means or support one depends on. \"靠著\" often marks an ongoing state. Don't confuse it with \"根據,\" which cites objective evidence.","k":"\"靠\"는 \"~에 의지하다/~을 통해\"라는 뜻으로 수단이나 의지처를 나타낸다. \"靠著\"는 지속되는 상태를 표현할 때 자주 쓰인다. 객관적 근거를 뜻하는 \"根據\"와 혼동하지 않도록 주의."},"eg":[{"z":"生活上有任何問題，我們都要努力<em>靠</em>自己的力量去解決。","py":"Shēnghuó shàng yǒu rènhé wèntí, wǒmen dōu yào nǔlì kào zìjǐ de lìliàng qù jiějué.","j":"生活で何か問題があっても、私たちは自分の力で解決するよう努力しなければならない。","e":"Whatever problems arise in life, we must try hard to solve them by relying on our own strength.","k":"생활에서 어떤 문제가 있어도, 우리는 자신의 힘으로 해결하려고 노력해야 한다。"},{"z":"他<em>靠</em>自己的努力考上了大學。","py":"Tā kào zìjǐ de nǔlì kǎoshàng le dàxué.","j":"彼は自分の努力で大学に合格した。","e":"He got into university through his own effort.","k":"그는 자신의 노력으로 대학에 합격했다."}]},
{"id":"g4-352","cat":"介詞","t":"根據","g":{"j":"〜に基づいて、〜によると","e":"according to / based on","k":"~에 따르면/근거하여"},"p":{"j":"根據＋(資料/報告等根據)，＋子句","e":"根據 + source/evidence + clause","k":"根據+(자료/보고 등 근거)+절"},"ex":{"j":"「根據」は客観的な資料・報告・法規などの根拠を示すときに使う書き言葉的表現。頼る対象を示す「靠」とは異なり、判断や結論の裏付けを述べる。","e":"\"根據\" cites an objective source (a report, data, law) as the basis for a statement. Unlike \"靠,\" which names something one relies on for support, it backs up a judgment or conclusion, and is common in formal writing.","k":"\"根據\"는 보고서·자료·법규 등 객관적 근거를 제시할 때 쓰는 문어적 표현이다. 의지 대상을 뜻하는 \"靠\"와 달리 판단이나 결론의 근거를 밝힌다."},"eg":[{"z":"<em>根據</em>氣象報告，明天下午會下雨。","py":"Gēnjù qìxiàng bàogào, míngtiān xiàwǔ huì xiàyǔ.","j":"天気予報によると、明日の午後は雨が降るそうだ。","e":"According to the weather report, it will rain tomorrow afternoon.","k":"기상 예보에 따르면, 내일 오후에 비가 온다고 한다."},{"z":"<em>根據</em>調查，很多年輕人喜歡喝手搖飲料。","py":"Gēnjù diàochá, hěn duō niánqīngrén xǐhuān hē shǒuyáo yǐnliào.","j":"調査によると、多くの若者はドリンクスタンドの飲み物を飲むのが好きだ。","e":"According to the survey, many young people like to drink handmade tea-stand beverages.","k":"조사에 따르면, 많은 젊은이들이 음료 전문점의 음료를 즐겨 마신다."}]},
{"id":"g4-353","cat":"接続","t":"......好......","g":{"j":"〜するために、〜できるように","e":"so that / in order to","k":"~하도록, ~하기 위해서"},"p":{"j":"子句1，好＋子句2(目的)","e":"Clause 1, 好 + Clause 2 (purpose)","k":"절1, 好+절2(목적)"},"ex":{"j":"「好」は動詞句の前に置き、前の動作が後の目的を実現するためであることを示す。「以便」と似るが、「好」はより口語的で簡潔に使われる。","e":"\"好\" precedes a verb phrase to show that the preceding action is done in order to achieve that purpose. It resembles \"以便\" but is more colloquial and concise.","k":"\"好\"는 동사구 앞에 놓여 앞의 행동이 뒤의 목적을 이루기 위한 것임을 나타낸다. \"以便\"과 비슷하지만 더 구어적이고 간결하다."},"eg":[{"z":"自己在國外生活，記得有空多打電話回家，<em>好</em>讓家人放心。","py":"Zìjǐ zài guówài shēnghuó, jìde yǒu kòng duō dǎ diànhuà huí jiā, hǎo ràng jiārén fàngxīn.","j":"一人で海外生活をするなら、時間があるときはできるだけ家に電話をして、家族を安心させるようにしなさい。","e":"If you're living abroad alone, remember to call home often when you have time, so that your family can feel at ease.","k":"혼자 외국에서 생활한다면, 시간 날 때 자주 집에 전화해서 가족을 안심시키도록 하라."},{"z":"我會提早出門，<em>好</em>避開上班時間的塞車。","py":"Wǒ huì tízǎo chūmén, hǎo bìkāi shàngbān shíjiān de sāichē.","j":"私は早めに家を出て、通勤ラッシュの渋滞を避けるようにする。","e":"I'll leave home early so as to avoid the rush-hour traffic jam.","k":"나는 일찍 집을 나서서 출퇴근 시간대의 교통 체증을 피하려고 한다."}]},
{"id":"g4-354","cat":"接続","t":"自從......後","g":{"j":"〜してから(その後)","e":"ever since ... (afterward)","k":"~한 이후로"},"p":{"j":"自從＋事件/時間點＋後，＋結果","e":"自從 + event/time point + 後, + result","k":"自從+사건/시점+後,+결과"},"ex":{"j":"「自從......後」はある出来事や時点を起点として、その後継続する状況や変化を述べる。単独の「自從」より、その直後という区切りを強調する。","e":"\"自從......後\" marks a specific event or point in time as the starting point for an ongoing situation or change afterward, emphasizing the moment right after that point more than \"自從\" alone.","k":"\"自從......後\"는 어떤 사건이나 시점을 기점으로 그 이후 계속되는 상황이나 변화를 말하며, 단독으로 쓰는 \"自從\"보다 그 직후 시점을 더 강조한다."},"eg":[{"z":"<em>自從他的研究發表後</em>，受到很多的肯定。","py":"Zìcóng tā de yánjiù fābiǎo hòu, shòudào hěn duō de kěndìng.","j":"彼の研究が発表されてから、多くの支持を得ている。","e":"Since his research was published, it has received a great deal of recognition.","k":"그의 연구가 발표된 이후로 많은 인정을 받고 있다."},{"z":"<em>自從搬到台北後</em>，他交了很多新朋友。","py":"Zìcóng bāndào Táiběi hòu, tā jiāo le hěn duō xīn péngyǒu.","j":"台北に引っ越してから、彼は新しい友達をたくさん作った。","e":"Since moving to Taipei, he has made many new friends.","k":"타이베이로 이사한 이후로 그는 새로운 친구를 많이 사귀었다."}]},
{"id":"g4-355","cat":"接続","t":"自從......以來","g":{"j":"〜して以来ずっと","e":"ever since ...","k":"~한 이래로"},"p":{"j":"自從＋事件/時間點＋以來，＋(持續的)結果","e":"自從 + event/time point + 以來, + (ongoing) result","k":"自從+사건/시점+以來,+(지속적인) 결과"},"ex":{"j":"「自從......以來」はある時点から現在まで継続している状態や変化を強調し、「自從......後」より「ずっと続いている」という持続性が強い。","e":"\"自從......以來\" emphasizes a state or change that has continued from a point in time up to now, stressing ongoing duration more strongly than \"自從......後.\"","k":"\"自從......以來\"는 어떤 시점부터 지금까지 계속 이어지는 상태나 변화를 강조하며, \"自從......後\"보다 지속성을 더 강하게 나타낸다."},"eg":[{"z":"<em>自從開始學習網球以來</em>，他的表現一直都很出色。","py":"Zìcóng kāishǐ xuéxí wǎngqiú yǐlái, tā de biǎoxiàn yìzhí dōu hěn chūsè.","j":"網球を習い始めてからずっと、彼の成績はとても優れている。","e":"Ever since he started learning tennis, his performance has consistently been outstanding.","k":"테니스를 배우기 시작한 이래로, 그의 성적은 줄곧 매우 뛰어나다."},{"z":"<em>自從搬到這裡以來</em>，我認識了很多新朋友。","py":"Zìcóng bāndào zhèlǐ yǐlái, wǒ rènshi le hěn duō xīn péngyǒu.","j":"ここに引っ越して来てから、私はたくさんの新しい友達と知り合った。","e":"Ever since I moved here, I've gotten to know many new friends.","k":"이곳으로 이사 온 이래로, 나는 많은 새로운 친구를 사귀었다."}]},
{"id":"g4-356","cat":"副詞","t":"至今","g":{"j":"今まで、これまで","e":"up until now","k":"지금까지"},"p":{"j":"(過去の出来事)，至今 + (仍/還/都)＋動詞","e":"(past event), zhìjīn + (réng/hái/dōu) + verb","k":"(과거의 사건), 至今 + (仍/還/都) + 동사"},"ex":{"j":"「至今」は過去に始まった状態や影響が現在まで続いていることを表す書き言葉寄りの表現で、後ろによく「仍」「還」「都」を伴う。「到現在」より書面語的でやや硬い言い方。","e":"\"Zhìjīn\" marks that a state or effect starting in the past continues up to now; it often pairs with \"仍/還/都\" after it. It is more formal/written than the spoken \"到現在\".","k":"'至今'은 과거에 시작된 상태나 영향이 지금까지 이어짐을 나타내는 다소 문어적인 표현으로, 뒤에 '仍/還/都'가 자주 온다. 구어체 '到現在'보다 격식 있는 느낌이다."},"eg":[{"z":"他講了一句話，<em>至今</em>仍讓我印象深刻。","py":"Tā jiǎng le yí jù huà, zhìjīn réng ràng wǒ yìnxiàng shēnkè.","j":"彼はある一言を言ったが、それは今でも私に深い印象を残している。","e":"He said a sentence that, to this day, still leaves a deep impression on me.","k":"그는 한 마디 말을 했는데, 지금까지도 나에게 깊은 인상을 남기고 있다."},{"z":"這件事發生已經十年了，<em>至今</em>大家還常常提起。","py":"Zhè jiàn shì fāshēng yǐjīng shí nián le, zhìjīn dàjiā hái chángcháng tíqǐ.","j":"この出来事が起きてからもう十年になるが、今でもみんなよく話題にする。","e":"This happened ten years ago, and people still often bring it up to this day.","k":"이 일이 일어난 지 벌써 10년이 되었지만, 지금까지도 사람들이 자주 이야기한다."}]},
{"id":"g4-357","cat":"接続","t":"原來A，如今B","g":{"j":"もとはA、今はB(対比)","e":"used to be A, now B","k":"원래는 A, 지금은 B"},"p":{"j":"原來＋A，如今＋B","e":"Yuánlái + A, rújīn + B","k":"原來 + A, 如今 + B"},"ex":{"j":"過去の状態(原來)と現在の変化後の状態(如今)を対で示し、変化・対比を強調する。「以前...現在...」と似るが、「如今」はやや書き言葉的でドラマチックな変化のニュアンスがある。","e":"This pattern pairs a past state (\"原來\") with the present, changed state (\"如今\") to highlight contrast/change. Similar to \"以前...現在...\", but \"如今\" carries a slightly more literary, dramatic-change nuance.","k":"과거 상태(原來)와 현재의 변화된 상태(如今)를 짝지어 대비와 변화를 강조한다. '以前...現在...'와 비슷하지만 '如今'은 다소 문어적이고 극적인 변화의 뉘앙스를 지닌다."},"eg":[{"z":"這塊地<em>原來</em>種香蕉，<em>如今</em>改種芒果。","py":"Zhè kuài dì yuánlái zhòng xiāngjiāo, rújīn gǎi zhòng mángguǒ.","j":"この土地はもともとバナナを植えていたが、今ではマンゴーに植え替えている。","e":"This plot of land used to grow bananas; now it has been replanted with mangoes.","k":"이 땅은 원래 바나나를 심었었는데, 지금은 망고로 바꿔 심었다."},{"z":"他<em>原來</em>是老師，<em>如今</em>當了校長。","py":"Tā yuánlái shì lǎoshī, rújīn dāng le xiàozhǎng.","j":"彼はもともと教師だったが、今では校長になった。","e":"He used to be a teacher; now he has become the principal.","k":"그는 원래 교사였는데, 지금은 교장이 되었다."}]},
{"id":"g4-358","cat":"接続","t":"一方面......，一方面......","g":{"j":"一方では...、また一方では...(二つの側面)","e":"on one hand... on the other hand...","k":"한편으로는...한편으로는..."},"p":{"j":"一方面＋A，一方面＋B","e":"Yì fāngmiàn + A, yì fāngmiàn + B","k":"一方面 + A, 一方面 + B"},"ex":{"j":"同時に存在する二つの側面や行為を並べて述べる書き言葉的表現。「一面...一面...」と似るが、「一方面」は主に「二つの側面・理由」を対比的に述べる時に使い、「一面...一面...」は同時に行う二つの動作を表すことが多い。","e":"Used to present two aspects or actions that hold true at the same time; somewhat formal. Similar to \"一面...一面...\", but \"一方面\" is mainly for contrasting two aspects/reasons, while \"一面...一面...\" more often describes two actions done simultaneously.","k":"동시에 존재하는 두 가지 측면이나 행위를 나열하는 다소 문어적인 표현이다. '一面...一面...'과 비슷하지만 '一方面'은 주로 두 가지 측면·이유를 대비할 때 쓰고, '一面...一面...'은 동시에 하는 두 동작을 나타낼 때가 많다."},"eg":[{"z":"表演的時候，<em>一方面</em>要注意動作，<em>一方面</em>還要跟別人配合。","py":"Biǎoyǎn de shíhòu, yì fāngmiàn yào zhùyì dòngzuò, yì fāngmiàn hái yào gēn biérén pèihé.","j":"演技をする時は、一方では動作に気をつけながら、もう一方では他の人と息を合わせなければならない。","e":"When performing, on the one hand you have to pay attention to your movements, and on the other hand you also have to coordinate with others.","k":"공연할 때는 한편으로는 동작에 신경을 써야 하고, 한편으로는 또 다른 사람과 호흡을 맞춰야 한다."},{"z":"她<em>一方面</em>想多存錢，<em>一方面</em>又想出國旅行。","py":"Tā yì fāngmiàn xiǎng duō cún qián, yì fāngmiàn yòu xiǎng chūguó lǚxíng.","j":"彼女は一方ではもっとお金を貯めたいと思いながら、もう一方では海外旅行にも行きたいと思っている。","e":"On one hand she wants to save more money, and on the other hand she also wants to travel abroad.","k":"그녀는 한편으로는 돈을 더 모으고 싶어 하면서도, 한편으로는 해외 여행을 가고 싶어 한다."}]},
{"id":"g4-359","cat":"接続","t":"一面......一面......","g":{"j":"〜しながら〜する(同時進行)","e":"while doing A, doing B","k":"~하면서 ~하다"},"p":{"j":"一面＋動作A，一面＋動作B","e":"Yímiàn + action A, yímiàn + action B","k":"一面 + 동작A, 一面 + 동작B"},"ex":{"j":"同じ主語が同時に二つの動作を行うことを表す口語的な表現で、「一邊...一邊...」とほぼ同義で置き換え可能。「一方面」は側面・理由の対比に使うのに対し、「一面」は具体的な動作の同時進行に使う。","e":"Describes the same subject doing two actions at the same time; fairly colloquial and largely interchangeable with \"一邊...一邊...\". Unlike \"一方面\" (which contrasts aspects/reasons), \"一面\" is used for concrete actions happening simultaneously.","k":"같은 주어가 동시에 두 동작을 하는 것을 나타내는 다소 구어적인 표현으로, '一邊...一邊...'과 거의 같은 뜻으로 바꿔 쓸 수 있다. 측면·이유를 대비하는 '一方面'과 달리 '一面'은 구체적인 동작의 동시 진행에 쓰인다."},"eg":[{"z":"臺下的觀眾<em>一面</em>拍手，<em>一面</em>跟著唱。","py":"Táixià de guānzhòng yímiàn pāishǒu, yímiàn gēnzhe chàng.","j":"客席の観客は拍手をしながら、一緒に歌を歌っていた。","e":"The audience below the stage clapped while singing along.","k":"무대 아래 관중들은 박수를 치면서 따라 불렀다."},{"z":"他<em>一面</em>騎腳踏車，<em>一面</em>講電話，很危險。","py":"Tā yímiàn qí jiǎotàchē, yímiàn jiǎng diànhuà, hěn wéixiǎn.","j":"彼は自転車に乗りながら電話をしていて、とても危険だ。","e":"He was riding his bike while talking on the phone, which is very dangerous.","k":"그는 자전거를 타면서 전화를 하는데, 매우 위험하다."}]},
{"id":"g4-360","cat":"副詞","t":"千萬","g":{"j":"絶対に、くれぐれも","e":"absolutely, whatever you do","k":"절대로, 반드시"},"p":{"j":"千萬＋(別/不要)＋動詞","e":"Qiānwàn + (bié/bùyào) + verb","k":"千萬 + (不要/別) + 동사"},"ex":{"j":"話し手の強い忠告や懇願を表す副詞で、命令文・禁止文でよく使われる。特に「千萬別/千萬不要」の形で「絶対に〜するな」という強い禁止を表すことが多い。「一定」より切迫感・懇願のニュアンスが強い。","e":"An adverb expressing the speaker's strong warning or plea, typically used in imperative or prohibitive sentences. Especially common as \"千萬別/千萬不要\" (\"whatever you do, don't...\"). Carries more urgency/pleading than \"一定\".","k":"화자의 강한 당부나 간곡한 부탁을 나타내는 부사로, 명령문·금지문에 자주 쓰인다. 특히 '千萬別/千萬不要' 형태로 '절대로 ~하지 마라'는 강한 금지를 나타낼 때가 많다. '一定'보다 절박함과 간곡함이 강하다."},"eg":[{"z":"出國時，<em>千萬</em>要記得帶護照。","py":"Chūguó shí, qiānwàn yào jìde dài hùzhào.","j":"海外に行く時は、必ずパスポートを持っていくのを忘れないように。","e":"When going abroad, you must absolutely remember to bring your passport.","k":"해외에 갈 때는 반드시 여권 챙기는 것을 잊지 말아야 한다."},{"z":"過馬路的時候，<em>千萬</em>別滑手機。","py":"Guò mǎlù de shíhòu, qiānwàn bié huá shǒujī.","j":"道路を渡る時は、絶対にスマホをいじってはいけない。","e":"When crossing the street, whatever you do, don't look at your phone.","k":"길을 건널 때는 절대로 휴대폰을 보지 마라."}]},
{"id":"g4-361","cat":"アスペクト","t":"V中","g":{"j":"〜中(動作が進行中であることを表す)","e":"in the process of / ongoing","k":"~중(동작이 진행 중임을 나타냄)"},"p":{"j":"V＋中","e":"V + 中","k":"V + 中"},"ex":{"j":"「V＋中」は動作が現在進行中であることを表す書面語的表現。「正在V」と似ているが、「V中」は名詞的で単独でも使え、公告や標示によく使われる(施工中、營業中など)。","e":"\"V+中\" marks an action as currently ongoing, often in formal or written contexts such as notices and reports. Unlike \"正在V\", \"V中\" can stand alone as a label (e.g. 施工中, 營業中) without needing a subject.","k":"\"V+中\"은 동작이 현재 진행 중임을 나타내는 문어체 표현으로, \"正在V\"와 비슷하지만 표지판이나 공고문처럼 명사처럼 단독으로도 쓰인다(예: 施工中, 營業中)."},"eg":[{"z":"意外發生的原因目前仍在<em>調查中</em>。","py":"Yìwài fāshēng de yuányīn mùqián réng zài diàochá zhōng.","j":"事故が起きた原因は現在も調査中です。","e":"The cause of the accident is still under investigation.","k":"사고가 발생한 원인은 현재 조사 중입니다."},{"z":"這個案子還在<em>討論中</em>，還沒有結果。","py":"Zhège ànzi hái zài tǎolùn zhōng, hái méiyǒu jiéguǒ.","j":"この案件はまだ検討中で、まだ結論が出ていません。","e":"This case is still under discussion, and there's no result yet.","k":"이 사건은 아직 논의 중이며, 아직 결과가 없습니다."}]},
{"id":"g4-362","cat":"接続","t":"結果","g":{"j":"結果として、〜の結果","e":"as a result, it turned out that...","k":"결과적으로, ~한 결과"},"p":{"j":"子句1，結果＋子句2","e":"Clause 1, 結果 + Clause 2","k":"절1, 結果 + 절2"},"ex":{"j":"「結果」は前の内容から生じた最終的な結末を導く接続詞で、良い結果にも悪い結果にも使える。「因此」が原因→結論の論理関係を示すのに対し、「結果」は出来事の最終的な成り行きを強調する。","e":"\"結果\" introduces the final outcome that followed from what was said before, and can be used for both good and bad results. Unlike \"因此\", which signals a logical cause-to-conclusion link, \"結果\" emphasizes how a situation actually turned out.","k":"\"結果\"는 앞 내용에서 비롯된 최종 결말을 이끄는 접속사로, 좋은 결과와 나쁜 결과 모두에 쓸 수 있다. \"因此\"가 논리적 인과를 나타낸다면 \"結果\"는 일이 실제로 어떻게 전개되었는지를 강조한다."},"eg":[{"z":"他去很多家公司面試，<em>結果</em>只有一家公司通知他去上班。","py":"Tā qù hěnduō jiā gōngsī miànshì, jiéguǒ zhǐyǒu yì jiā gōngsī tōngzhī tā qù shàngbān.","j":"彼はたくさんの会社を面接して回ったが、結局一社しか採用の連絡がなかった。","e":"He interviewed at many companies, but in the end only one company notified him to start work.","k":"그는 많은 회사에 면접을 보러 갔지만, 결국 한 회사만 그에게 출근하라는 연락을 했다."},{"z":"他每天熬夜念書，<em>結果</em>考試的時候頭痛得沒辦法寫。","py":"Tā měitiān áoyè niànshū, jiéguǒ kǎoshì de shíhòu tóutòng de méi bànfǎ xiě.","j":"彼は毎日夜更かしして勉強していたが、結果、試験のときに頭痛がひどくて書けなかった。","e":"He stayed up late studying every night, and as a result he had such a bad headache during the exam that he couldn't write.","k":"그는 매일 밤늦게까지 공부했는데, 결과적으로 시험 때 두통이 심해서 답을 쓸 수가 없었다."}]},
{"id":"g4-363","cat":"接続","t":"由於","g":{"j":"〜のため、〜によって(原因)","e":"due to / owing to","k":"~로 인해, ~때문에"},"p":{"j":"由於＋原因，(就/因此)＋結果","e":"由於 + reason, (就/因此) + result","k":"由於 + 원인, (就/因此) + 결과"},"ex":{"j":"「由於」は原因・理由を導く書面語的な接続詞で、「因為」よりフォーマル。後半に「因此/所以/就」を伴うことが多く、文頭にも文中にも置ける点は「因為」と同じ。","e":"\"由於\" introduces a cause or reason and is more formal/written than \"因為\". It often pairs with \"因此/所以/就\" in the result clause, and like \"因為\" it can appear at the start of a sentence or mid-sentence.","k":"\"由於\"는 원인・이유를 이끄는 문어체 접속사로 \"因為\"보다 격식적이다. 뒷절에 \"因此/所以/就\"가 자주 따라오며, \"因為\"처럼 문장 앞이나 중간에 모두 올 수 있다."},"eg":[{"z":"表達能力差正是我的弱點，但<em>由於</em>多講多寫，這些弱點也就克服了。","py":"Biǎodá nénglì chà zhèng shì wǒ de ruòdiǎn, dàn yóuyú duō jiǎng duō xiě, zhèxiē ruòdiǎn yě jiù kèfú le.","j":"表現力が弱いことがまさに私の弱点だったが、たくさん話したりたくさん書いたりしたおかげで、これらの弱点も克服できた。","e":"Poor expressive ability was exactly my weakness, but by speaking and writing a lot, I managed to overcome these weaknesses.","k":"표현력이 부족한 것이 바로 나의 약점이었지만, 많이 말하고 많이 쓴 덕분에 이 약점들도 극복되었다."},{"z":"<em>由於</em>颱風來襲，明天的班機全部取消。","py":"Yóuyú táifēng láixí, míngtiān de bānjī quánbù qǔxiāo.","j":"台風が接近しているため、明日のフライトはすべてキャンセルになった。","e":"Due to the approaching typhoon, all of tomorrow's flights have been cancelled.","k":"태풍이 접근함에 따라 내일 항공편이 모두 취소되었다."}]},
{"id":"g4-364","cat":"接続","t":"因此","g":{"j":"だから、そのため","e":"therefore, as a result","k":"그러므로, 그 결과"},"p":{"j":"原因子句，因此＋結果子句","e":"Reason clause, 因此 + result clause","k":"원인절, 因此 + 결과절"},"ex":{"j":"「因此」は前の原因・理由から導かれる結論を示す書面語的接続詞で、「所以」よりやや硬い。文頭に置いて新しい文を始めることもできる点が話し言葉の「所以」と異なる。","e":"\"因此\" links a cause to its logical result and is more formal/written than \"所以\". Unlike \"所以\", it can begin a brand-new sentence on its own, not just join clauses within one sentence.","k":"\"因此\"는 원인에서 결론을 이끄는 문어체 접속사로 \"所以\"보다 다소 격식적이다. \"所以\"와 달리 마침표 뒤 새 문장을 시작할 때도 쓸 수 있다."},"eg":[{"z":"這家麵店參加牛肉麵比賽得了第一名，<em>因此</em>吸引了更多顧客。","py":"Zhè jiā miàndiàn cānjiā niúròumiàn bǐsài dé le dìyīmíng, yīncǐ xīyǐn le gèngduō gùkè.","j":"この麺屋は牛肉麵コンテストで一位を取り、そのためより多くの客を引きつけた。","e":"This noodle shop won first place in a beef noodle competition, and as a result attracted more customers.","k":"이 국수집은 우육면 대회에서 1등을 해서, 그 결과 더 많은 손님을 끌어들였다."},{"z":"他每次上課都遲到，<em>因此</em>老師對他印象不太好。","py":"Tā měicì shàngkè dōu chídào, yīncǐ lǎoshī duì tā yìnxiàng bú tài hǎo.","j":"彼は授業のたびに遅刻するので、そのため先生の彼に対する印象はあまり良くない。","e":"He is late for class every time, so the teacher doesn't have a very good impression of him.","k":"그는 수업 때마다 지각해서, 그 때문에 선생님이 그에 대해 별로 좋은 인상을 갖고 있지 않다."}]},
{"id":"g4-365","cat":"副詞","t":"甚至（於）","g":{"j":"〜さえ、〜すら","e":"even (to an extreme degree)","k":"심지어 ~조차"},"p":{"j":"A，甚至（於）＋B","e":"A, 甚至(於) + B","k":"A, 甚至(於) + B"},"ex":{"j":"「甚至」は一連の例の中で最も極端・意外な事例を挙げて強調する副詞で、「連…都/也」と一緒に使われることが多い。「甚至於」は書面語でよりフォーマル。単純な「連」だけの文とは強調の強さが違う。","e":"\"甚至(於)\" highlights the most extreme or surprising item among a series, often paired with \"連…都/也\". \"甚至於\" is the more formal written variant. It carries stronger emphasis than \"連\" alone.","k":"\"甚至(於)\"는 일련의 예시 중 가장 극단적이거나 의외인 경우를 강조하는 부사로, \"連…都/也\"와 자주 함께 쓰인다. \"甚至於\"는 더 격식적인 문어체이며, \"連\"만 쓸 때보다 강조가 강하다."},"eg":[{"z":"妹妹很怕黑，<em>甚至</em>連晚上睡覺都要開燈。","py":"Mèimei hěn pà hēi, shènzhì lián wǎnshang shuìjiào dōu yào kāidēng.","j":"妹はとても暗いのが怖くて、夜寝るときでさえ電気をつけなければならない。","e":"My little sister is very afraid of the dark — she even needs to keep the light on when sleeping at night.","k":"여동생은 어둠을 매우 무서워해서, 심지어 밤에 잠을 잘 때도 불을 켜야 한다."},{"z":"這個城市的交通很方便，<em>甚至</em>半夜都有公車可以搭。","py":"Zhège chéngshì de jiāotōng hěn fāngbiàn, shènzhì bànyè dōu yǒu gōngchē kěyǐ dā.","j":"この都市の交通はとても便利で、真夜中でさえバスに乗ることができる。","e":"Transportation in this city is very convenient — there are even buses you can take in the middle of the night.","k":"이 도시의 교통은 매우 편리해서, 심지어 한밤중에도 탈 수 있는 버스가 있다."}]},
{"id":"g4-366","cat":"特殊構文","t":"任何","g":{"j":"どんな〜でも","e":"any","k":"어떤 ~라도"},"p":{"j":"任何＋名詞（＋都/也）＋動詞","e":"任何 + N (+ 都/也) + V","k":"任何 + 명사 (+ 都/也) + 동사"},"ex":{"j":"「任何」は「どんな〜でも」という意味で、後ろに「都」「也」を伴って全面否定・全面肯定を示す。「甚麼」と違い、特定のものを指さず全体を包括する点に注意。","e":"\"任何\" means \"any/whatever,\" typically paired with \"都\" or \"也\" to express totality. Unlike \"什麼\", it doesn't ask about identity but asserts inclusiveness across all cases—a common mistake is omitting 都/也.","k":"\"任何\"는 \"어떤 ~라도\"라는 뜻으로 뒤에 \"都/也\"와 함께 쓰여 예외 없음을 나타낸다. \"什麼\"와 달리 특정 대상을 묻지 않고 전체를 포괄하므로 都/也를 빠뜨리지 않도록 주의해야 한다."},"eg":[{"z":"做<em>任何</em>重大的決定以前，都應該要經過仔細的思考。","py":"Zuò rènhé zhòngdà de juédìng yǐqián, dōu yīnggāi yào jīngguò zǐxì de sīkǎo.","j":"重要な決定をする前には、どんなことでもよく考えるべきだ。","e":"Before making any major decision, one should think carefully.","k":"어떤 중대한 결정을 내리기 전에는 신중하게 생각해야 한다."},{"z":"這件事很重要，<em>任何</em>人都不能馬虎。","py":"Zhè jiàn shì hěn zhòngyào, rènhé rén dōu bùnéng mǎhu.","j":"これはとても重要なことだから、誰であっていい加減にしてはいけない。","e":"This matter is very important; no one can be careless about it.","k":"이 일은 매우 중요해서 누구도 소홀히 해서는 안 된다."}]},
{"id":"g4-367","cat":"特殊構文","t":"以上","g":{"j":"以上（前述の内容）","e":"the above","k":"이상(위에서 언급한 것)"},"p":{"j":"由以上＋（內容），...／以上是＋（內容）","e":"由以上 + [content], ... / 以上是 + [content]","k":"由以上 + (내용), .../ 以上是 + (내용)"},"ex":{"j":"「以上」は前に述べた内容全体を指し、文頭で「由以上…」「以上是…」の形でまとめに使う。数字の後の「以上」(〜以上、数量)とは意味が違うので混同しないよう注意。","e":"\"以上\" refers back to everything stated previously, often opening a summary as \"由以上...\" or \"以上是...\". Don't confuse it with the \"以上\" after numbers meaning \"or more,\" which is a different usage.","k":"\"以上\"은 앞서 말한 내용 전체를 가리키며 \"由以上…\", \"以上是…\" 형태로 요약할 때 쓴다. 숫자 뒤에 붙어 \"~이상(수량)\"을 뜻하는 以上과는 다른 용법이므로 혼동하지 않도록 주의한다."},"eg":[{"z":"由<em>以上</em>的報告，我們可以知道不同地區學生的學習差異。","py":"Yóu yǐshàng de bàogào, wǒmen kěyǐ zhīdào bùtóng dìqū xuéshēng de xuéxí chāyì.","j":"以上の報告から、地域によって学生の学習に差があることが分かる。","e":"From the above report, we can see that students in different regions learn differently.","k":"이상의 보고에서 우리는 지역마다 학생들의 학습 차이가 있다는 것을 알 수 있다."},{"z":"<em>以上</em>是今天會議的重點，大家有問題嗎？","py":"Yǐshàng shì jīntiān huìyì de zhòngdiǎn, dàjiā yǒu wèntí ma?","j":"以上が今日の会議の要点です。皆さん、質問はありますか。","e":"The above is the key points of today's meeting. Does anyone have questions?","k":"이상이 오늘 회의의 요점입니다. 여러분 질문 있으신가요?"}]},
{"id":"g4-368","cat":"介詞","t":"（在）......方面","g":{"j":"〜の面では","e":"in terms of / regarding","k":"~방면에서는"},"p":{"j":"（在）＋名詞＋方面","e":"(在) + N + 方面","k":"(在) + 명사 + 方面"},"ex":{"j":"「（在）……方面」は話題となる範囲・分野を限定する表現で、「關於」より客観的な分野・領域を示すのに使う。「在」は省略可能だが、文頭に置くとより自然。","e":"\"（在）...方面\" narrows the topic to a specific area or aspect, often more neutral/objective than \"關於\". \"在\" can be omitted, but including it at the start of the clause sounds more natural.","k":"\"（在）……方面\"은 화제의 범위나 분야를 한정하는 표현으로 \"關於\"보다 좀 더 객관적인 영역·분야를 나타낼 때 쓴다. \"在\"는 생략 가능하지만 문두에 두면 더 자연스럽다."},"eg":[{"z":"除了運動，爸爸<em>在飲食方面</em>也非常注意。","py":"Chúle yùndòng, bàba zài yǐnshí fāngmiàn yě fēicháng zhùyì.","j":"運動以外に、お父さんは食事の面でもとても気をつけている。","e":"Besides exercise, Dad is also very careful about his diet.","k":"운동 외에도 아버지는 음식 방면에서도 매우 신경을 쓰신다."},{"z":"<em>在學習方面</em>，姊姊一直都很努力。","py":"Zài xuéxí fāngmiàn, jiějie yìzhí dōu hěn nǔlì.","j":"勉強の面では、姉はずっと頑張っている。","e":"When it comes to studying, my older sister has always worked hard.","k":"공부 방면에서는 언니가 늘 열심히 해 왔다."}]},
{"id":"g4-369","cat":"介詞","t":"關於","g":{"j":"〜について","e":"about / regarding","k":"~에 관하여"},"p":{"j":"關於＋名詞，...／N1＋關於＋N2＋的＋N3","e":"關於 + N, ... / N1 + 關於 + N2 + 的 + N3","k":"關於 + 명사, ..."},"ex":{"j":"「關於」は話題・テーマを導く前置詞で、文頭に置いて主題を提示することが多い。「關於……的＋名詞」の形で名詞を修飾することもできる。「（在）……方面」より範囲は広く、話題全般を指せる。","e":"\"關於\" introduces a topic and often opens the sentence to set the theme; it can also modify a noun as \"關於...的+N\". It covers a broader scope than \"（在）...方面\", which narrows to a specific aspect.","k":"\"關於\"는 화제나 주제를 이끄는 전치사로 문두에서 주제를 제시하는 경우가 많다. \"關於……的+명사\" 형태로 명사를 수식할 수도 있으며, 특정 방면을 한정하는 \"（在）……方面\"보다 범위가 더 넓다."},"eg":[{"z":"張老師寫了一篇<em>關於</em>梵谷作品欣賞的文章。","py":"Zhāng lǎoshī xiěle yì piān guānyú Fàngāo zuòpǐn xīnshǎng de wénzhāng.","j":"張先生は、ゴッホの作品鑑賞についての文章を一篇書いた。","e":"Teacher Zhang wrote an article about appreciating Van Gogh's works.","k":"장 선생님은 반 고흐 작품 감상에 관한 글을 한 편 썼다."},{"z":"這是一本<em>關於</em>臺灣歷史的書。","py":"Zhè shì yì běn guānyú Táiwān lìshǐ de shū.","j":"これは台湾の歴史についての本だ。","e":"This is a book about Taiwan's history.","k":"이것은 대만 역사에 관한 책이다."}]},
{"id":"g4-370","cat":"介詞","t":"以/從......來看","g":{"j":"〜から見ると","e":"judging from / looking at ...","k":"~로 보면"},"p":{"j":"以/從＋名詞＋來看，...","e":"以/從 + N + 來看, ...","k":"以/從 + 명사 + 來看, ..."},"ex":{"j":"「以/從……來看」は「ある観点・基準に立って判断すると」という意味で、後ろに評価や結論の文が続く。「以」は基準・視点を示す名詞に、「從」は出発点となる角度に使われやすいが、実際はほぼ交換可能。","e":"\"以/從...來看\" means \"judging from/from the perspective of...\", followed by an evaluation or conclusion. \"以\" tends to mark a standard or criterion while \"從\" marks a starting angle, but in practice the two are largely interchangeable.","k":"\"以/從……來看\"는 \"어떤 관점·기준에서 보면\"이라는 뜻으로 뒤에 평가나 결론이 이어진다. \"以\"는 기준을, \"從\"은 출발점이 되는 관점을 나타내는 경향이 있지만 실제로는 거의 서로 바꿔 쓸 수 있다."},"eg":[{"z":"得到這份工作的時候，我覺得<em>以薪水來看</em>，算是相當不錯。","py":"Dédào zhè fèn gōngzuò de shíhòu, wǒ juéde yǐ xīnshuǐ láikàn, suànshì xiāngdāng búcuò.","j":"この仕事を得たとき、給料から見ればかなり良いと思った。","e":"When I got this job, I felt that, judging from the salary, it was quite good.","k":"이 일자리를 얻었을 때 나는 월급으로 보면 상당히 괜찮다고 생각했다."},{"z":"<em>從穩定性來看</em>，這間公司值得投資。","py":"Cóng wěndìngxìng láikàn, zhè jiān gōngsī zhíde tóuzī.","j":"安定性から見れば、この会社は投資する価値がある。","e":"Judging from its stability, this company is worth investing in.","k":"안정성으로 보면 이 회사는 투자할 가치가 있다."}]},
{"id":"g4-371","cat":"補語","t":"V 得/不 來","g":{"j":"気が合う/合わない","e":"get along (or not) with","k":"잘 맞다/안 맞다"},"p":{"j":"V ＋ 得/不 ＋ 來","e":"V + 得/不 + 來","k":"V + 得/不 + 來"},"ex":{"j":"「V得來」は人や物事との相性・適合がうまくいくことを表し、「V不來」はうまくいかないことを表す。可能補語の一種で、能力ではなく「合う・合わない」という相性の判断に使われる点が他の可能補語と異なる。","e":"\"V得來\" expresses that something/someone is compatible or works out well, while \"V不來\" expresses incompatibility. As a potential complement, it judges compatibility rather than physical ability, unlike complements such as \"V得動\".","k":"'V得來'는 서로 잘 맞음을, 'V不來'는 잘 맞지 않음을 나타낸다. 가능보어의 일종으로, 능력이 아니라 '어울림, 궁합'을 판단할 때 쓰인다는 점이 다른 가능보어와 다르다."},"eg":[{"z":"暑假的實習生和我們年紀差不多大，大家都很<em>合得來</em>。","py":"Shǔjià de shíxíshēng hàn wǒmen niánjì chàbuduō dà, dàjiā dōu hěn hédelái.","j":"夏休みのインターン生は私たちと年齢がそれほど変わらず、みんなとても気が合う。","e":"The summer interns are about the same age as us, so everyone gets along really well.","k":"여름방학 인턴들은 우리와 나이가 비슷해서 다들 아주 잘 지낸다."},{"z":"他脾氣不好，跟誰都<em>合不來</em>。","py":"Tā píqì bù hǎo, gēn shéi dōu hébulái.","j":"彼は気性が悪くて、誰とも気が合わない。","e":"He has a bad temper, so he doesn't get along with anyone.","k":"그는 성격이 안 좋아서 누구와도 잘 지내지 못한다."}]},
{"id":"g4-372","cat":"補語","t":"V下","g":{"j":"(結果を)固定する・完了する","e":"complete/fix an action (result)","k":"동작을 확정·완료하다"},"p":{"j":"V ＋ 下","e":"V + 下","k":"V + 下"},"ex":{"j":"動詞の後に「下」をつけて、その動作の結果が固定・確定したことを表す(所有・契約・記録などが定着するイメージ)。方向補語の「下來/下去」と違い、単独の「下」は移動の方向ではなく結果の確定を示す点に注意。","e":"Adding \"下\" after a verb shows the result of the action becomes fixed or settled (e.g., ownership, an agreement). Unlike the directional complements \"下來/下去\", a bare \"下\" here marks a settled result rather than physical direction.","k":"동사 뒤에 '下'를 붙여 그 동작의 결과가 확정·고정됨을 나타낸다(소유, 계약 등이 정착되는 느낌). 방향보어 '下來/下去'와 달리 단독의 '下'는 이동 방향이 아니라 결과의 확정을 나타낸다는 점에 주의."},"eg":[{"z":"他以很低的價格<em>買下</em>這棟房子。","py":"Tā yǐ hěn dī de jiàgé mǎixià zhè dòng fángzi.","j":"彼はとても安い価格でこの家を買い取った。","e":"He bought this house for a very low price.","k":"그는 아주 낮은 가격에 이 집을 사들였다."},{"z":"他們<em>簽下</em>一份三年的合約。","py":"Tāmen qiānxià yí fèn sān nián de héyuē.","j":"彼らは3年間の契約を結んだ。","e":"They signed a three-year contract.","k":"그들은 3년짜리 계약을 체결했다."}]},
{"id":"g4-373","cat":"副詞","t":"不免","g":{"j":"どうしても〜してしまう","e":"inevitably, unavoidably","k":"아무래도 ~하게 되다"},"p":{"j":"(狀況) ＋ 不免 ＋ V","e":"(Situation) + 不免 + V","k":"(상황) + 不免 + V"},"ex":{"j":"「不免」は書き言葉的な副詞で、ある状況では望まなくても自然にそうなる、という客観的な必然性を表す。話し言葉の「難免」とほぼ同義だが、「不免」の方がやや硬い書面語。","e":"\"不免\" is a somewhat formal/written adverb meaning something naturally, unavoidably happens given the circumstances. It is close in meaning to the more spoken \"難免\" but \"不免\" reads slightly more literary.","k":"'不免'은 다소 문어체적인 부사로, 어떤 상황에서 원치 않아도 자연스럽게 그렇게 됨을 나타낸다. 구어의 '難免'과 뜻이 비슷하지만 '不免'이 조금 더 문어적이다."},"eg":[{"z":"生活中<em>不免</em>遇到很多問題和挑戰。","py":"Shēnghuó zhōng bùmiǎn yùdào hěn duō wèntí hàn tiǎozhàn.","j":"生活の中ではどうしても多くの問題や困難に出会ってしまう。","e":"In life, one inevitably encounters many problems and challenges.","k":"살다 보면 어쩔 수 없이 많은 문제와 도전에 부딪히게 된다."},{"z":"剛搬到新環境，<em>不免</em>會感到有點緊張。","py":"Gāng bāndào xīn huánjìng, bùmiǎn huì gǎndào yǒudiǎn jǐnzhāng.","j":"新しい環境に引っ越したばかりだと、どうしても少し緊張してしまう。","e":"Having just moved to a new environment, one can't help but feel a bit nervous.","k":"새로운 환경으로 막 이사하면 어쩔 수 없이 조금 긴장하게 된다."}]},
{"id":"g4-374","cat":"副詞","t":"不見得","g":{"j":"必ずしも〜とは限らない","e":"not necessarily","k":"반드시 ~인 것은 아니다"},"p":{"j":"A ＋ 不見得 ＋ B","e":"A + 不見得 + B","k":"A + 不見得 + B"},"ex":{"j":"「不見得」は「必ずしも〜ではない」と、一般的な思い込みや通念を部分的に否定するときに使う。「不一定」とほぼ同義で置き換え可能だが、「不見得」はやや話し言葉的で反論・訂正のニュアンスを含みやすい。","e":"\"不見得\" means \"not necessarily,\" used to partially deny a common assumption. It's nearly interchangeable with \"不一定,\" but \"不見得\" is a bit more colloquial and often carries a nuance of gently correcting someone's assumption.","k":"'不見得'는 '반드시 ~인 것은 아니다'라는 뜻으로, 일반적인 통념을 부분적으로 부정할 때 쓴다. '不一定'과 거의 같은 뜻으로 바꿔 쓸 수 있지만, '不見得'는 다소 구어적이고 상대의 생각을 살짝 정정하는 뉘앙스를 띠기 쉽다."},"eg":[{"z":"成績不好的學生，<em>不見得</em>無法獲得成功的機會。","py":"Chéngjī bù hǎo de xuéshēng, bújiànde wúfǎ huòdé chénggōng de jīhuì.","j":"成績が悪い学生でも、必ずしも成功のチャンスを得られないとは限らない。","e":"Students with poor grades won't necessarily be unable to get a chance to succeed.","k":"성적이 나쁜 학생이라고 해서 반드시 성공할 기회를 얻지 못하는 것은 아니다."},{"z":"便宜的東西<em>不見得</em>品質不好。","py":"Piányí de dōngxi bújiànde pǐnzhí bù hǎo.","j":"安いものが必ずしも品質が悪いとは限らない。","e":"Cheap things aren't necessarily of poor quality.","k":"싼 물건이라고 해서 반드시 품질이 나쁜 것은 아니다."}]},
{"id":"g4-375","cat":"否定","t":"並+不/沒","g":{"j":"実は決して〜ではない","e":"actually not at all (contrary to expectation)","k":"사실은 전혀 ~하지 않다"},"p":{"j":"並 ＋ 不/沒 ＋ VP","e":"並 + 不/沒 + VP","k":"並 + 不/沒 + VP"},"ex":{"j":"「並」は否定詞「不/沒」の前につけて、相手の予想や一般的な想定を強く打ち消し、「実はそうではない」と訂正するニュアンスを加える。単なる「不/沒」より語気が強く、反論・弁明の文脈でよく使われる。","e":"\"並\" placed before \"不/沒\" strengthens the negation, correcting an assumption by emphasizing \"that's actually not the case.\" It carries a stronger, more argumentative tone than a plain \"不/沒\" and often appears when refuting or clarifying something.","k":"'並'은 부정사 '不/沒' 앞에 놓여 상대의 예상이나 통념을 강하게 부정하며 '사실은 그렇지 않다'는 뉘앙스를 더한다. 단순한 '不/沒'보다 어조가 강하며, 반박하거나 해명하는 문맥에서 자주 쓰인다."},"eg":[{"z":"雖然他們的宗教不同，但<em>並不</em>影響他們的合作關係。","py":"Suīrán tāmen de zōngjiào bùtóng, dàn bìng bù yǐngxiǎng tāmen de hézuò guānxì.","j":"彼らの宗教は異なるが、それは彼らの協力関係にまったく影響していない。","e":"Although their religions are different, it doesn't affect their cooperative relationship at all.","k":"그들의 종교는 다르지만, 그것이 그들의 협력 관계에 전혀 영향을 주지 않는다."},{"z":"他雖然沒說什麼，但心裡<em>並沒有</em>生氣。","py":"Tā suīrán méi shuō shénme, dàn xīnlǐ bìng méiyǒu shēngqì.","j":"彼は何も言わなかったが、心の中では全く怒っていなかった。","e":"Although he didn't say anything, he wasn't angry at all inside.","k":"그는 아무 말도 하지 않았지만, 속으로는 전혀 화나지 않았다."}]},
{"id":"g4-376","cat":"副詞","t":"再也（不/沒）","g":{"j":"二度と～ない","e":"never again","k":"다시는 ~하지 않다"},"p":{"j":"再也＋不/沒＋V(＋了)","e":"zài yě + bù/méi + V (+ le)","k":"再也 + 不/沒 + V (+了)"},"ex":{"j":"「再也不/沒」は強い決意や驚きを込めて「二度と～しない/していない」と述べる表現。過去の経験には「沒」＋動詞(+過)、意志や習慣には「不」を使う。基本語法の「不再」より感情が強く、文末に「了」を伴うことが多い。","e":"\"再也不/沒\" emphasizes a strong, often emotional sense of \"never again.\" Use 沒 (+過) for past experience and 不 for future intent or habits. It's stronger in tone than the basic \"不再\" and usually ends with 了.","k":"'再也不/沒'는 '두 번 다시 ~하지 않다/않았다'라는 강한 감정을 담은 표현이다. 과거 경험에는 沒(+過), 의지나 습관에는 不를 쓴다. 기본 문법인 不再보다 어감이 강하며 문장 끝에 了를 자주 동반한다."},"eg":[{"z":"自從那次在公車上遇見王明後，我就<em>再也沒見過他了</em>。","py":"Zìcóng nà cì zài gōngchē shàng yùjiàn Wáng Míng hòu, wǒ jiù zàiyě méi jiànguò tā le.","j":"あの日バスで王明に出会ってから、私は二度と彼に会っていない。","e":"Since I ran into Wang Ming on the bus that day, I've never seen him again.","k":"그날 버스에서 왕밍을 만난 후로, 나는 다시는 그를 만나지 못했다."},{"z":"那次吵架以後，他們<em>再也沒說過話</em>。","py":"Nà cì chǎojià yǐhòu, tāmen zàiyě méi shuōguò huà.","j":"あの喧嘩以来、彼らはもう二度と話をしていない。","e":"After that argument, they never spoke to each other again.","k":"그 싸움 이후로 그들은 다시는 말을 하지 않았다."}]},
{"id":"g4-377","cat":"特殊構文","t":"沒有一M（N） 不/沒......的","g":{"j":"～ない者は一人もいない（＝全員～だ）","e":"there isn't a single one who doesn't...","k":"~하지 않는 사람(것)은 하나도 없다"},"p":{"j":"沒有一＋量詞(＋名詞)＋不/沒＋...的","e":"méiyǒu yī + M (+ N) + bù/méi + ... + de","k":"沒有一 + 양사(+명사) + 不/沒 + ... + 的"},"ex":{"j":"二重否定で「全員/すべて～だ」という強調表現。量詞は名詞に合わせて変え、文末に「的」を置くのが特徴。「每個人都」と意味は近いが、こちらは驚きや強調のニュアンスが強い。","e":"A double-negative structure meaning \"every single one is...\" The classifier changes with the noun, and the sentence ends with 的. Similar in meaning to 每個人都, but carries stronger emphasis or surprise.","k":"이중부정으로 '전부 다 ~하다'를 강조하는 표현이다. 양사는 명사에 맞춰 바뀌며 문장 끝에 的를 붙이는 것이 특징이다. 每個人都와 의미가 비슷하지만 더 강한 감정을 담는다."},"eg":[{"z":"來過這間餐廳用餐的顧客，<em>沒有一個不說好的</em>。","py":"Láiguò zhè jiān cāntīng yòngcān de gùkè, méiyǒu yí ge bù shuō hǎo de.","j":"この店で食事したことのある客は、おいしいと言わない人は一人もいない。","e":"Not a single customer who has eaten at this restaurant has failed to say it's good.","k":"이 식당에서 식사해 본 손님 중 맛있다고 말하지 않은 사람은 한 명도 없다."},{"z":"這班學生，<em>沒有一個不喜歡老師的</em>。","py":"Zhè bān xuéshēng, méiyǒu yí ge bù xǐhuān lǎoshī de.","j":"このクラスの生徒は、先生を好きではない人は一人もいない。","e":"There isn't a single student in this class who doesn't like the teacher.","k":"이 반 학생 중 선생님을 좋아하지 않는 사람은 한 명도 없다."}]},
{"id":"g4-378","cat":"介詞","t":"把......V為......","g":{"j":"～を…に定める／名づける","e":"designate/name X as Y","k":"~을 …로 정하다/이름 짓다"},"p":{"j":"把＋N1＋V為＋N2","e":"bǎ + N1 + V + wéi + N2","k":"把 + N1 + V為 + N2"},"ex":{"j":"「把」構文でN1を特定の名前・地位・結果に「定める/変える」ことを表す。動詞は「定・稱・列・訂・視」など限られた語と結びつき、「為」は省略できない。「當作」と混同しやすいが、「當作」は「～とみなす」で公式な決定を意味しない。","e":"This \"把\" structure shows that N1 is officially designated, named, or turned into N2. The verb is limited to words like 定, 稱, 列, 訂, 視, and 為 cannot be dropped. It's often confused with 當作 (\"regard as\"), which doesn't imply an official decision.","k":"'把' 구문으로 N1을 특정 이름·지위·결과로 '정하다/바꾸다'를 나타낸다. 동사는 定, 稱, 列, 訂, 視 등 제한된 단어와만 결합하며 為를 생략할 수 없다. '當作'(~로 여기다)와 혼동하기 쉬운데, 當作은 공식적 결정을 의미하지 않는다."},"eg":[{"z":"教授<em>把演講題目定為「團隊精神」</em>。","py":"Jiàoshòu bǎ yǎnjiǎng tímù dìngwéi \"Tuánduì Jīngshén\".","j":"教授は講演のテーマを「チームワーク精神」に定めた。","e":"The professor set the topic of the lecture as \"Team Spirit.\"","k":"교수는 강연 주제를 '팀워크 정신'으로 정했다."},{"z":"我們<em>把這條路命名為「幸福路」</em>。","py":"Wǒmen bǎ zhè tiáo lù mìngmíng wéi \"Xìngfú Lù\".","j":"私たちはこの道を「幸福路」と名付けた。","e":"We named this road \"Happiness Road.\"","k":"우리는 이 길을 '행복로'라고 이름 지었다."}]},
{"id":"g4-379","cat":"話しことば","t":"老實說","g":{"j":"正直に言うと","e":"honestly / to be honest","k":"솔직히 말해서"},"p":{"j":"老實說，＋文","e":"Lǎoshí shuō, + sentence","k":"老實說, + 문장"},"ex":{"j":"文頭に置いて「本音を言うと」と前置きする表現。「說實話」とほぼ同義で置き換え可能。後ろには話し手の率直な意見や、時に言いにくい事実が続くことが多い。","e":"Placed at the start of a sentence to preface an honest opinion. Nearly interchangeable with 說實話. It's usually followed by the speaker's frank opinion, sometimes something slightly awkward to say.","k":"문장 앞에 놓여 '솔직히 말하면'이라고 운을 떼는 표현이다. 說實話와 거의 같은 뜻으로 바꿔 쓸 수 있다. 뒤에는 화자의 솔직한 의견이나 말하기 껄끄러운 사실이 이어지는 경우가 많다."},"eg":[{"z":"<em>老實說</em>，這個笑話不好笑。","py":"Lǎoshí shuō, zhège xiàohuà bù hǎoxiào.","j":"正直に言うと、この笑い話は面白くない。","e":"Honestly, this joke isn't funny.","k":"솔직히 말해서, 이 농담은 재미없다."},{"z":"<em>老實說</em>，我覺得這部電影不太好看。","py":"Lǎoshí shuō, wǒ juéde zhè bù diànyǐng bú tài hǎokàn.","j":"正直に言うと、私はこの映画があまり面白くないと思う。","e":"Honestly, I don't think this movie is very good.","k":"솔직히 말해서, 나는 이 영화가 별로 재미없다고 생각한다."}]},
{"id":"g4-380","cat":"副詞","t":"據說","g":{"j":"聞くところによると／～だそうだ","e":"it is said that / reportedly","k":"듣자 하니 / ~라고 한다"},"p":{"j":"據說＋文","e":"jùshuō + sentence","k":"據說 + 문장"},"ex":{"j":"伝聞や又聞きの情報を伝える際に文頭で使う。話し手自身が確認していない情報である点がポイントで、「聽說」とほぼ同義だが「據說」の方がやや書き言葉寄り。","e":"Used at the start of a sentence to convey hearsay or secondhand information the speaker hasn't personally verified. Nearly synonymous with 聽說, but 據說 leans slightly more formal/written.","k":"문장 앞에서 전해 들은 정보, 즉 화자가 직접 확인하지 않은 내용을 전할 때 쓴다. 聽說와 거의 같은 뜻이지만 據說가 약간 더 문어체에 가깝다."},"eg":[{"z":"<em>據說</em>這個地方本來沒有湖，是大地震之後才出現的。","py":"Jùshuō zhège dìfāng běnlái méiyǒu hú, shì dà dìzhèn zhīhòu cái chūxiàn de.","j":"聞くところによると、この場所には元々湖はなく、大地震の後にできたのだそうだ。","e":"It's said that this place originally had no lake, and it only appeared after a major earthquake.","k":"듣자 하니 이곳에는 원래 호수가 없었는데, 대지진 이후에 생겨났다고 한다."},{"z":"<em>據說</em>這家店的牛肉麵是全台北最好吃的。","py":"Jùshuō zhè jiā diàn de niúròumiàn shì quán Táiběi zuì hǎochī de.","j":"聞くところによると、この店の牛肉麵は台北で一番おいしいそうだ。","e":"It's said that this shop's beef noodle soup is the best in all of Taipei.","k":"듣자 하니 이 가게의 우육면이 타이베이에서 제일 맛있다고 한다."}]},
{"id":"g4-381","cat":"話しことば","t":"我看","g":{"j":"(わたしの考えでは)〜と思う","e":"I think / In my opinion","k":"내 생각엔"},"p":{"j":"我看 ＋ (還是) ＋ 判斷・提案","e":"Wǒ kàn + judgment/suggestion","k":"我看 + 판단·제안"},"ex":{"j":"「我看」は話し手が自分の判断や提案を控えめに述べる口語表現で、「我覺得」より断定を和らげ助言のニュアンスが強い。文頭に置き、後に「還是」を伴うことが多い。","e":"'Wǒ kàn' softly gives the speaker's judgment/suggestion, close to 'I think/guess'; often paired with 還是 to soften advice, more tentative than flat 我覺得.","k":"'我看'은 화자가 자신의 판단이나 제안을 부드럽게 말할 때 쓰는 구어체 표현으로, '我覺得'보다 완곡하며 종종 '還是'와 함께 조언을 나타낸다."},"eg":[{"z":"<em>我看</em>還是早點出門，等等遲到就不好了。","py":"Wǒ kàn háishì zǎodiǎn chūmén, děngděng chídào jiù bù hǎo le.","j":"わたしはやっぱり早めに出かけたほうがいいと思う。遅れたらまずいから。","e":"I think we'd better leave early, or we'll be late.","k":"내 생각엔 그래도 일찍 나가는 게 좋겠어. 늦으면 안 좋으니까."},{"z":"<em>我看</em>你還是打電話問清楚比較好。","py":"Wǒ kàn nǐ háishì dǎ diànhuà wèn qīngchǔ bǐjiào hǎo.","j":"わたしはやっぱり電話でちゃんと確認したほうがいいと思う。","e":"I think you'd better call and ask clearly.","k":"내 생각엔 네가 전화해서 확실히 물어보는 게 나을 것 같아."}]},
{"id":"g4-382","cat":"話しことば","t":"你看","g":{"j":"見て/ねえ(注意を引く、意見を求める)","e":"Look / You see","k":"봐/있잖아"},"p":{"j":"你看 ＋ 文","e":"Nǐ kàn + sentence","k":"你看 + 문장"},"ex":{"j":"「你看」は相手の注意を引いたり、状況を指し示して意見や反応を求めたりする口語表現。文頭に置き、日本語の「ねえ、見て」「〜でしょ？」に近いニュアンスを持つ。","e":"'Nǐ kàn' draws the listener's attention to something or invites their opinion, like 'look' or 'see?'; placed at the start of a casual sentence.","k":"'你看'는 상대의 주의를 끌거나 상황을 가리키며 의견을 구할 때 쓰는 구어체 표현으로, '봐/그렇지?'에 가깝다."},"eg":[{"z":"<em>你看</em>這件事到底是怎麼回事？","py":"Nǐ kàn zhè jiàn shì dàodǐ shì zěnme huí shì?","j":"見て、この件はいったいどういうことなの？","e":"Look, what's really going on with this?","k":"봐, 이 일이 도대체 어떻게 된 거야?"},{"z":"<em>你看</em>，外面下雨了，我們得帶傘。","py":"Nǐ kàn, wàimiàn xià yǔ le, wǒmen děi dài sǎn.","j":"見て、外は雨が降っているよ。傘を持って行かなきゃ。","e":"Look, it's raining outside — we need to bring an umbrella.","k":"봐, 밖에 비가 오네. 우산을 가져가야겠어."}]},
{"id":"g4-383","cat":"話しことば","t":"這麼說","g":{"j":"つまり〜ということですね(結論を導く)","e":"So you're saying... / In that case...","k":"그럼〜라는 거네"},"p":{"j":"這麼說，＋ 結論の文","e":"Zhème shuō, + conclusion","k":"這麼說，+ 결론 문장"},"ex":{"j":"「這麼說」は相手の発言を受けて、そこから導いた結論や確認を述べる時に使う。文頭に置き、日本語の「つまり〜ということですね」に相当し、話し手自身の推論を示す。","e":"'Zhème shuō' introduces a conclusion drawn from what was just said, like 'so you're saying...'; it signals the speaker's own inference from the prior statement.","k":"'這麼說'는 상대의 말을 근거로 결론이나 확인을 이끌어낼 때 쓰며, '그럼 〜라는 거네'에 해당한다."},"eg":[{"z":"<em>這麼說</em>，我得三點以前去找他。","py":"Zhème shuō, wǒ děi sān diǎn yǐqián qù zhǎo tā.","j":"つまり、わたしは三時前に彼を訪ねに行かなきゃいけないんだね。","e":"So you're saying I have to go see him before three o'clock.","k":"그럼 내가 세 시 전에 그를 만나러 가야 한다는 거네."},{"z":"<em>這麼說</em>，你昨天根本沒去上班？","py":"Zhème shuō, nǐ zuótiān gēnběn méi qù shàngbān?","j":"つまり、あなたは昨日全然仕事に行かなかったってこと？","e":"So you're saying you didn't go to work at all yesterday?","k":"그럼 너 어제 아예 출근을 안 했다는 거야?"}]},
{"id":"g4-384","cat":"接続","t":"相反地","g":{"j":"それとは反対に/逆に","e":"On the contrary / Conversely","k":"그와는 반대로"},"p":{"j":"句子A；相反地，句子B(対照)","e":"Clause A; xiāngfǎn de, Clause B (contrast)","k":"문장A；相反地，문장B (대조)"},"ex":{"j":"「相反地」は前の内容と正反対の事柄を書き言葉で述べる接続語で、日本語の「それとは逆に」に相当する。話し言葉の「但是」より論理的・対比的な文脈で使われる。","e":"'Xiāngfǎn de' is a written connector introducing the opposite of what was just stated, like 'on the contrary'; more formal and logically contrastive than casual 但是.","k":"'相反地'는 앞 내용과 정반대되는 내용을 이어주는 문어체 접속어로, 구어적인 '但是'보다 논리적·대조적 맥락에서 쓰인다."},"eg":[{"z":"我認為父母不應該直接告訴孩子答案；<em>相反地</em>，應該讓他們有機會多嘗試。","py":"Wǒ rènwéi fùmǔ bù yīnggāi zhíjiē gàosù háizi dá'àn; xiāngfǎn de, yīnggāi ràng tāmen yǒu jīhuì duō chángshì.","j":"わたしは、親は子供に直接答えを教えるべきではないと思う。逆に、もっと試す機会を与えるべきだ。","e":"I don't think parents should tell children the answer directly; on the contrary, they should let them have more chances to try.","k":"나는 부모가 아이에게 직접 답을 알려주면 안 된다고 생각한다. 반대로 아이들에게 더 많이 시도할 기회를 줘야 한다."},{"z":"這部電影評價很好；<em>相反地</em>，續集卻讓人失望。","py":"Zhè bù diànyǐng píngjià hěn hǎo; xiāngfǎn de, xùjí què ràng rén shīwàng.","j":"この映画は評判がとてもいい。逆に、続編は人をがっかりさせた。","e":"This movie got great reviews; on the contrary, the sequel disappointed people.","k":"이 영화는 평가가 아주 좋다. 반대로 속편은 사람들을 실망시켰다."}]},
{"id":"g4-385","cat":"接続","t":"再說","g":{"j":"それに/おまけに(理由を追加)","e":"Besides / Moreover","k":"게다가"},"p":{"j":"理由A，再說 ＋ 理由B","e":"Reason A, zàishuō + Reason B","k":"이유A，再說 + 이유B"},"ex":{"j":"「再說」は既に述べた理由に加えて、さらに補強となる理由を追加する口語的接続語で、「それに/おまけに」に近い。「而且」より軽い口調で、後付けの理由を示すことが多い。","e":"'Zàishuō' adds another supporting reason on top of one already given, close to 'besides/moreover'; more casual than 而且 and often frames the added reason as secondary.","k":"'再說'는 이미 말한 이유에 덧붙여 추가 이유를 대는 구어체 접속어로, '게다가'에 가깝다. '而且'보다 가볍고 후속 이유를 나타낼 때 많이 쓴다."},"eg":[{"z":"他對看電影沒興趣，<em>再說</em>生意這麼忙，他也沒時間。","py":"Tā duì kàn diànyǐng méi xìngqù, zàishuō shēngyì zhème máng, tā yě méi shíjiān.","j":"彼は映画を見ることに興味がないし、それに商売がこんなに忙しいから時間もない。","e":"He's not interested in watching movies, besides, business is so busy that he has no time either.","k":"그는 영화 보는 데 관심이 없고, 게다가 장사가 이렇게 바빠서 시간도 없다."},{"z":"這件衣服太貴了，<em>再說</em>顏色我也不喜歡。","py":"Zhè jiàn yīfu tài guì le, zàishuō yánsè wǒ yě bù xǐhuān.","j":"この服は高すぎるし、それに色も好きじゃない。","e":"This piece of clothing is too expensive, besides, I don't like the color either.","k":"이 옷은 너무 비싸고, 게다가 색깔도 마음에 안 들어."}]},
{"id":"g4-386","cat":"接続","t":"（也/那/這）就是說","g":{"j":"つまり~ということだ","e":"that is to say","k":"즉 ~라는 것이다"},"p":{"j":"A，也/那/這就是說，B","e":"A, 也/那/這就是說, B","k":"A, 也/那/這就是說, B"},"ex":{"j":"「A，也/那/這就是說，B」で前の内容を言い換えたりまとめたりする。三つの語はほぼ同じ意味で置き換え可能。単独の「也就是說」が最も口語的でよく使われる。","e":"Used to rephrase or summarize what was just said: \"A, that is to say, B.\" 也/那/這 are largely interchangeable here; 也就是說 is the most common colloquial form.","k":"앞의 내용을 바꿔 말하거나 정리할 때 쓴다: \"A, 즉, B.\" 也/那/這는 거의 같은 뜻으로 서로 바꿔 쓸 수 있으며, 也就是說이 가장 흔히 쓰인다."},"eg":[{"z":"氣象報告說週末會有颱風，<em>也/那/這就是說</em>，我們不能去海邊了。","py":"Qìxiàng bàogào shuō zhōumò huì yǒu táifēng, yě/nà/zhè jiùshìshuō, wǒmen bùnéng qù hǎibiān le.","j":"氣象報告によると週末は台風が来るそうだ。つまり、私たちは海に行けないということだ。","e":"The weather forecast says there'll be a typhoon this weekend. In other words, we can't go to the beach.","k":"기상 예보에서 주말에 태풍이 온다고 했다. 즉, 우리는 바다에 갈 수 없다는 것이다."},{"z":"他每次都遲到，<em>這就是說</em>，他根本不在乎這個約會。","py":"Tā měi cì dōu chídào, zhè jiùshìshuō, tā gēnběn bú zàihū zhège yuēhuì.","j":"彼はいつも遅刻する。つまり、この約束をまったく気にしていないということだ。","e":"He's late every time — in other words, he doesn't care about this appointment at all.","k":"그는 매번 지각한다. 즉, 이 약속을 전혀 신경 쓰지 않는다는 것이다."}]},
{"id":"g4-387","cat":"話しことば","t":"可不是","g":{"j":"そのとおり!(相槌)","e":"exactly!/isn't that so!","k":"그러게 말이야!"},"p":{"j":"可不是！","e":"可不是！","k":"可不是！"},"ex":{"j":"相手の発言に強く同意する相槌表現で「まったくその通り」という意味。単独または短い補足を続けて使う。否定文ではなく肯定の同意を表すことに注意(可不是＝当然そうだ)。","e":"An agreement interjection meaning \"Isn't that so!/Exactly!\" — despite containing 不, it expresses strong agreement, not negation. Often stands alone or is followed by a short elaboration.","k":"상대방 말에 강하게 동의하는 맞장구 표현으로 \"정말 그렇다\"는 뜻이다. 不가 들어가지만 부정이 아니라 강한 긍정 동의를 나타낸다는 점에 유의한다."},"eg":[{"z":"<em>可不是</em>！","py":"Kěbúshì!","j":"そのとおりですね!","e":"Isn't that so! / Exactly!","k":"그러게 말이에요!"},{"z":"「今天真的好熱喔！」「<em>可不是</em>，都超過三十五度了。」","py":"\"Jīntiān zhēn de hǎo rè ō!\" \"Kěbúshì, dōu chāoguò sānshíwǔ dù le.\"","j":"「今日は本当に暑いね！」「まったくだよ、もう35度を超えてるし。」","e":"\"It's really hot today!\" \"Isn't that so! It's already over 35 degrees.\"","k":"\"오늘 진짜 덥다!\" \"그러게 말이야, 벌써 35도가 넘었어.\""}]},
{"id":"g4-388","cat":"話しことば","t":"怎麼說呢","g":{"j":"どう言えばいいかな","e":"how should I put it","k":"뭐라고 해야 할까"},"p":{"j":"怎麼說呢，……","e":"怎麼說呢, ...","k":"怎麼說呢, ..."},"ex":{"j":"質問にすぐ答えにくいときや、言葉を選びながら話すときに使う前置き表現。「そうだなあ、どう言えばいいか」という間を取る働きをする。断定を避けたい場面でよく使われる。","e":"A hesitation filler used when it's hard to answer right away or one is choosing words carefully — \"how should I put it...\" Common when the speaker wants to soften or avoid a blunt answer.","k":"바로 대답하기 어렵거나 말을 고르면서 이야기할 때 쓰는 표현으로 \"뭐라고 해야 할까\"라는 뜻의 군말이다. 단정적으로 말하기 어려운 상황에서 자주 쓰인다."},"eg":[{"z":"<em>怎麼說呢</em>，就是覺得合不來。","py":"Zěnme shuō ne, jiùshì juéde hébùlái.","j":"どう言えばいいかな、ただ性格が合わないと感じただけなんだ。","e":"How should I put it... I just feel we don't get along.","k":"뭐라고 해야 할까, 그냥 성격이 안 맞는다고 느꼈어."},{"z":"這部電影好看嗎？<em>怎麼說呢</em>，劇情普通，可是演員演得不錯。","py":"Zhè bù diànyǐng hǎokàn ma? Zěnme shuō ne, jùqíng pǔtōng, kěshì yǎnyuán yǎn de búcuò.","j":"この映画、面白かった？どう言えばいいかな、ストーリーは普通だけど、俳優の演技はなかなか良かったよ。","e":"Was the movie good? How should I put it... the plot was so-so, but the actors did a good job.","k":"이 영화 재미있었어? 뭐라고 해야 할까, 줄거리는 평범한데 배우들 연기는 꽤 좋았어."}]},
{"id":"g4-389","cat":"接続","t":"這樣一來","g":{"j":"このようにすれば","e":"this way/as a result","k":"이렇게 하면"},"p":{"j":"A，這樣一來，B","e":"A, 這樣一來, B","k":"A, 這樣一來, B"},"ex":{"j":"前の内容を受けて「そうすれば/そうなると」という結果・結論を導く。前件の行動や状況が後件の良い結果につながることを示す際によく使う。","e":"Introduces the result or consequence of what was just said: \"this way / as a result.\" Often used when a prior action leads to a positive outcome.","k":"앞 내용을 이어받아 \"이렇게 하면/이렇게 되면\"이라는 결과나 결론을 이끈다. 앞의 행동이나 상황이 좋은 결과로 이어짐을 나타낼 때 자주 쓰인다."},"eg":[{"z":"我先買好車票了，<em>這樣一來</em>，我們等一下就可以放心去買伴手禮了。","py":"Wǒ xiān mǎihǎo chēpiào le, zhèyàng yìlái, wǒmen děng yíxià jiù kěyǐ fàngxīn qù mǎi bànshǒulǐ le.","j":"私が先に切符を買っておいたよ。そうすれば、私たちはあとで安心してお土産を買いに行けるね。","e":"I already bought the tickets. This way, we can go buy souvenirs later with peace of mind.","k":"내가 먼저 표를 사 놨어. 이렇게 하면, 우리는 이따가 마음 놓고 기념품을 사러 갈 수 있어."},{"z":"老闆決定調漲薪水，<em>這樣一來</em>，員工的工作意願提高了不少。","py":"Lǎobǎn juédìng tiáozhǎng xīnshuǐ, zhèyàng yìlái, yuángōng de gōngzuò yìyuàn tígāo le bùshǎo.","j":"社長が給料を上げることを決めた。これによって、社員の仕事への意欲がかなり高まった。","e":"The boss decided to raise salaries. As a result, employees' motivation to work increased quite a bit.","k":"사장님이 월급을 올리기로 결정했다. 이렇게 되니, 직원들의 근무 의욕이 꽤 높아졌다."}]},
{"id":"g4-390","cat":"話しことば","t":"算了","g":{"j":"もういい、やめよう","e":"forget it/never mind","k":"됐어, 그만두자"},"p":{"j":"算了，……(放棄・妥協)","e":"算了, ... (giving up/compromise)","k":"算了, ... (포기·타협)"},"ex":{"j":"あきらめる・こだわるのをやめるときの表現で「もういい、やめておこう」という意味。不満や妥協を含むことが多い。「可不是」の同意とは異なり、こちらは断念・妥協を表す。","e":"Expresses giving up or dropping a matter — \"forget it, let's not bother.\" Often implies mild resignation or compromise, unlike 可不是 which expresses agreement.","k":"어떤 일을 포기하거나 더 이상 신경 쓰지 않겠다는 표현으로 \"됐어, 그만두자\"는 뜻이다. 약간의 체념이나 타협의 뉘앙스를 담고 있으며, 동의를 나타내는 可不是와는 다르다."},"eg":[{"z":"<em>算了</em>，這麼晚了你先回去吧，剩下的我來整理就可以了。","py":"Suànle, zhème wǎn le nǐ xiān huíqù ba, shèngxià de wǒ lái zhěnglǐ jiù kěyǐ le.","j":"もういいよ、こんなに遅いんだから先に帰りなよ、残りは私が片付けるから。","e":"Never mind, it's so late — you go home first, I'll take care of the rest.","k":"됐어, 이렇게 늦었으니까 너 먼저 들어가, 나머지는 내가 정리할게."},{"z":"我打了好幾次電話都沒人接，<em>算了</em>，明天再說吧。","py":"Wǒ dǎ le hǎo jǐ cì diànhuà dōu méi rén jiē, suànle, míngtiān zài shuō ba.","j":"何回も電話をかけたけど誰も出なかった。もういいや、明日にしよう。","e":"I called several times and no one answered. Forget it, let's deal with it tomorrow.","k":"전화를 여러 번 걸었는데 아무도 안 받았어. 됐어, 내일 다시 얘기하자."}]},
{"id":"l4-4","cat":"書面","t":"凡是","g":{"j":"およそ〜はすべて","e":"all / any that…","k":"무릇 ~은 모두"},"p":{"j":"凡是 X，都 Y","e":"凡是 X, 都 Y","k":"凡是 X, 都 Y"},"ex":{"j":"「Xに当てはまるものはすべて」と、ある条件を満たす全体を指す書き言葉的な表現です。後ろには必ずと言っていいほど「都」が呼応し、例外がないことを強調します。規則や告知文でよく使われます。","e":"A formal pattern meaning 'all / any that fall under X.' It is almost always echoed by 都 and stresses that there are no exceptions. Common in rules and announcements.","k":"'X에 해당하는 것은 모두'라는 뜻의 문어체 표현입니다. 뒤에 거의 반드시 都가 호응하며 예외가 없음을 강조합니다. 규정이나 공지문에 자주 쓰입니다."},"eg":[{"z":"<em>凡是</em>參加活動的人，<em>都</em>可以拿到一份小禮物。","py":"Fánshì cānjiā huódòng de rén, dōu kěyǐ nádào yí fèn xiǎo lǐwù.","j":"イベントに参加した人は誰でも、ちょっとしたプレゼントをもらえます。","e":"Everyone who takes part in the event can receive a small gift.","k":"행사에 참가하는 사람은 모두 작은 선물을 받을 수 있습니다."},{"z":"<em>凡是</em>他決定的事，很少會改變。","py":"Fánshì tā juédìng de shì, hěn shǎo huì gǎibiàn.","j":"彼が決めたことは、めったに変わりません。","e":"Anything he has decided rarely changes.","k":"그가 결정한 일은 좀처럼 바뀌지 않습니다."}]},
{"id":"l4-11","cat":"書面","t":"針對","g":{"j":"〜に対して・〜に的を絞って","e":"aimed at / targeting","k":"~을 겨냥하여"},"p":{"j":"針對 X + V","e":"針對 X + verb","k":"針對 X + 동사"},"ex":{"j":"「Xに的を絞って〜する」という意味の介詞です。特定の対象・問題に向けて対策を取ったり意見を述べたりするときに使い、ビジネスやニュースで頻出します。日本語の「〜に対して」「〜向けに」にあたります。","e":"A preposition meaning 'aimed at / targeting X.' Used when taking measures or making statements directed at a specific issue or group; very common in business and news contexts.","k":"'X를 겨냥해서 〜하다'라는 뜻의 개사입니다. 특정 대상이나 문제에 대해 대책을 세우거나 의견을 말할 때 쓰며, 비즈니스와 뉴스에서 자주 나옵니다."},"eg":[{"z":"政府<em>針對</em>年輕人推出了新的住房政策。","py":"Zhèngfǔ zhēnduì niánqīngrén tuīchū le xīn de zhùfáng zhèngcè.","j":"政府は若者向けに新しい住宅政策を打ち出しました。","e":"The government launched a new housing policy targeting young people.","k":"정부는 젊은이들을 겨냥한 새로운 주택 정책을 내놓았습니다."},{"z":"我們會<em>針對</em>客戶的需求調整方案。","py":"Wǒmen huì zhēnduì kèhù de xūqiú tiáozhěng fāng'àn.","j":"私たちはお客様のニーズに合わせてプランを調整します。","e":"We will adjust the plan according to the client's needs.","k":"우리는 고객의 요구에 맞춰 방안을 조정할 것입니다."}]},
{"id":"l4-12","cat":"書面","t":"進而","g":{"j":"さらに進んで〜する","e":"and then go further to…","k":"더 나아가 ~하다"},"p":{"j":"X，進而 Y","e":"X, 進而 Y","k":"X, 進而 Y"},"ex":{"j":"「まずXをして、それを踏まえてさらにYへ進む」という段階的な発展を表す書き言葉です。前の行動が土台となって次のより深い段階に進むニュアンスで、「さらに」「ひいては」にあたります。","e":"A written connector meaning 'and then go further to Y.' It marks progression: the first action becomes the basis for advancing to a further, deeper step.","k":"'먼저 X를 하고 그것을 바탕으로 더 나아가 Y한다'는 단계적 발전을 나타내는 문어체입니다. '나아가, 더 나아가서'에 해당합니다."},"eg":[{"z":"他先從基層做起，<em>進而</em>成為公司的高階主管。","py":"Tā xiān cóng jīcéng zuòqǐ, jìn'ér chéngwéi gōngsī de gāojiē zhǔguǎn.","j":"彼はまず現場からスタートし、さらに進んで会社の上級管理職になりました。","e":"He started from the bottom and went on to become a senior executive of the company.","k":"그는 먼저 말단부터 시작해서 더 나아가 회사의 고위 관리자가 되었습니다."},{"z":"先了解問題的原因，才能<em>進而</em>找到解決的方法。","py":"Xiān liǎojiě wèntí de yuányīn, cái néng jìn'ér zhǎodào jiějué de fāngfǎ.","j":"まず問題の原因を理解してこそ、さらに進んで解決方法を見つけられます。","e":"Only by first understanding the cause of a problem can we then go on to find a solution.","k":"먼저 문제의 원인을 이해해야 나아가 해결 방법을 찾을 수 있습니다."}]},
{"id":"l4-15","cat":"語氣","t":"未免","g":{"j":"いささか〜すぎる","e":"rather too / a bit too…","k":"아무리 그래도 너무 ~하다"},"p":{"j":"X 未免太 Y 了","e":"X 未免太 Y 了","k":"X 未免太 Y 了"},"ex":{"j":"「いくらなんでも〜すぎる」と、程度が行き過ぎていることへの控えめな批判・不満を表します。「未免太…了」の形が定番で、直接非難するより柔らかく聞こえます。客観的な「〜を免れない（難免）」と混同しないよう注意しましょう。","e":"Expresses mild criticism: 'rather too / a bit too much.' The set pattern is 未免太…了, which sounds softer than a direct complaint. Do not confuse it with 難免 ('inevitably').","k":"'아무리 그래도 너무 〜하다'라는 완곡한 비판이나 불만을 나타냅니다. 未免太…了 형태가 전형적이며 직접적인 비난보다 부드럽게 들립니다. 難免(불가피하다)과 혼동하지 마세요."},"eg":[{"z":"一杯咖啡賣三百塊，<em>未免</em>太貴了吧。","py":"Yì bēi kāfēi mài sānbǎi kuài, wèimiǎn tài guì le ba.","j":"コーヒー一杯で300元とは、いくらなんでも高すぎるでしょう。","e":"Three hundred dollars for a cup of coffee is really a bit too expensive.","k":"커피 한 잔에 300위안이라니 아무리 그래도 너무 비싸지 않나요?"},{"z":"你這樣說他，<em>未免</em>有點過分。","py":"Nǐ zhèyàng shuō tā, wèimiǎn yǒudiǎn guòfèn.","j":"彼のことをそんなふうに言うのは、いささか言い過ぎです。","e":"Talking about him like that is rather going too far.","k":"그를 그렇게 말하는 것은 좀 지나친 감이 있습니다."}]}
];
if (typeof window !== "undefined") window.GRAMMAR_L4 = GRAMMAR_L4;
